COLLDATA("asabahur","ur",[[9314,"§۹۳۵۱ ۔ یسار مولیٰ آل عمر\n(1) ابن عمیر الثقفی۔ مستغفری نے طائف کے غلاموں میں سے نکلنے والوں میں ان کا ذکر کیا ہے کہ آپ نے انہیں آزاد کر دیا۔ بعد میں انہوں نے بنی عقیل میں شادی کر لی۔ حجاج(2) کے گورنر ہیں، نوے(۹۰) سے زیادہ اولادیں ہوئیں۔\nمیں کہتا ہوں: احتمال ہے پہلے والے ہوں۔","",{"fn":"(1) اسد الغابہ (۵۶۲۸) تجرید (۱۴۲/۲)\n(2) اسد الغابہ (۳۵۸/۴)"}],[9315,"§۹۳۵۲ ۔ یاسر\n(1) مولیٰ فضالہ بن ہلال۔ ابن مندہ نے مسلم کے والد سے انہیں رلا ملا دیا ہے اور ابو عمر(2) نے دونوں میں فرق کیا ہے کہ انہوں نے اور ان کے مولا نے نبی صلی اللہ علیہ وسلم سے بیعت کی، یہی درست لگتا ہے۔ کیونکہ ان کا نسب مزنی بتاتے ہیں۔ چنانچہ ابو بکر بن ابی شیبہ عن عبد اللہ بن موسیٰ عن عبد اللہ بن مسلم بن یسار المزنی عن ابیہ عن جدہ روایت کی ہے کہ میں اپنے مولا فضالہ بن ہلال کے ساتھ حجۃ الوداع کے لیے نکلا۔(3)","",{"fn":"(1) اسد الغابہ (۵۶۲۵) استیعاب (۲۸۳۷) تجرید (۱۴۲/۲)\n(2) استیعاب (۱۴۵/۴)\n(3) اتحاف السادۃ (۳۵۲/۵)"}],[9316,"§۹۳۵۳ ۔ یُسیر بن جابر العتکی\nابن شاہین نے یہاں ان کا ذکر کیا ہے، حرف باء میں تذکرہ ہو چکا ہے۔"],[9317,"§۹۳۵۴ ۔ یُسیر بن حارث العبسی\n(1) باء میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۲) تجرید (۱۴۳/۲)"}],[9318,"§۹۳۵۵ ۔ یُسیر\nتصغیر ہے، یہ ابن عروہ ہیں اسیر میں ذکر ہوا ہے۔"],[9319,"§۹۳۵۶ ۔ یُسیر بن عمرو\n(1) ابن سیار بن درمکہ، جو سیار کی والدہ ہیں۔ وہ بنت عبد اللہ بن سعید بن مرہ بن ذہل بن شیبان ہیں، رہے ابو یسار تو وہ بنی مزید بن الاحجم بن سعید بن مرہ سے تعلق رکھتے ہیں۔ ابن کلبی نے ان کا ذکر کیا ہے کہ صحابی ہیں، انہیں اسیر بھی کہا جاتا ہے۔ بعض نے انہیں اسیر بن عمرو سے ملا دیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۳) استیعاب (۲۸۴۰) تجرید (۱۴۳/۲)"}],[9320,"§۹۳۵۷ ۔ یَعفر\n(1) بقول بعض: یعفور بن عریب بن عبد کلال الرعینی التقبانی۔ ابن یونس نے ان کا ذکر کیا ہے کہ لوگوں کا گمان ہے فتح مصر میں شریک ہوئے، بحر کے حالات میں لکھتے ہیں: یعفر کو آنے کی سعادت حاصل ہے۔","",{"fn":"(1) تجرید (۱۴۳/۲)"}],[9321,"§۹۳۵۸ ۔ یعقوب بن الحصین\n(1) بقول ابن السکن: ان سے ایک غیر مشہور حدیث مروی ہے۔ ابن ابی خیثمہ، بغوی، ابن قانع، ابن شاہین اور ابن السکن وغیرہ نے بروایت عبد الوہاب بن مجاہد عن ابیہ عن یعقوب بن الحصین روایت کی ہے، فرمایا: مجھے لگتا ہے کہ میں اب بھی رسول اللہ صلی اللہ علیہ وسلم کے رخسار دیکھ رہا ہوں آپ دائیں بائیں سلام پھیر رہے ہیں۔ آپ بلند آواز سے سلام پھیرتے تھے۔ ابو عمر(2)(3) کا بیان ہے، اس میں ابن مجاہد جو ضعیف راوی ہے منفرد ہے۔ یحییٰ بن مخلد نے یہ روایت نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۷) استیعاب (۲۸۴۳) تجرید (۱۴۳/۲)\n(2) جامع المسانید (۴۵۷/۱۲)\n(3) استیعاب (۱۴۷/۴)"}],[9322,"§۹۳۵۹ ۔ یعقوب بن زمعہ الاسدی\n(1) عبد اللہ بن عمرو کی حدیث میں منقطع سند سے ان کا ذکر ملتا ہے۔ فرماتے ہیں: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ یہاں کی کسی وادی میں نماز پڑھنا چاہتے تھے۔ آپ کھڑے ہوئے اور ہم بھی کھڑے ہو گئے۔ اتنے میں شعب ابی ذئب سے ایک گدھا نکلا، آپ صلی اللہ علیہ وسلم رک گئے اور تکبیر نہیں کہی اور بنی اسد کے یعقوب بن زمعہ کو اس کی طرف روانہ کیا یہاں تک کہ انہوں نے اسے لوٹا دیا۔ اسے امام احمد رحمہ اللہ نے عن عبد الرزاق عن ابن جریج، عمرو بن شعیب، عن عبد اللہ بن عمرو اسی اسناد سے نقل کیا ہے اور ابن ابی عمر نے عن ہشام ابن سلیمان عن ابن جریج نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۸) تجرید (۱۴۳/۲)"}],[9323,"§۹۳۶۰ ۔ یعقوب القبطی\n(1) مولیٰ بنی فہر۔ ابن یونس نے ان کا ذکر کیا ہے کہ مقوقس نے ماریہ رضی اللہ عنہا کے ساتھ بھیجا تھا۔ بقول بعض: صحابی ہیں۔ ایک قول ہے: جب اسلام لائے تو بنی فہر سے موالات کر لی۔ میں نے سعید بن عفیر کی کتاب میں دیکھا ہے کہ یعقوب الفہری سے مروی ہے، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو دیکھا اور آپ صلی اللہ علیہ وسلم کے ساتھ صبح کی نماز پڑھی میں نے آپ سے زیادہ اچھی کسی کی قراءت نہیں سنی۔ ابن یونس فرماتے ہیں: مجھے یہ حدیث سوائے ابن عفیر کے کسی کی کتاب میں نہیں ملی۔ جسے مجھ سے حسین بن زید نے عن اسد بن سعید عن کثیر بن عفیر نقل کی ہے۔","",{"fn":"(1) تجرید (۱۴۳/۲)"}],[9324,"§۹۳۶۱ ۔ یعقوب القبطی (دوسرے)\n(1) ان کے مولا نے مدبر بنا کر آزاد کر دیا تھا، تو نبی صلی اللہ علیہ وسلم نے انہیں فروخت کر دیا تاکہ ان کا قرض ادا ہو جائے۔ مسلم کی روایت میں جو بطریق ابو الزبیر عن جابر مروی ہے۔ ان کا نام آیا ہے کہ ابو مذکور انصاری نے یعقوب قبطی کو خرید کر پھر مدبر بنا کر آزاد کر دیا (جب ان کی وفات ہوئی تو) نبی صلی اللہ علیہ وسلم نے پوچھا: کیا اس کے علاوہ ان کا کوئی مال ہے؟ لوگوں نے عرض کی: نہیں۔ تو آپ نے انہیں نعیم بن عبد اللہ(2) کے ہاتھ فروخت کر دیا۔ حدیث صحیحین میں ہے اور لیث کی روایت عن ابی الزبیر عن اشیم مروی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۹) تجرید (۱۴۳/۲)\n(2) بخاری کتاب کفارات الایمان باب عتق المدبر و ام الولد والمکاتب فی الکفارۃ و عتق ولد الزنا (۶۷۱۶) مسلم (۵۸)"}],[9325,"§۹۳۶۲ ۔ یعلی بن امیہ\n(1) ابن ابی عبیدہ بن ہمام بن الحارث التیمی الحنظلی، قریش کے حلیف، انہی کو یعلی بن منیہ کہا جاتا ہے، جو ان کی والدہ ہیں۔ بقول بعض: ان کی دادی ہیں جس پہ الدارقطنی نے اعتماد کیا ہے، لکھتے ہیں: وہ منیہ بنت حارث بن جابر، امیہ کی والدہ ہیں۔ یعلی کے والد اور عوام کی والدہ ہیں جو زبیر کے والد ہیں۔ یہ زبیر اور یعلی کی دادی ہیں۔ انہیں روایت حاصل ہے اور ان کا ذکر ملتا ہے ان کی کنیت ابو خلف ہے یا ابو خالد یا ابو صفوان ہے۔ مدائنی عن سلمہ بن محارب عن عوف الاعرابی روایت کرتے ہیں کہ سیدنا ابو بکر نے ارتداد کے فتنہ میں یعلی کو حلوان کا گورنر بنایا، پھر وہ سیدنا عمر رضی اللہ عنہ کی طرف سے یمن کے کسی علاقے کے گورنر رہے۔ وہاں اپنے لیے ایک چراگاہ بنائی تو آپ نے انہیں معزول کر دیا۔ پھر سیدنا عثمان رضی اللہ عنہ کی طرف سے صنعاء یمن کے گورنر مقرر ہوئے۔ اور جس سال شہادت عثمان رضی اللہ عنہ ہوئی حج کیا۔ پھر جنگ جمل میں سیدہ عائشہ رضی اللہ عنہا کا ساتھ دیا اور صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ رہے۔ بقول بعض: اسی میں شہید ہوئے۔\nابن عساکر نے یہ بات ابو حسان الزیادی سے نقل کی ہے لیکن اسے بعید سمجھا ہے۔ نسائی کی روایت سے پتہ چلتا ہے ان کی وفات تاخیر سے ہوئی۔ یعلی بن امیہ سے مروی ہے میں عقبہ بن ابی سفیان کے پاس ان کی آخری گھڑی میں آیا تو انہوں نے بواسطہ جبیب رضی اللہ عنہ مجھ سے حدیث بیان کی۔ خلیفہ وغیرہ کا بیان ہے عقبہ ۴۴ھ میں فوت ہوئے۔ حضور نبی صلی اللہ علیہ وسلم، سیدنا عمر اور عقبہ بن ابی سفیان رضی اللہ عنہم سے روایت کرتے ہیں۔ ان سے ان کی اولاد صفوان، عثمان، محمد، عبد الرحمن، پوتے صفوان بن عبد اللہ بن یعلی، عطاء مجاہد وغیرہ روایت کرتے ہیں۔ بقول ابن سعد:(2) حنین، طائف اور تبوک میں شریک ہوئے۔ بقول حاکم نجران پر سیدنا عمر رضی اللہ عنہ کے گورنر مقرر تھے۔","",{"fn":"(1) اسد الغابہ (۵۶۴۰) استیعاب (۲۸۴۴) تجرید (۱۴۴/۲)\n(2) الطبقات الکبریٰ (۴۵۶/۵)"}],[9326,"§۹۳۶۳ ۔ یعلی بن جاریہ ثقفی\n(1) بنی زہرہ بن کلاب کے حلیف۔ ابو عمر(2) نے بحوالہ ابو معشر ان کا ذکر کیا ہے کہ جنگ یمامہ میں شہید ہوئے، لکھتے ہیں: محمد ابن اسحاق نے ان کا نام یحییٰ بن جاریہ بتایا ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۵۶۴۱) استیعاب (۲۸۴۵) تجرید (۱۴۴/۲)\n(2) استیعاب (۱۴۹/۴)"}],[9327,"§۹۳۶۴ ۔ یعلی سیابہ\n(1) وہی ابن مرہ۔ ابو حاتم،(2) ابن قانع اور طبرانی(3) نے دونوں میں فرق کیا ہے۔ ابن حبان کہتے ہیں: جو یعلی بن مرہ کو یعلی ابن سیابہ کہتا ہے اسے وہم ہوا ہے۔ پھر خود لکھتے ہیں: یعلی بن سیابہ۔ بقول بعض: صحابی ہیں۔","",{"fn":"(1) تجرید (۱۴۴/۲)\n(2) الجرح والتعدیل (۳۰۱/۹)\n(3) المعجم الکبیر (۲۷۵/۲۲)"}],[9328,"§۹۳۶۵ ۔ یعلی بن مرّہ\n(1) ابن وہب بن جابر بن عتاب بن مالک بن کعب بن عمرو بن سعد بن عوف بن ثقیف ثقفی ابو المرازم۔ یہی یعلی بن سیابہ ہیں۔ سیابہ ان کی والدہ کا نام ہے۔ بقول یحییٰ بن معین: خیبر، بیعت رضوان، فتح مکہ، غزوہ ہوازن اور طائف میں شریک ہوئے۔ بقول ابو عمر:(2) افضل صحابہ رضی اللہ عنہم میں سے تھے۔ نبی صلی اللہ علیہ وسلم سے کئی احادیث روایت کی ہیں۔ سیدنا علی رضی اللہ عنہ سے بھی روایت کرتے ہیں۔ ان سے ان کے دونوں فرزند عبد اللہ اور عثمان، نیز راشد بن سعد سعید بن راشد کے دادا اور عبد اللہ بن حفص بن نہیک وغیرہ روایت کرتے ہیں۔ ابن سعد لکھتے ہیں: نبی صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ ثقیف انگوری باغ کاٹ ڈالیں تو انہوں نے کاٹ دیئے۔(3)","",{"fn":"(1) اسد الغابہ (۵۶۴۴) استیعاب (۲۸۴۷) تجرید (۱۴۴/۲)\n(2) استیعاب (۱۴۹/۴)\n(3) جامع المسانید والسنن (۴۷۵/۱۲)"}],[9329,"§۹۳۶۶ ۔ یعلی العامری\n(1) طبرانی، ابن شاہین(2) ابو عمر عسکری نے ان میں اور یعلی بن مرہ ثقفی میں فرق کیا ہے۔ بقول بعض: دونوں ایک ہیں۔ ان کے نسب میں اختلاف ہے۔ حدیث سے ایک ہونے کی تائید ہوتی ہے۔ ابن قانع اور طبرانی(3) کی روایت میں یعلی بن مرہ لکھا ہے۔ ابو عمر کا بیان ہے اس میں اختلاف ہے کہ یعلی بن مرہ ثقفی ہیں یا عامری۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۶۴۳) استیعاب (۲۸۴۸) تجرید (۱۴۴/۲)\n(2) استیعاب (۱۴۹/۴)\n(3) المعجم الکبیر (۲۷۳/۲۲)"}],[9330,"§۹۳۶۷ ۔ یَعمَر\n(1) بنی سعد بن ہذیم کے فرد، ابو خزامہ کے والد کسی نے ایک روایت میں ان کا نام بتایا ہے جبکہ اکثر میں مبہم ہے۔ بغوی کی روایت ہے کہ ابو خزامہ بن یعمر بحوالہ اپنے والد نقل کرتے ہیں، انہوں نے عرض کی: اللہ کے رسول! جو دم ہم کرتے ہیں اس کے بارے میں آپ کا کیا ارشاد ہے؟ (حدیث)(2)","",{"fn":"(1) اسد الغابہ (۵۶۴۶) استیعاب (۲۸۵۵) تجرید (۱۴۴/۲)\n(2) ترمذی کتاب الطب باب ما جاء فی الرقی والادویۃ (۲۰۶۵، ۲۱۴۸) ابن ماجہ (۳۴۳۷) المستدرک (۴۰۲/۴) المعجم الکبیر (۲۱۵/۳) مجمع الزوائد (۸۵/۵)"}],[9331,"§۹۳۶۸ ۔ یعیش ذوالغرۃ الجہنی\n(1) اونٹوں کا گوشت کھانے کی وجہ سے وضو کرنے کے بارے میں ان کی ایک حدیث ہے۔ ترمذی نے بلا نام ان کا ذکر کیا ہے جبکہ ابن السکن نے ان کا نام بتایا ہے کہ یعیش جہنی جو ذو الغرۃ سے مشہور ہیں سے مروی ہے ایک دیہاتی آ کر کہنے لگا: کیا آپ اونٹوں کا گوشت کھانے کے بعد وضو کرتے ہیں؟ آپ نے فرمایا: ہاں! ابن شاہین(2) نے اسی سند سے ان کا نام بیان کیا ہے ان کا سیاق اس سے مکمل ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۴۷) استیعاب (۲۸۵۰) تجرید (۱۴۴/۲)\n(2) مسند احمد (۶۷/۴) (۱۱۲/۵) المعجم الکبیر (۷۰۹/۲۲) مجمع الزوائد (۲۵۰/۱) شرح المعانی (۷۰/۱)"}],[9332,"§۹۳۶۹ ۔ یعیش بن طخفہ الغفاری\n(1) بقول ابن سعد: شامی ہیں۔ مصریوں سے ان کی حدیث روایت کی جاتی ہے۔ پھر بطریق ابن لہیعہ بحوالہ یعیش الغفاری یہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم ایک اونٹنی کے پاس آ کر فرمانے لگے: اس کا دودھ کون دوہے گا؟ تو ایک صاحب اٹھے، آپ نے فرمایا: کیا نام ہے؟ کہا: مرہ۔ فرمایا: بیٹھ جاؤ۔ پھر دوسرا اٹھا تو پوچھا: کیا نام ہے؟ کہا: جمرہ۔ فرمایا: بیٹھ جاؤ، اتنے میں تیسرا شخص کھڑا ہوا، آپ نے فرمایا: کیا نام ہے؟ عرض کی: یعیش۔ فرمایا: دوہو! ابن قانع(2) ایک اور طریق سے عن ابن لہیعہ نقل کر کے سند میں فرماتے ہیں: عن یعیش الانصاری۔ حرب کے سوانح میں اس کے کئی طرق ہیں جو موطا میں منقول ہیں اور بزار نے یہ روایت حدیث بریدہ سے طویل نقل کی ہے۔ یہ یعیش ان یعیش بن طخفہ کے علاوہ ہیں جو اپنے والد سے اور ان سے یحییٰ بن ابی کثیر روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۴۸) استیعاب (۱۵۰/۴) تجرید (۱۴۴/۲)\n(2) المعجم الکبیر (۱۷۱/۲۲) مجمع الزوائد (۴۱/۸) جامع المسانید (۴۹۱/۱۲)"}],[9333,"§۹۳۷۰ ۔ یعیش\n(1) مولیٰ بنی عامر بن لوی۔ ابن الامین نے اپنے ذیل الاستعیاب میں ان کا ذکر کیا ہے کہ عثمانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۱۴۴/۲)"}],[9334,"§۹۳۷۱ ۔ یعیش\n(1) بنی مغیرہ کے غلام۔ مستغفری نے ان کا ذکر کیا ہے اور بطریق وکیع، سفیان، عن حبیب بن ابی ثابت عن عکرمہ روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم بنی مغیرہ کے ایک عجمی غلام کو قرآن پڑھاتے تھے۔ وکیع فرماتے ہیں: سفیان کا قول ہے: میرے خیال میں اسے یعیش کہا جاتا تھا۔ جس پہ یہ آیت نازل ہوئی: ﴿ہم خوب جانتے ہیں یہ لوگ کہتے ہیں: اسے (محمد صلی اللہ علیہ وسلم کو تو) ایک انسان سکھاتا ہے۔۔۔۔﴾۔ یحنس(2) میں دیکھ لیا جائے شاید وہ یہی ہوں۔","",{"fn":"(1) اسد الغابہ (۵۶۴۹) تجرید (۱۴۵/۲)\n(2) سورۃ النحل (۱۰۳)"}],[9335,"§۹۳۷۲ ۔ یغوث\nایک حدیث میں جسے میں من گھڑت سمجھتا ہوں ان کا ذکر آیا ہے جو میں نے ابن ابی طی کی کتاب طبقات الامامیہ میں پڑھی ہے۔۔۔۔"],[9336,"§۹۳۷۳ ۔ یفودان بن یفد یدویہ\n(1) مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جبکہ محمد نامی حضرات میں ان کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۶۵۰) تجرید (۱۴۵/۲)"}],[9337,"§۹۳۷۴ ۔ الیمان بن جابر\n(1) سیدنا حذیفہ رضی اللہ عنہ کے والد۔ حاء میں ان کا ذکر ہوا ہے کہ ان کا نام حصل ہے اور یمان لقب ہے۔ بقول بعض: یمان سیدنا حذیفہ کے دادا کا لقب ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۵۱) تجرید (۱۴۵/۲)"}],[9338,"§۹۳۷۵ ۔ یَناق\n(1) ابن مندہ نے ان کا ذکر کیا ہے کہ ان کی حدیث علی بن حجر نے عن عمر بن ہارون عن عبد العزیز بن عمر عن الحسن بن مسلم عن جدہ یَناق کی سند سے بیان کی ہے، فرمایا: میں نے حجۃ الوداع میں نبی صلی اللہ علیہ وسلم کو دیکھا۔ آپ سورج ڈھلنے کے بعد لوگوں کو وعظ کہنے کھڑے ہوئے۔(2)","",{"fn":"(1) اسد الغابہ (۵۶۵۲) تجرید (۱۴۵/۲)\n(2) جامع المسانید (۴۹۲/۱۲)"}],[9339,"§۹۳۷۶ ۔ یناق العمانی\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور الدارقطنی نے \"غرائب مالک\" میں نافع مولی ابن عمر کے حالات کے آخر میں بطریق عبد الرحمن بن خالد بن نجیح عن حبیب کاتب مالک روایت کی ہے کہ عمان کے کچھ لوگ امام مالک کے پاس آئے، ان میں صدقہ بن عطیہ بن حماس بن نجبہ بن حمار بن یناق نامی ایک شخص تھا، آپ اس کا احترام کرتے، کسی نے امام مالک رحمہ اللہ سے کہا کہ اس کے پاس چند احادیث ہیں جنہیں وہ بیان کرتا ہے تو مجھے امام مالک رحمہ اللہ نے وہ حدیث لکھنے کا حکم دیا تاکہ میں آپ کے سامنے پیش کروں۔ چنانچہ اس نے مجھے املاء کرایا: حدثنی ابی عطیہ سمعت جدی نجبہ بن حمار یحدث عن جدہ یناق، فرمایا: میں طائف میں اپنے جنگل میں اونٹ چرا رہا تھا، ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم کا خط آیا: \"اگر تم لوگ اسلام قبول نہیں کرتے تو جزیہ دو\"۔ پھر لمبی حدیث ذکر کی۔ اس کے آخر میں ہے: وہ سیدنا عمر رضی اللہ عنہ کے پاس اس وقت آئے جب آپ کو نیزہ لگا تھا، چنانچہ آپ کی وفات اور دفن میں شریک ہوئے۔ اور پہلے بیان ہو چکا ہے کہ حجۃ الوداع کے موقع پر مکہ اور طائف میں جو مسلمان باقی رہا وہ اس میں شریک ہوا۔"],[9340,"§۹۳۷۷ ۔ ینّہ الجہنی\nابن السکن نے یہاں ان کا ذکر کیا ہے، باء میں ذکر ہو چکا ہے۔"],[9341,"§۹۳۷۸ ۔ ینّہ الحمراوی\nابن یونس نے ان کا ذکر کیا ہے کہ فتح مصر میں شریک ہوئے اور حمراء کے ناظم تھے، مصر میں انہیں زائد وظیفہ ملتا تھا۔ بقول سعید بن عفیر: عبد الرحمن بن ینّہ کے والد ہیں۔\nمیں کہتا ہوں: فتوحات میں صحابہ رضی اللہ عنہم ہی امیر مقرر ہوتے تھے۔"],[9342,"§۹۳۷۹ ۔ یوسف بن عبد اللہ\n(1) بن سلام بن حارث اسرائیلی۔ بچپن میں نبی صلی اللہ علیہ وسلم کو دیکھا ہے اور آپ کی حدیث یاد رکھی ہے، ان کی حدیث سنن ابو داؤد اور جامع ترمذی میں بطریق یزید بن الاعور مروی ہے۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ نے روٹی کے ٹکڑے پہ کھجور رکھ کر فرمایا: یہ اس کا سالن ہے۔(2) ترمذی(3) میں ایک اور طریق سے بحوالہ ان کے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے میرا نام یوسف رکھا، یوسف اپنے والد، سیدنا عثمان، عمر، علی وغیرہ صحابہ کرام رضی اللہ عنہم سے بھی روایت کرتے ہیں۔ ابن ابی حاتم(4) نے نقل کیا ہے، انہوں نے اپنے والد سے کہا: امام بخاری رحمہ اللہ(5) نے ذکر کیا ہے کہ یوسف صحابی ہیں، تو میرے والد نے فرمایا: نہیں، انہیں رویت حاصل ہے۔ امام بخاری رحمہ اللہ کی بات زیادہ صحیح ہے۔ بغوی کا قول ہے: نبی صلی اللہ علیہ وسلم سے روایت کی ہے اور ابن سعد نے صحابہ رضی اللہ عنہم کے پانچویں طبقے میں ان کا ذکر کیا ہے اور صحابہ رضی اللہ عنہم کے متعلق کتابیں لکھنے والی ایک جماعت نے ان کا ذکر کیا ہے، خلیفہ بن خیاط فرماتے ہیں: خلافت عمر بن عبد العزیز میں فوت ہوئے۔ حاکم کا قول ہے: واقدی نے ان کی کنیت ابو یعقوب بتائی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۵۳) استیعاب (۲۸۵۶) تجرید (۱۴۵/۲)\n(2) ابوداؤد کتاب الاطعمۃ باب فی التمر (۳۸۳۰) شمائل الترمذی (۱۸۲) السنن الکبریٰ (۶۳/۱۰) المعجم الکبیر (۷۳۲/۲۲) مجمع الزوائد (۳۸/۵)\n(3) ترمذی، کتاب المناقب۔۔۔۔\n(4) الجرح والتعدیل (۲۴۰/۹)\n(5) التاریخ الکبیر (۳۷۱/۴)"}],[9343,"§۹۳۸۰ ۔ یوسف بن ہبیرہ\nابن ابی وہب المخزومی، فتح مکہ کے بعد ان کا والد کافر مرا، ان کی والدہ ام ہانی ہیں ان کے بھائی ہانی کے حالات میں ان کا ذکر ہوا ہے کہ انہوں نے اور ان کے بھائیوں نے دور نبوی پایا ہے۔"],[9344,"§۹۳۸۱ ۔ یونس بن شداد الازدی\n(1) ابن ابی حاتم(2) نے ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم سے روایت کی ہے جو بروایت سعید بن بشیر ان کی سند سے ہے جسے عبد اللہ بن احمد نے \"زوائد المسند\" میں بروایت سعید عن قتادہ عن ابی قلابہ عن ابی الشعثاء عن یونس بن شداد نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ایام تشریق (قربانی کے تین دنوں) میں روزہ رکھنے سے منع کیا ہے۔(3)","",{"fn":"(1) اسد الغابہ (۵۶۵۵) استیعاب (۲۸۵۷) تجرید (۱۴۵/۲)\n(2) الجرح والتعدیل (۲۴۰/۹)\n(3) مسند احمد (۷۷/۴) مجمع الزوائد (۳۰۳/۳) شرح المعانی (۲۴۵/۲) جامع المسانید (۴۹۹/۱۲)"}],[9345,"§۹۳۸۲ ۔ یونس بن عبید\nابن اسد بن علاج الثقفی۔ حنفیہ بنت عبید جو زیاد کی والدہ سیدہ سمیہ کی مولاۃ ہیں کے بھائی، نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے یہ فیصلہ فرمایا کہ بچہ اسی کا ہے جس کے پاس وہ بیوی ہے جب یہ زیاد کے استلحاق (ملائے جانے) کے وقت حاضر ہوئے۔ انہوں نے اس کا انکار کیا۔ تو امیر معاویہ رضی اللہ عنہ نے ان سے فرمایا: یا تم باز آ جاؤ گے یا میں تمہاری وجہ سے ایسی بدشگونی لوں گا جس کا پیش آنا دیر سے ہوگا۔ تو یونس(1) نے کہا: صرف اللہ کی طرف پھر میں واقع ہو جاؤں گا؟ انہوں نے کہا: ہاں! اور میں اللہ سے معافی چاہتا ہوں۔ پھر خاموش ہو گئے۔ یہ واقعہ رشاطی نے نقل کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۴۲/۹)"}],[9346,"§۹۳۸۳ ۔ یحییٰ بن ثابت\nابن قیس بن شماس انصاری خزرجی۔ انہیں اپنے بھائیوں کی طرح رویت حاصل ہے، ثابت جنگ یمامہ میں شہید ہوئے تھے۔"],[9347,"§۹۳۸۴ ۔ یحییٰ بن خلاد\n(1) ابن رافع بن مالک بن العجلان الزرقی بقول ابو عمر(2): ان کی احادیث اسحاق بن عبد اللہ بن ابی طلحہ کی کتاب میں عن علی بن یحییٰ بن خلاد عن ابیہ عن جدہ کی سند سے ہیں، کہ: جس دن یہ پیدا ہوئے نبی صلی اللہ علیہ وسلم کے پاس لائے گئے۔ آپ نے کھجور چبا کر دی اور فرمایا: میں اس کا ایسا نام رکھوں گا جو یحییٰ بن زکریا علیہ السلام کے بعد کسی کا نہیں رکھا گیا۔ پھر آپ نے ان کا نام(3) یحییٰ رکھا۔ ہمارے شیخ الشیوخ حافظ صلاح الدین علائی کا قول ہے: مجھے اس کی سند سے نہیں ملی۔\nمیں کہتا ہوں: ابن مندہ نے اس کا ذکر تو کیا ہے لیکن مرسلا۔ چنانچہ بطریق حبان بن ہلال عن ہمام عن اسحاق، حدثنی یحییٰ ابن خلاد، فرمایا: جب میری ولادت ہوئی تو میرے والد مجھے لے کر آئے۔۔۔۔ پھر اس کا ذکر کیا۔ ابو عمر نے وہم سے ان کا نسب کندی بتایا ہے جس کی ابن فتحون نے تردید کی ہے جو درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۵) استیعاب (۲۷۷۹) تجرید (۱۳۳/۲)\n(2) استیعاب (۱۲۹/۴)\n(3) الطبقات الکبریٰ (۵۲/۵) التاریخ الکبیر (۲۶۹/۴) الجرح والتعدیل (۱۳۹/۹)"}],[9348,"§۹۳۸۵ ۔ یزید بن الاصم\n(1) بن عمرو بن عبید بن معاویہ بن عبادہ بن البکاء بن عامر بن ربیعہ بن عامر بن صعصعہ، الاصم لقب ہے۔ یزید کی والدہ برزہ بنت الحارث الہلالیہ سیدہ ام المومنین میمونہ رضی اللہ عنہا کی بہن ہیں۔ بقول بعض: ان کی ولادت عہد نبی صلی اللہ علیہ وسلم میں ہوئی۔ ابن مندہ نے ان کے متعلق یہی ذکر کیا ہے۔ ابو نعیم فرماتے ہیں: ان کے صحابی ہونے کی بات صحیح نہیں۔ اپنی خالہ سیدہ میمونہ، سیدہ عائشہ رضی اللہ عنہما، ابو ہریرہ، سعد بن ابی وقاص، معاویہ اور ابن عباس رضی اللہ عنہم سے روایت کرتے ہیں۔ ان سے دونوں بیٹے عبد اللہ اور عبید اللہ صاحبزادگان عبد اللہ بن الاصم، زہری، ابو فزارہ العبسی، السبعی، قتادہ، میمون بن مہران، جعفر بن برقان وغیرہ روایت کرتے ہیں۔ ابن سعد(2) کا قول ہے، بقول ابن کلبی: نبی صلی اللہ علیہ وسلم نے الاصم کا نام عبد الرحمن رکھا۔ ابن سعد فرماتے ہیں: یزید بکثرت حدیث بیان کرتے۔ ۱۰۳ھ یا ۱۰۴ھ میں فوت ہوئے۔ بقول بعض: ۱۰۱ھ میں وفات پائی۔ واقدی کا بیان ہے: بہتر(۷۳) سال زندہ رہے۔\nمیں کہتا ہوں: اگر یہ روایت صحیح ہے تو پھر انہیں رویت حاصل نہیں۔ اس حساب سے ان کی پیدائش وفات نبویہ سے تقریباً بیس(۲۰) سال بعد ہوئی ہوگی۔","",{"fn":"(1) اسد الغابہ (۵۵۲۱) تجرید (۱۳۴/۲)\n(2) الطبقات الکبریٰ (۴۷۹/۷)"}],[9349,"§۹۳۸۶ ۔ یزید بن امیہ الدؤلی\n(1) ابو سنان الدؤلی۔ سیدنا علی، ابو واقد اللیثی اور ابن عباس رضی اللہ عنہم سے اور ان سے نافع، زہری، زید بن اسلم روایت کرتے ہیں۔ ابو عمر(2) نے صحابہ رضی اللہ عنہم میں ان کا مختصر ذکر کیا ہے۔ غزوہ احد کے سال عین موقعہ پہ پیدا ہوئے۔ ابو حاتم(3) فرماتے ہیں: نبی صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئے۔ یہ بات انہوں نے واقدی سے لی ہے ورنہ ثابت نہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۲۲) استیعاب (۲۷۸۷) تجرید (۱۳۴/۲)\n(2) استیعاب (۱۳۲/۴)\n(3) الجرح والتعدیل (۳۰۱/۹)"}],[9350,"§۹۳۸۷ ۔ یعلی بن حمزہ\n(1) ابن عبد المطلب بن ہاشم ہاشمی۔ نبی صلی اللہ علیہ وسلم کے چچا زاد بھائی۔ بقول زبیر: سیدنا حمزہ کی نسل صرف یعلی سے چلی تھی ان کے ہاں چار بیٹے پیدا ہوئے لیکن وہ سب فوت ہو گئے اور کوئی اولاد نہ چھوڑی۔ یوں سیدنا حمزہ بن عبد المطلب کا سلسلہ نسل منقطع ہو گیا۔ ابن سعد(2) کا قول ہے: سیدنا حمزہ کے ہاں یعلی پیدا ہوئے اور انھی کے نام پہ کنیت رکھتے تھے۔ پھر عمارہ ہوئے جن کے نام سے بھی کنیت کرتے تھے اور عامر پیدا ہوئے۔ انہوں نے شادی کی۔ ان کی والدہ ام یعلی اوسیہ انصاریہ ہیں اور عمارہ کی والدہ خولہ بنت قیس ہیں اور یعلی کی اولاد کے نام عمارہ، الفضل، زبیر عقیل اور محمد بتائے، سب فوت ہو گئے۔","",{"fn":"(1) اسد الغابہ (۵۶۴۲) استیعاب (۲۸۴۶)\n(2) الطبقات الکبریٰ (۸/۳)"}],[9351,"§۹۳۸۸ ۔ یحمد الخولانی\nیزید بن محمد کے حالات میں ان کا ذکر ہوگا۔"],[9352,"§۹۳۸۹ ۔ یُحَنّس\nمولی صہیب بن سنان۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے۔ سیدنا صہیب کے سیدنا عمر رضی اللہ عنہ کے ساتھ پیش آمدہ واقعے میں صہیب کے حالات میں ان کا ذکر ہوا ہے۔"],[9353,"§۹۳۹۰ ۔ یحییٰ بن یعمر الرعینی\nبقول ابن یونس: فتح مصر میں شریک ہوئے، سیدنا عثمان رضی اللہ عنہ کے خون کا مطالبہ کرنے میں سردار کی حیثیت رکھتے تھے۔"],[9354,"§۹۳۹۱ ۔ یرفا (دربان عمر رضی اللہ عنہ)\nدور جاہلیت پایا ہے اور خلافت صدیقی میں سیدنا عمر رضی اللہ عنہ کے ساتھ حج کیا۔ ابن المبارک نے کتاب الزہد میں اپنی شامی سند سے بحوالہ ابن عمر روایت کی ہے کہ سیدنا عمر رضی اللہ عنہ کو سیدنا یزید بن ابی سفیان رضی اللہ عنہ کی طرف سے یہ خبر ملی کہ وہ رنگ برنگے کھانے کھاتے ہیں تو آپ نے اپنے مولا یرفا سے فرمایا: جب تمہیں پتہ چلے کہ ان کے کھانے کا وقت ہو گیا ہے تو مجھے اطلاع کر دینا۔۔۔۔ پھر ایک واقعہ نقل کیا۔ ابن صاعد لکھتے ہیں: غریب ہے۔ اسے صرف ابن المبارک نے نقل کیا ہے۔ سعید بن منصور، ابو الاحوص عن ابی اسحاق بحوالہ البراء روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے مجھ سے فرمایا: میں اللہ کے مال سے وہی سلوک کرتا ہوں جو یتیم کا سرپرست کرتا ہے۔ جب مجھے ضرورت پڑتی ہے لے لیتا ہوں اور جب فراخی ہوتی ہے واپس کر دیتا ہوں۔ اور جب مجھے اس کی ضرورت نہیں ہوتی تو اس سے بچتا ہوں۔ ابو حنفہ الازدی کا بیان ہے: جب سیدنا عمر خلیفہ مقرر ہوئے تو ابو عبیدہ کی طرف یرفا کو خط دے کر بھیجا۔ تو یہ روانہ ہوئے یہاں تک کہ ابو عبیدہ کے پاس جا پہنچے۔۔۔۔ پھر ایک واقعہ نقل کیا۔\nیرفا کا تذکرہ صحیحین میں سیدنا عباس و علی رضی اللہ عنہما کے رسول اللہ صلی اللہ علیہ وسلم کے زکوۃ کے مال میں جھگڑے والے واقعے میں ملتا ہے اور اس حدیث میں بھی ان کا ذکر ہے جسے ابن ابی شیبہ(1) نے بطریق زہری عن عبد اللہ بن عبد اللہ بن عتبہ عن ابیہ نقل کیا ہے، فرماتے ہیں: میں سیدنا عمر رضی اللہ عنہ کے پاس آیا، آپ اس وقت نماز پڑھ رہے تھے۔ تو آپ نے مجھے اپنی دائیں جانب کھڑا کر لیا۔ میں یرفا آئے تو ہمیں اپنے پیچھے دھکیل دیا۔","",{"fn":"(1) المصنف لابن ابی شیبہ (۵۳۵/۱)"}],[9355,"§۹۳۹۲ ۔ یریم بن عامر\nبن سعد بن ذہل بن الاحدس بن سہل الرعینی۔ دور نبوی پایا ہے، بقول ابن یونس: یہ اور ان کا بھائی عقبہ فتح مصر میں شریک ہوئے۔"],[9356,"§۹۳۹۳ ۔ یریم بن معدیکرب\nابن ابرہہ بن الصباح الاصحی۔ دور نبوت پایا ہے، ان کا نضر نامی ایک بیٹا تھا، بقول ابن کلبی: اپنے دور میں حمیر کے شام میں سردار تھے، ان کے والد بنت معبد بن عباس بن عبد المطلب ہیں۔"],[9357,"§۹۳۹۴ ۔ یزداد الفارسی\n(1) ازواج میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۴) تجرید (۱۳۳/۲)"}],[9358,"§۹۳۹۵ ۔ یزید بن احمد المرادی ثم الزرقی\nبقول ابن کلبی۔ فتح مصر میں شریک ہوئے۔"],[9359,"§۹۳۹۶ ۔ یزید بن الاسود الغسانی\n(1) از بنی ثعلبہ بن کعب بن عمرو۔ ابن کلبی نے نسب قحطان کے آغاز میں ان کا ذکر کیا ہے۔ ابو خنس کنیت تھی۔ یہی یرموک کے زمانہ میں جبلہ بن الایہم کے ساتھ روم میں داخل ہوئے۔ پھر وہاں غسلان سے اپنے ساتھیوں سمیت مسلمان ہو کر لوٹے۔ شام میں ان کا بڑا مرتبہ ہے۔","",{"fn":"(1) تجرید (۱۳۴/۲)"}],[9360,"§۹۳۹۷ ۔ یزید بن الاسود الجُرَشی\n(1) ابو الاسود۔ بقول ابن ابی حاتم(2): دور جاہلیت کے ہیں۔ مسلم فرماتے ہیں: قدیم زمانے کے ہیں۔ ابو عمر(3) لکھتے ہیں: دور جاہلیت پایا ہے اور اہل شام میں شمار ہوتے ہیں۔ ابن مندہ فرماتے ہیں: صحابہ رضی اللہ عنہم میں ان کا ذکر ملتا ہے، جو ثابت نہیں۔ پھر بطریق یونس بن میسرہ روایت کی ہے کہ میں نے یزید بن الاسود سے پوچھا: ابو الاسود! آپ نے کتنا عرصہ گزارا ہے؟ انہوں نے کہا: مجھے وہ زمانہ یاد ہے جب میری قوم عزیٰ کو پوجا کرتی تھی اور امام بخاری رحمہ اللہ(4) نے اسے عن ابی مسہر عن سعید بن عبد العزیز عن یونس نقل کیا ہے اور ابن سعد نے پہلے طبقہ میں ان کا ذکر کیا ہے۔ ابن حبان الثقات میں لکھتے ہیں: سخت(5) حال لوگوں میں سے تھے۔ یہی روایت ابو زرعہ دمشقی اور یعقوب بن سفیان نے اپنی اپنی تاریخ میں بسند صحیح عن سلیم بن عامر نقل کی ہے کہ دمشق میں قحط پڑا تو امیر معاویہ یزید ابن الاسود کے وسیلے سے بارش کی دعا کرنے لگے تو ان لوگوں پہ بارش ہوئی۔\nابو زرعہ فرماتے ہیں: ابو مسہر، سعید بن عبد العزیز کے واسطے سے ہمیں بتاتے ہیں کہ ضحاک بن قیس لوگوں کے ساتھ صلوۃ الاستسقاء پڑھنے نکلے تو یزید بن الاسود سے کہا: اے کثرت سے رونے والے، اٹھیے! اسی سند سے مروی ہے کہ عبد الملک جب مصعب ابن الزبیر کی جانب روانہ ہوا تو اس کے ساتھ یزید بن الاسود تھے۔ ابن ابی الدنیا نے بطریق ہشام بن الغاز، حبان بن النضر کہ مجھ سے واثلہ بن الاسقع نے فرمایا کہ مجھے یزید بن الاسود کے پاس لے چلو، یہ ان کے پاس پہنچے تو وہ آ رہے تھے۔ انہوں نے آواز دی یہ آپ کے بھائی واثلہ ہیں تو انہوں نے اپنا ہاتھ بڑھایا، وہ اسے چومنے لگے، میں نے ان کی ہتھیلی اپنی ہتھیلی میں لے لی جسے وہ اپنے سینے پہ کبھی پھیرتے اور کبھی چہرے پہ۔ واثلہ کی ہتھیلی رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ کی جگہ ہے۔۔۔۔ پھر ایک واقعہ ذکر کیا۔ میرا غالب گمان یہی ہے کہ یہ سابقہ شخص کے علاوہ ہیں۔","",{"fn":"(1) استیعاب (۲۷۸۳) تجرید (۱۳۴/۲)\n(2) الجرح والتعدیل (۲۵۰/۹)\n(3) استیعاب (۱۳۱/۴)\n(4) التاریخ الکبیر (۳۱۸/۴)\n(5) جامع المسانید (۴۱۵/۱۲)"}],[9361,"§۹۳۹۸ ۔ یزید بن اُنیس الہذلی\n(1) دور نبوی پایا ہے۔ فرماتے ہیں: ہم لوگ عہد فاروقی میں مسجد میں قیام کرتے، یہ روایت ان سے مسلم بن جندب نے نقل کی ہے اور امام بخاری رحمہ اللہ نے کتاب خلق افعال العباد میں درج کی ہے۔","",{"fn":"(1) تجرید (۱۳۴/۲)"}],[9362,"§۹۳۹۹ ۔ یزید بن بشر الضبعّی\nبشر بن یزید میں ذکر ہوا ہے۔"],[9363,"§۹۴۰۰ ۔ یزید بن حارث الشیبانی\nدور نبوی پایا ہے اور جنگ یمامہ میں شریک ہوئے۔ جس کے بارے کہتے ہیں: ط \"ہماری چکی عامر کے جھنڈے کے ارد گرد گھوم رہی تھی، وہ ہمیں کھلے میدان میں ملے ہوئے دیکھ رہا تھا، معد کے دونوں رکن ہماری پناہ لے رہے تھے اور ہماری وجہ سے مشارق والے موت کی سختیوں سے بچتے ہیں\"۔ اس کے بعد بصرہ فروکش ہوئے، مرزبانی نے ان کا ذکر کیا ہے۔"],[9364,"§۹۴۰۱ ۔ یزید بن حذیفہ اسدی\n(1) کتاب الردہ میں وثیمہ نے ان کا اور ان کے بیٹے زفر کا اسلام پہ ثابت قدم رہنے والوں میں ذکر کیا ہے۔ وہ بنی اسد کے معزز لوگوں میں سے تھے۔ سیدنا خالد بن ولید سے جا ملے انہوں نے بنی اسد کی طرف انہیں ارتداد سے ڈرانے کے لیے یہ اشعار بھیجے: ط \"بنی اسد! اے میری قوم! طلیحہ میں کوئی ایسی خصلت نہیں جس کی وجہ سے اس کی بات مانی جائے\"۔","",{"fn":"(1) اسد الغابہ (۳۵۲۵) تجرید (۱۳۶/۲)"}],[9365,"§۹۴۰۲ ۔ یزید بن حمزہ المازنی\n(1) حارث بن عوف میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۹) تجرید (۱۳۶/۲)"}],[9366,"§۹۴۰۳ ۔ یزید بن ذی الاخرۃ الیمانی\nوثیمہ نے کتاب الردہ میں ان کا ذکر کیا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کے حکم سے الاسود العنسی کے بارے میں اشعار کہے تھے، اس بارے میں وہ اسود کے قتل کے بعد کہتے ہیں: ط \"تیرے بقاء کی قسم! ہم عبدان کے دن برکت والے حسیوں کی جماعت تھے نہ کہ کمینے۔ جس صبح ہم نے ایک وار سے عنس میں ناک کاٹ ڈالی اس کے ذریعے مکشوح نے ہمام کا سر جدا کر دیا\"۔"],[9367,"§۹۴۰۴ ۔ یزید بن رناب الاسلمی\nبقول ابن یونس: یہ اور ان کا بھائی فتح مصر میں شریک ہوئے۔"],[9368,"§۹۴۰۵ ۔ یزید بن السجّوح التجیبی العامری\nابن یونس کا بیان ہے: فتح مصر میں شریک ہوئے۔ بحری جنگ کے امیر مقرر ہوئے۔ یہ معصومہ میں طحاوی گلی کی مسجد والے ہیں۔"],[9369,"§۹۴۰۶ ۔ یزید بن شریک\n(1) ابن طارق التیمی الکوفی الفقیہ ابراہیم کے والد۔ کوفہ کے رہائشی تھے۔ سیدنا عمر، علی، ابوذر، ابن مسعود، حذیفہ وغیرہ صحابہ رضی اللہ عنہم سے روایت کرتے ہیں۔ ان سے ان کا بیٹا ابراہیم، ابراہیم نخعی، حکم بن عیینہ وغیرہ روایت کرتے ہیں۔ بقول ابن سعد(2): اپنی قوم کے ناظم تھے۔ بقول ابو موسیٰ: بتایا جاتا ہے دور جاہلیت پایا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۰) تجرید (۱۳۸/۲)\n(2) الطبقات الکبریٰ (۷۰/۶)"}],[9370,"§۹۴۰۷ ۔ یزید بن ضرار الاسدی\n(1) الشماخ میں ذکر ہوا ہے۔ یہ مزد ابو ضرار بقول ابو الحسن سے مشہور ہیں۔ الشماخ کے بھائی ہیں، بڑے تھے۔ مرزبانی(2) لکھتے ہیں: اسلام کا زمانہ پایا تو مسلمان ہو گئے، اپنے اس قصیدے میں کہتے ہیں جس کا مطلع ہے: ط \"دل سلمیٰ سے صاف ہو گیا اور اب طعنہ زن بھی کم ہو گئے ہیں\"۔ اسی میں کہتے ہیں: ط \"لوگوں کو خوب معلوم ہے کہ میں گزشتہ زمانے میں جب جری اور طعنہ زن کوشش کرتا تو میں ہی خطیب ہوتا، سردار ہوتا جسے بدکے ہوئے اونٹوں کے ذریعے پھینک دیتے۔ جنہیں ساتھ چلنے والے گاتے اور سواریوں کی حدی خوانی کی جاتی جس پر ان میں سے کسی ایک شعر کو تو پھینکے گا اسے واضح کر دے گا جسے چہرے کے قتل ہوئے اور مٹکوں کو دھو کے والا کوئی نہیں\"۔","",{"fn":"(1) تجرید (۱۳۸/۲)\n(2) معجم الشعراء (۴۸۲)"}],[9371,"§۹۴۰۸ ۔ یزید بن عبد اللہ\nالاحرم بن شعبہ بن حزم بن رویبہ بن عبد اللہ بن ہلال العامری ثم الہلالی، ہوزم میں ام المومنین سیدہ میمونہ رضی اللہ عنہا کے ہم نسب ہو جاتے ہیں۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے، بنی مروان کے دور میں ان کے بیٹے عبد اللہ بن یزید کا ذکر ہے، ان کا پوتا عاصم بن عبد اللہ ابن یزید، اسد بن عبد اللہ القسری کے پاس خراسان آیا تو اس نے انہیں قید کر لیا جس پہ اشعار کہے: ط \"تمہارے دوست قمری نے تمہیں قمر کے قریب کر دیا، ودوتی کی بنا پر جس چیز کے قریب کر دیا وہ بہت بری ہے\"۔ ابن کلبی رحمہ اللہ نے ان کا ذکر کیا ہے، حمص کے رہائشی تھے۔"],[9372,"§۹۴۰۹ ۔ یزید بن عمرو الریاحی\nشاعر اخوص سے مشہور تھے۔ مرزبانی معجم الشعراء میں لکھتے ہیں: مخضرمی ہیں، ابن قسوہ شاعر عیینہ بن مرداس کے ساتھ ان کا ایک واقعہ ہے۔ ابو بشر الآمدی نے ان کا نام زید بتایا ہے۔"],[9373,"§۹۴۱۰ ۔ یزید بن عمیرہ الزبیدی\n(1) بقول بعض: کندی/کلبی۔ حمص کے رہائشی تھے، بقول ابن سمیع: دور جاہلیت پایا ہے۔ ابن سعد رحمہ اللہ(2) لکھتے ہیں: سیدنا ابو بکر و عمر رضی اللہ عنہما سے ملے اور معاذ بن جبل کے ساتھ رہے۔ سیدنا معاذ، ابن مسعود رضی اللہ عنہما سے روایت کرتے ہیں ان سے ابو ادریس الخولانی، عطیہ بن قیس، ابو قلابہ، اور معبد الجہنی روایت کرتے ہیں۔ عجلی لکھتے ہیں: اکابر تابعین میں سے ہیں۔ ابو مسہر کا قول ہے: سیدنا معاذ کے تلامذہ کے سردار مالک بن ہبیرہ تھے اور یزید بن عمیرہ ان کے سرداروں میں سے تھے۔","",{"fn":"(1) اسد الغابہ (۵۵۸۷) تجرید (۱۳۹/۲)\n(2) الطبقات الکبریٰ (۳۵۲/۲)"}],[9374,"§۹۴۱۱ ۔ یزید بن قیس\n(1) ابن تمام بن مسعود بن کعب بن علوی بن علیان بن ارحب بن عامر بن مالک بن معاویہ۔۔۔۔ ہمدانی ارحبی۔ دور نبوت پایا ہے۔ اور ان کے سردار تھے۔ مجالد بن سعید نے کہا: جب سعید بن عاص روانہ ہوئے جو سیدنا عثمان رضی اللہ عنہ کی طرف سے کوفہ کے امیر تھے تو اہل کوفہ نے ان پہ دھاوا بول دیا۔ تو وہ سیدنا عثمان رضی اللہ عنہ کی طرف روانہ ہو گئے۔ کوفہ کے تمام قریش اکٹھے ہوئے اور ان یزید بن قیس کو اپنا امیر بنا لیا۔ پھر سیدنا علی رضی اللہ عنہ کی جنگوں میں ان کا ساتھ دیا، انہوں نے اپنا محافظ بنا لیا۔ پھر اصبہان، رے، اور ہمدان کا والی مقرر کر دیا۔ اس کے بعد شاعر امیر معاویہ کو مخاطب کر کے انہی سے مراد لیتا ہے: ط \"معاویہ! اگر آپ ہماری طرف آنے میں جلدی نہ کریں تو سیدنا علی رضی اللہ عنہ سے بیعت کر لیں یا یزید یمانی سے\"۔ بقول ابن کلبی: اس شعر کا شاعر ثمامہ ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[9375,"§۹۴۱۲ ۔ یزید بن قیس\nابن عبد اللہ بن قیس ابن عبد اللہ بن معاویہ بن الشیطان بن بکر بن کوف بن الحج انحی۔ دور نبوت پایا ہے۔ ان کا بیٹا عبد اللہ ابن یزید سیدنا علی رضی اللہ عنہ کے طرفداروں میں سے تھا۔ اور کوفہ میں فوت ہوا تو سیدنا علی رضی اللہ عنہ نے جنازہ پڑھایا۔ ہشام بن کلبی نے ان کا ذکر کیا ہے۔"],[9376,"§۹۴۱۳ ۔ یزید بن قیصم البہزی\nدور نبوی صلی اللہ علیہ وسلم پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے۔ مورخین نے اپنی کتابوں میں ان کا ذکر کیا ہے۔"],[9377,"§۹۴۱۴ ۔ یزید بن قنان\nاز بنی مالک بن سعد۔ سیف نے فتوح میں لکھا ہے کہ جب سیدنا عکرمہ رضی اللہ عنہ بن ابی جہل نے فتنہ ارتداد میں اپنے ساتھیوں کو ادھر ادھر تقسیم کیا تو انہیں کندہ بھیجا۔ طبری نے ان کا ذکر کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ واللہ اعلم"],[9378,"§۹۴۱۵ ۔ یزید بن قیس\n(1) ابن یزید بن الصعق۔ یہ لقب ہے ان کا نام عمرو بن حارث بن خویلد بن نوفل بن عمرو بن کلاب بن ربیعہ الکلابی ہے۔ بقول بعض: الصعق خویلد کا لقب ہے۔ مرزبانی نے ان کے دادا یزید بن الصعق کا ذکر کیا ہے اور ان کے بنی تمیم کی ہجو میں بیان کردہ اشعار نقل کیے ہیں کہ وہ نعمان بن المنذر کے دور میں تھے۔ رہے یزید بن قیس تو ان کی کنیت ابو المحتار ہے۔ ان کا مرزبانی نے ذکر کیا ہے اور لکھا ہے انہوں نے بحرہ کے گورنروں کی شکایات پر مشتمل ایک قصیدہ تیار کیا جو سیدنا عمر رضی اللہ عنہ تک پہنچ گیا۔ تو خالد بن غلاب نے دیا۔ اور ندائی نے عن علی بن حماد و حکیم بن حفص وغیرہ نقل کیے ہیں۔ لوگوں کا کہنا ہے: ابو المحتار یزید بن قیس بن الصعق نے ایسی بات کی جس میں اھواء وغیرہ کے گورنروں کی سیدنا عمر بن خطاب رضی اللہ عنہ سے شکایت کی ہے: ط \"امیر المومنین کو میری طرف سے یہ پیام پہنچا دو کہ آپ امر و نہی میں اللہ کے امین ہیں۔ آپ ہم میں اللہ کے امین ہیں اور جو رب العرش کا امین ہو میرا سینہ اس کے تابع ہے۔ آپ رسا تیق اور گاؤں والوں کو نہ چھوڑیئے گا۔ جو اللہ کے مال کو چپڑے اور بہتان میں بہاتے ہیں۔ آپ حجاج کی طرف پیام بھیج کر اس کا حساب جانچیئے، اسی طرح جزاء اور بشری کی طرف حکم بھیجیے! اور دونوں نافع کو ہرگز نہ بھولیے گا۔ اور نہ ابن غلاب کو جو بنی نصر کے سرداروں میں سے ہے، ان میں سے عاصم کی تھوڑی توجہ نہیں۔ اور جو بازاروں میں ہے وہ بنی بدر کا مولا ہے نعمان کی طرف خط بھیج کر اس کا حساب بھی دیکھئے۔ اور بنی غزوان کے داماد کی بے شک مجھے اطلاع ہے اور شبل کی طرف اس کے مال کے بارے میں پوچھے۔ اور ابن محرش کیونکہ اہل رساتق میں انہی کا بڑا ذکر ہے۔ آپ ان سے مقاسمہ کیجئے۔ میری جان آپ پہ فدا! اگر آپ نے آدھو آدھ تقسیم کی تو راضی ہو جائیں گے آپ مجھے گواہی کے لیے نہ بلائیے گا کیونکہ میں غائب رہتا ہوں، لیکن میں زمانے کے عجائبات دیکھتا ہوں جب یہ لوگ واپس ہوتے ہیں ہم بھی واپس ہوتے ہیں اور جب یہ جہاد کرتے ہیں ہم بھی شریک ہوتے ہیں\"۔ مرزبانی نے چند اشعار پر اکتفا کیا ہے اور آخر میں ایک تیرا شعر زائد نقل کیا ہے: ط \"جب ہندوستانی تاجر مشک لے کر آتا ہے تو آپ دیکھیں گے کہ ان کی مانگوں سے بہہ رہی ہوتی ہے\"۔ تو سیدنا عمر رضی اللہ عنہ نے ان لوگوں سے مقاسمہ کیا، ان کا آدھا مال ضبط کر لیا یہاں تک کہ ایک جوتا ضبط اور ایک چھوڑ دیا۔ ان لوگوں میں ابو بکرہ بھی تھے۔ کہنے لگے: میں نے کسی کام میں کوئی کوتاہی نہیں کی۔ آپ نے فرمایا: تمہارا بھائی بیت المال اور اونٹوں کا عشر لینے پہ مامور ہے وہ تمہیں مال دیتا ہے جس سے تم تجارت کرتے ہو۔ چنانچہ ان سے دس ہزار لیے۔ بقول بعض: ان کا بھی آدھا مال لے لیا۔ راوی کا بیان ہے۔ جس حجاج کا انہوں نے ذکر کیا ہے وہ ابن عتیک ثقفی ہیں اور وہ فرات پہ مامور تھے۔ اور جزاء بن معاویہ احنف کے چچا جو سرف پر مقرر تھے۔ بشر بن المحبر باب سابور کے لشکروں کے نگران تھے۔ دو نافع سے مراد، ابو بکر نفع اور نافع بن حارث بن خلدہ جو ان کے بھائی ہیں۔ اور ابن غلاب خالد بن حارث جن کا تعلق بنی دھمان بن نصر بن معاویہ بن بکر بن ھوازن سے تھا وہ اصبہان میں بیت المال پر مامور تھے۔ اور عاصم بن قیس بن الصلت مناذر پر تھے اور بازار پر سمرہ بن جندب تھے جو سوق الاھواز پر مامور تھے۔ نعمان بن عدی بن نضلہ، بقول بعض: فضیلہ بن عبد العزیٰ بن حرثان بنی عدی بن کعب کے فرد جو دجلہ کے ضلع کے عامل تھے۔ انہیں نے کہا تھا: ط \"حناء کو کوئی یہ پیام پہنچانے والا ہے کہ اس کا خاوند اور بنی غزوان کا داماد مجاشع بن سعد سلمی ہیں\"۔ ان کے عقد میں بنت عتبہ بن غزوان تھیں۔ وہ بصرہ کی زکوۃ وصولی پر مامور تھے۔ اور شبل بن معبد الجبلی الا حمسی، غنیمتیں وصول کرنے پر مقرر تھے۔ اور ابن محرش ابو مریم کثفی، رامہر مز پر فرات کے پل پر مقرر تھے۔ مرزبانی کا قول ہے: خالد بن غلاب نے انہیں جواب دیتے ہوئے کہا: ط \"ابو المحتار کو بتا دو میں نہ تمہارا رشتہ دار ہوں اور نہ داماد، میرا مال کسی ویران حکومت سے حاصل نہیں ہوا جسے تم شعروں میں شامل کرنے لگو\"۔ اسی قصیدے میں چند اشعار یہ ہیں: ط \"دار الحفاظ آگے رکھی ہوئی چیزیں کھانے کی تھیں جنگ کے دن فرما رواؤں کے لیے، اسل اور کیکر، بھری ہوئی نیزوں کی زیادتی کو بھلا دے، میں ان چیزوں سے تیری کفایت سفید اثر والی چیز سے اپنی طرف سے کر دوں گا\"۔","",{"fn":"(1) معجم الشعراء (۴۸۰)"}],[9379,"§۹۴۱۶ ۔ یزید بن محمد\nیزید بن محمد کے حالات میں ذکر ہوا ہے۔"],[9380,"§۹۴۱۷ ۔ یزید بن مر\nعلی بن عبدوؤ بن امد بن کعب الصائد بن شر حبیل بن عمرو بن جشم بن صاعد المحمد انی ثم الصائدی۔ ان کا بیٹا محمد، ابن الحنفیہ کے ساتھیوں میں سے تھا۔ مختار بن ابی عبید کی جنگوں میں اس کے ساتھ تھا۔ ابن کلبی نے یہ بات نقل کی ہے۔"],[9381,"§۹۴۱۸ ۔ یزید بن معاویہ\n(1) ابن عبید بن رؤاس بن کلاب بن ربیعہ بن عامر بن صعصعہ الرؤاسی۔ ابو داؤد شاعر بقول مرزبانی(2) مخضرمی ہیں: ط \"کبھی تو تم سلسلہ بحال رکھتے ہو اور کبھی توڑ دیتے ہو، سب سے برا دوست مقلون المراج ہے\"۔ ابن کلبی رحمہ اللہ نے ان کے بارے میں شاعر سے زیادہ کچھ نہیں کہا۔","",{"fn":"(1) اسد الغابہ (۵۶۰۱)\n(2) معجم الشعراء (۴۸۴)"}],[9382,"§۹۴۱۹ ۔ یزید بن مُغفل\nابن عوف بن عمیر بن کلب العامری۔ نسب ان کے بھائی زہیر کے حالات میں بیان ہو چکا ہے۔ دونوں نے دور نبوی صلی اللہ علیہ وسلم پایا ہے اور دونوں ہی جنگ قادسیہ میں شہید ہوئے۔ (ابن کلبی) اور مرزبانی نے یزید بن مغفل کا ذکر کیا اور ان کا یہ شعر نقل کیا ہے جب وہ حسین بن علی رضی اللہ عنہ کی طرف سے لڑ رہے تھے اور اسی گھڑی شہید ہوئے۔ \"اگر تم مجھے نہیں جانتے تو میں ابن المغفل ہوں جنگوں میں اسلحے سے لیس پیچھے نہ ہٹنے والا، میرے دائیں ہاتھ میں آوھی تیز دھار تلوار ہے جسے میں گھر سوار پر جنگ کے درمیان میں چلا دیتا ہوں\"۔ یا تو یہ دو ہیں یا ان کے شہید ہونے کی جگہوں میں سے ایک کے بارے میں قول غلط ہے۔"],[9383,"§۹۴۲۰ ۔ یزید بن ملجم المرادی\nعبد الرحمن کے بھائی۔ دور نبوی پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے۔"],[9384,"§۹۴۲۱ ۔ یزید بن ناجیہ اللخمی\nاز بنی بحر بن سوادہ ان میں صاحب شرافت تھے۔ دور نبوی پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے۔ سیدنا ابوذر رضی اللہ عنہ سے روایت کرتے ہیں ان سے یزید بن عمرو الغافری روایت کرتے ہیں۔"],[9385,"§۹۴۲۲ ۔ یزید بن نعیم\n(1) ابن شجرہ بن یزید التجیبی ثم الایدعانی، دور نبوت پایا ہے۔ بقول ابن یونس: فتح مصر میں شریک ہوئے اور گنے چنے شہسواروں میں سے ایک تھے۔","",{"fn":"(1) تجرید (۱۴۱/۲)"}],[9386,"§۹۴۲۳ ۔ یزید بن یحمد الہمدانی\n(1) عبد خیر کے والد۔ ابو عمر نے ان کے بیٹے کے سوانح میں ان کا ذکر کیا ہے۔ اور بروایت عبد الملک بن سلع نقل کیا ہے، فرماتے ہیں: میں نے عبد خیر سے کہا: ابو عمارہ! آپ بہت بوڑھے ہو گئے آپ کی کتنی عمر ہو گئی ہے؟ انہوں نے کہا: ایک سو بیس(۱۲۰) سال۔ میں نے کہا: کیا آپ کو دور جاہلیت کی کوئی بات یاد ہے؟ انہوں نے فرمایا: ہاں! مجھے یاد ہے کہ میری والدہ نے ہنڈیا پکائی، میں نے کہا: ہمیں کھانا دیجئے! کہنے لگیں ابا کو آ لینے دو، اتنے میں میرے والد صاحب آ گئے۔ وہ کہنے لگے: ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم کا خط آیا ہے۔ آپ ہمیں مردار کا گوشت کھانے سے منع کر رہے ہیں۔ چنانچہ ہم نے وہ ہنڈیا انڈیل دی۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں اسی طرح نقل کیا ہے۔ اور ابو یعلی نے بروایت عبد الملک، ابن فتحون فرماتے ہیں: یہ روایت ابو عمر نے ان کے بیٹے عبد خیر کے حالات میں شامل کی ہے۔ یہ ان کی شرط کے مطابق ہیں پھر ان کا الگ نہیں ذکر کیا۔\nمیں کہتا ہوں: لیکن انہوں نے \"یزید بن محمد\" کہا ہے تحریف میں بدل دیا، یہ تو محمد ہیں۔ بقول بعض: یہ عبد الرحمن بن محمد ہیں۔ شاید کسی نے ان کے دادا کے نسب سے ایسا ذکر کر دیا ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[9387,"§۹۴۲۴ ۔ یسار\nحسن بن ابی الحسن البصری کے والد۔ دور نبوی نصیب ہوا ہے۔ خطیب بطریق ابی الحنا عن ابی عائشہ روایت کرتے ہیں کہ یسار اہل یمان سے تھے۔ گرفتار ہوئے اور کسی انصاری کے گھر جا پہنچے۔ یہ انصار کے مولا ہیں خلافت فاروقی کے اخیر دور میں ان کے ہاں حسن پیدا ہوئے۔"],[9388,"§۹۴۲۵ ۔ یسار المطلبی\nمولی قیس بن مخرمہ۔ یہ صاحب مغازى محمد یسار کے دادا ہیں۔ ابو بکر بن المقرئ نے اپنے فوائد میں بطریق محمد بن اسحاق روایت کی ہے کہ مجھ سے صالح بن کیسان نے بیان کیا کہ خالد بن الولید روانہ ہو کر \"عین التمر\" پہ فروکش ہوئے۔ وہاں جنگ کی اور لوگوں کو قیدی بنایا۔ قیدیوں میں سیر بن ابی عمرہ اور عبد مولی بلقین، حمران بن ابان، افلح مولی ابی ایوب، اور یسار مولی قیس بن مخرمہ بھی تھے۔ یہ اھل خلافت صدیقی کے آغاز کا واقعہ ہے۔"],[9389,"§۹۴۲۶ ۔ یسار بن نمیر\n(1) سیدنا عمر رضی اللہ عنہ کے خزانچی۔ دور نبوی صلی اللہ علیہ وسلم پایا ہے اور سیدنا عمر رضی اللہ عنہ سے روایت کا شرف رکھتے ہیں۔ ان سے ابو وائل، شقیق بن سلمہ وغیرہ روایت لیتے ہیں۔ ابن سعد(2) نے طبقات میں سیدنا عمر رضی اللہ عنہ کے حالات میں بروایت ابو عاصم الغطفانی، بحوالہ یسار بن نمیر حدیث نقل کی ہے کہ \"میں نے جب بھی سیدنا عمر رضی اللہ عنہ کے آٹا چھانا، تو آپ مجھ سے ناراض ہوئے\"۔ اور ہم عباس(3) الترقی کے رسالہ میں بطریق غیلان بن جریر عن ابی اسحاق عن یسار بن نمیر مولی عمر روایت کی ہے، فرمایا: سیدنا عمر رضی اللہ عنہ جب پیشاب کے لیے بیٹھتے تو مجھے فرماتے: کوئی چیز دے دو، تو میں آپ کو لکڑی یا پتھر دیتا ورنہ آپ کسی دیوار والے باغ کے قریب آ جاتے۔ بلاذری کی روایت ہے، یسار فرماتے ہیں: مجھ سے سیدنا عمر رضی اللہ عنہ نے فرمایا: ہمارا حج میں کتنا خرچ ہوا۔۔۔۔ پھر ایک واقعہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۵۶۳۳) استیعاب (۱۴۵/۴) تجرید (۱۴۲/۲)\n(2) الطبقات (۳۱۹/۳)\n(3) التاریخ الکبیر (۴۲۰/۴) الجرح والتعدیل (۳۰۷/۹)"}],[9390,"§۹۴۲۷ ۔ یُسیر بن عمرو\n(1) اسیر میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۳) استیعاب (۲۸۴۰) تجرید (۱۴۳/۲)"}],[9391,"§۹۴۲۸ ۔ یعقوب بن عمرو\nدور نبوت پایا ہے۔ خلافت صدیقی میں اجنادین میں شہید ہوئے۔ یہ بات میں نے تاریخ مظفری میں دیکھی ہے۔ پھر ازدی کی فتوح الشام میں مل گئی۔ ان کا تذکرہ ان کے والد عمرو بن ضریس کے حالات میں بھی ہوا ہے۔ ابو اسماعیل ازدی کا قول ہے: واقعہ اجنادین میں سات مشرک قتل کیے۔ انہیں ایک نیزہ لگا، چار یا پانچ ایام تک زندہ رہے پھر زخم بہہ پڑا۔ سیدنا ابو عبیدہ سے اپنے اہل و عیال کے ہاں جانے کی اجازت چاہی، انہوں نے اجازت دے دی تو وہیں وفات پائی۔"],[9392,"§۹۴۲۹ ۔ یعفور بن حسان الذہلی\nدور نبوی پایا ہے اور فتح قادسیہ میں شریک ہوئے۔ سیدنا سعد رضی اللہ عنہ نے سیدنا عمر رضی اللہ عنہ سے ان کے بارے میں بیان کیا کہ میں نے یعفور جیسا آدمی نہیں دیکھا وہ ایک دن پانچ گھر سواروں کو لے آئے ان میں سے ایک آدمی کو ایسا داو دیا یہاں تک کہ اس پہ تیروں کی بوچھاڑ کر دی، پھر پوری طرح اس پر غلبہ پا کر اسے مسلمان کر کے لے آئے۔"],[9393,"§۹۴۳۰ ۔ یعلی بن عمیرہ\nابن یعمر بن حارثہ بن العبید۔۔۔۔ انہدی۔ دور نبوت نصیب ہوا، فتوحات عراق میں سے قادسیہ میں سیدنا سعد رضی اللہ عنہ کے ساتھ شریک ہوئے۔ پھر صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ بقول ابن کلبی بنی نہد کا جھنڈا انہی کے ہاتھ میں تھا۔"],[9394,"§۹۴۳۱ ۔ ینّاق العمانی\n(1) دور نبوی پایا ہے۔ الدار قطنی نے \"غرائب مالک\" میں ان کی حدیث بطریق عبد الرحمن بن خالد بن نجیح عن حبیب کاتب مالک روایت کی ہے کہ عمان کے کچھ لوگ حج کر کے امام مالک کے پاس آئے۔ ان میں صدقہ بن عطیہ بن حماس بن نجبہ بن حمار بن یناق تھا۔ امام مالک رحمہ اللہ اس کا بڑا اکرام کرتے بلند مقام پر بٹھاتے، پھر مجھے حکم دیا کہ میں اس سے وہ حدیث نقل کروں جو وہ بیان کرتا ہے اور پھر امام مالک رحمہ اللہ کے سامنے پیش کروں۔ چنانچہ اس نے مجھے املا کرایا: حدثنی ابی عطیة بن حماس قال سمعت جدی نجبہ بن حمار یحدث عن جدہ یناق۔ فرماتے ہیں: میں اپنے گھر والوں کے اپنے جنگل میں اونٹ چرا رہا تھا، ہمارے پاس نبی صلی اللہ علیہ وسلم کا خط آیا کہ مسلمان ہو جاؤ، تو میری قوم نے انکار کر دیا۔ آپ نے ان کی طرف اپنے نیک آدمی بھیجے، پھر ہمیں رسول اللہ صلی اللہ علیہ وسلم کی وفات کی اطلاع ملی۔ تو میری قوم جو پہلے ادا کرتی تھی وہ ابو بکر کی طرف بھیج دی، میں نے اپنی قوم سے کہا: مجھے سوار کر کے سیدنا عمر رضی اللہ عنہ کے پاس بھیج دو تو انہوں نے نہ مانا۔ یہاں تک کہ ان میں سے بعض لوگوں نے میرے اونٹ لے لیے، میں اپنی سواری پر بیٹھ کر مدینہ کی طرف چل پڑا۔۔۔۔ پھر ایک لمبا واقعہ ذکر کیا۔ اس میں ہے: سیدنا عمر رضی اللہ عنہ پہ قاتلانہ حملہ ہوا، فرماتے ہیں: میں مدینہ میں داخل ہوا، پھر سیدنا عمر رضی اللہ عنہ کے گھر آپ کے آخری لمحات میں ان لوگوں سے اپنی ملاقات کا ذکر کیا، جس کی لمبی حدیث ہے۔\nحبیب کہتے ہیں: میں امام مالک کے پاس آیا، آپ نے وہ تحریر پڑھ کر فرمایا: اسی مفہوم کی روایت مجھ سے نافع نے بحوالہ ابن عمر رضی اللہ عنہ بیان کی ہے۔ پھر وہ شیخ امام مالک رحمہ اللہ کے پاس آیا، آپ نے اس کا اکرام کیا تو آپ کی مجلس میں اس نے وہ حدیث بیان کی۔ پھر ان سے وہ واقعہ نقل کیا جس میں سیدنا علی رضی اللہ عنہ کا سیدنا عمر رضی اللہ عنہ سے ام کلثوم بنت علی بن نعیم کے بارے اختلاف ہوا، یہاں تک کہ سب کا اس پہ اتفاق ہوا کہ وہ سیدہ حفصہ بنت عمر کے پاس قیام کریں گی۔۔۔۔ الدار قطنی فرماتے ہیں: اس میں حبیب عن صدقہ عن مالک روایت کرنے میں منفرد ہیں، اس کے بعد فرماتے ہیں: حبیب محدثین کے نزدیک ضعیف ہیں۔","",{"fn":"(1) تجرید (۱۴۵/۲)"}],[9395,"§۹۴۳۲ ۔ یحییٰ بن سعید\n(1) ابن عاص۔ درمیانہ درجے کے تابعی ہیں۔ ذیل میں ابو موسیٰ لکھتے ہیں: ابو داؤد نے السنن میں عن الشعی عن مالک عن یحییٰ بن سعید الانصاری عن القاسم بن محمد و سلیمان بن یسار روایت کی ہے، دونوں فرماتے ہیں کہ یحییٰ بن سعید بن عاص نے بنت عبد الرحمن کو طلاق بائن دے دی تو عبد الرحمن انہیں لے گئے۔ سیدہ عائشہ رضی اللہ عنہا نے مروان بن الحکم کی طرف پیام بھیجا وہ اس وقت مدینہ کے گورنر تھے: کہ اللہ سے ڈرو! اور عورت کو اس کے گھر لوٹا دو۔۔۔۔ (حدیث)(2)\nابن الاثیر(3) فرماتے ہیں: یہ یحییٰ، عمرو بن سعید الاشدق کے بھائی ہیں۔ نہ یہ دونوں صحابی ہیں اور نہ دونوں کو دور نبوی ملا ہے۔ کیونکہ ان کے والد سعید بن عاص ہجرت کے سال پیدا ہوئے اور یحییٰ ان کے بڑے بیٹے بھی نہیں۔ بہر صورت یہ صحابی نہیں۔ تو ابو موسیٰ کو کیسے شبہ ہو گیا؟\nیہ حدیث بخاری میں بھی عن اسماعیل عن مالک مروی ہے اس میں بنت عبد الرحمن بن الحکم کو طلاق دی۔ اور بطریق عبد الرحمن ابن القاسم عن ابیہ نقل کی ہے کہ عروہ نے سیدہ عائشہ رضی اللہ عنہا سے کہا: خالہ جان! آپ نے اس عورت کو دیکھا ہے جسے اس کے خاوند نے طلاق دے دی ہے، پھر بھی وہ چلی گئی ہے، اس کے بارے آپ کیا کہتی ہیں؟ آپ نے فرمایا: اس نے بہت برا کیا۔ لگتا ہے اس روایت میں اپنے دادا کے نسب سے ذکر ہوئی ہیں اور ان کے خاوند کا نام نہیں لیا گیا۔ جو یحییٰ بن سعید ہیں جن کا ابھی ذکر ہوا ہے۔ اور یحییٰ(4) ..........","",{"fn":"(1) اسد الغابہ (۵۵۰۶) تجرید (۱۳۲/۲)\n(2) بخاری کتاب الطلاق باب فاطمۃ بنت قیس (۵۳۲۱، ۵۳۲۲) ابو داؤد (۲۲۹۵) موطا مالک (۱۲۶۰)\n(3) اسد الغابہ (۴۲۸/۴)\n(4) چار لفظوں کے بقدر جگہ خالی ہے۔"}],[9396,"§۹۴۳۳ ۔ یحییٰ بن صیفی\n(1) چھوٹے تابعی ہیں۔ کوئی حدیث مرسل بیان کی ہے جس کی وجہ سے یحییٰ بن یونس نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا۔ اور بطریق ابراہیم بن یزید، الجوزی، عن یحییٰ بن صیفی روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: آدمی کی سعادت ہے کہ اس کا بیٹا اس کے مشابہ ہو۔(2) مستغفری صحابہ رضی اللہ عنہم میں ان کا ذکر کرنے کے بعد فرماتے ہیں: یہ روایت مرسل ہے اور یحییٰ کا صحابی ہونا مشہور ہے۔\nمیں کہتا ہوں: ان کی ایک اور مرسل حدیث بھی ہے جسے ابو سعید بن الاعرابی نے اپنے \"معجم\" میں بروایت السائب بن عمر مخزومی عن یحییٰ بن صیفی نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس پہ کوئی احسان ہوا ہو تو اس پہ لازم ہے کہ وہ اس کا بدلہ دے اگر ایسا نہ کر سکے تو تعریف کر دے، اگر ایسا بھی نہ کیا تو اس نے کفران نعمت کیا۔ بعض نے یہ امکان ظاہر کیا ہے کہ یہ یحییٰ بن عبد اللہ بن صیفی ہیں جن کی حدیث صحیح میں بروایت ان کے عن ابی سعید مولی ابن عباس رضی اللہ عنہما بحوالہ ان کے مروی ہے۔ لگتا ہے ان دونوں صحیح حدیثوں میں اپنے دادا کے نسب سے ذکر ہوئے۔ بقول ابن سعد رضی اللہ عنہ ثقہ تھے ان کی روایت سے کئی احادیث مروی ہیں، ابن حبان نے ثقہ تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۰۷) تجرید اسماء الصحابۃ (۱۳۳/۲)\n(2) جامع المسانید والسنن (۴۰۹/۱۲)"}],[9397,"§۹۴۳۴ ۔ یحییٰ بن عبد الرحمن\n(1) ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا اور بطریق شعبہ بحوالہ یحییٰ بن عبد الرحمن روایت کی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اسعد بن زرارہ کو داغ لگایا، ان سے غلطی ہوئی یہ تو عن عمہ یحییٰ بن اسعد بن زرارہ مروی ہے جیسا کہ پہلے بیان ہوئی۔","",{"fn":"(1) تجرید (۱۳۳/۲)"}],[9398,"§۹۴۳۵ ۔ یحییٰ بن ابی کریم\nتابعی ہیں، مرسل حدیث بیان کی جس کی وجہ سے کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا۔ عسکری لکھتے ہیں: ان کی روایت مرسل ہے۔"],[9399,"§۹۴۳۶ ۔ یحییٰ بن ہانی\n(1) ابن عروہ المرادی۔ چھوٹے تابعی ہیں۔ کوئی مرسل حدیث بیان کی ہے جس کی وجہ سے ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے اور بطریق ابن کلبی بحوالہ یحییٰ بن ہانی بن عروہ المرادی روایت کی ہے فرمایا کہ فروہ بن مسیک کندہ کے بادشاہوں سے الگ ہو کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔۔۔۔ پھر وہ حدیث(2) ذکر کی۔\nمیں کہتا ہوں: ان کے والد ہانی بن عروہ مخضرمین میں شامل ہوتے ہیں۔ حرف ہاء میں ان کا ذکر ہو چکا ہے یحییٰ کو سیدنا انس، نعیم بن وجاج اور ابو حذیفہ وغیرہ حضرات سے روایت کرنے کا شرف حاصل ہے۔ ان سے شعبہ، ثوری، شریک اور ابو بکر بن عیاش وغیرہ روایت کرتے ہیں۔\nابو حاتم رازی(3) لکھتے ہیں: ثقہ، صالح ہیں۔ اہل کوفہ کے سرداروں میں سے ہیں۔ ابن حبان نے معتبر ثقہ تابعین میں ان کا شمار کیا ہے، یحییٰ بن بکیر بحوالہ شعبہ نقل کرتے ہیں۔ اپنے دور میں کوفہ والوں کے سردار تھے۔ نسائی وغیرہ نے انہیں ثقہ لکھا ہے۔ ان کی حدیث سنن کی تینوں کتابوں میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۱۱) تجرید (۱۳۳/۲)\n(2) البدایۃ والنہایۃ (۷۱/۵)\n(3) الجرح والتعدیل (۱۹۵/۹)"}],[9400,"§۹۴۳۷ ۔ یزید بن ابی اوفی\n(1) درست نام زید ہے، حرف زاء میں پہلے بیان ہو چکا ہے۔","",{"fn":"(1) تجرید (۱۳۵/۲)"}],[9401,"§۹۴۳۸ ۔ یزید بن جاریہ\nابن قانع نے ان کا ذکر کیا ہے اور ابن الدباغ نے ابن عبد البر کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے، جو ان کا وہم ہے۔ کیونکہ ابن عبد البر نے ان کا درست نام ذکر کیا ہے، وہ لکھتے ہیں: یزید بن سیف یا یوسف، ان کے دادا کا نام نہیں لکھا، جس سے ابن الدباغ سمجھے انہوں نے ان کا ذکر نہیں کیا اور ابن قانع نے ان کے دادا کے نسب سے ذکر کیا ہے اور بغوی، ابن السکن اور طبرانی(1) نے ان کا صحیح نسب لکھا ہے اور جیسا پہلے بیان ہوا ان کی حدیث نقل کی۔","",{"fn":"(1) المعجم الکبیر (۲۴۵/۲۲)"}],[9402,"§۹۴۳۹ ۔ یزید بن جاریہ\n(1) ابن عامر بن العطاف۔ ابن شاہین نے ان کا ذکر کیا ہے اور ان سے پہلے یزید بن جاریہ ابن مجمع بن العطاف کا ذکر کر چکے ہیں، دونوں ایک ہیں۔ یہی ابن جاریہ بن عامر بن مجمع بن العطاف ہیں جیسا کہ قسم اول میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۰) تجرید (۱۳۵/۲)"}],[9403,"§۹۴۴۰ ۔ یزید بن جاریہ\n(1) دوسرے، قریب ہی یزید بن خارجہ بن عامر میں ذکر ہوگا۔","",{"fn":"(1) استیعاب (۲۷۹۲) تجرید (۱۳۵/۲)"}],[9404,"§۹۴۴۱ ۔ یزید بن حُصین\n(1) ابن نمیر الکوفی الحمصی۔ صغار تابعین میں سے ہیں۔ خلافت یزید بن عبد الملک ۱۰۳ھ میں فوت ہوئے۔ سلیمان بن عبد الملک نے انہیں حمص کا پھر حضرت عمر بن عبد العزیز نے گورنر مقرر کیا تھا۔ جب مروان بن الحکم مصر داخل ہوئے تو یہ ساتھ تھے، ان کے والد حسین بن نمیر کو مسلم بن عقبہ المری نے واقعہ حرہ کے بعد اس لشکر کا امیر بنایا جس نے خلافت یزید بن معاویہ میں مدینہ نبویہ پر چڑھائی کی۔ پھر حسین نے مکہ پہ حملہ کیا اور ابن زبیر رضی اللہ عنہ کا محاصرہ کر لیا۔ اتنے میں انہیں یزید بن معاویہ(2) کی موت کی اطلاع مل گئی۔ حسین صحابی نہیں چہ جائیکہ ان کا بیٹا۔ جس کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا تو ایک صحابی کے ساتھ اشتباہ کی وجہ سے جن کا نام اور ان کے والد کا نام ایک جیسا ہے جن کا قسم اول میں ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۳۷) تجرید (۱۳۶/۲)\n(2) التاریخ الکبیر (۳۲۶/۴) جامع المسانید (۴۲۴/۱۲) الطبقات الکبریٰ (۲۹۳/۴)"}],[9405,"§۹۴۴۲ ۔ یزید بن حنظلہ\nحدیث ابراہیم میں ان کا ذکر آتا ہے جو ابراہیم بن عبد الاعلی عن جدتہ عن ابیھا یزید بن حنظلہ کی سند سے مروی ہے کہ ہم سفر پہ نکلے، ہمارے ساتھ وائل بن حجر تھے۔ انہیں ان کے دشمن نے پکڑ لیا، ان لوگوں نے تم کھائے بغیر نہ چھوڑا۔ تو انہوں نے اللہ کی قسم کھائی کہ یہ میرا بھائی ہے۔ (حدیث)(1) اسے بغوی نے عن ہارون الحمال عن یزید بن ہارون بحوالہ ان کے نقل کیا: یزید، اور دوسری بار کہا: سوید بن حنظلہ، انہیں اس میں شک ہے۔\nمیں کہتا ہوں: امام احمد رحمہ اللہ(2) نے اسے عن یزید بلا شک عن سوید نقل کیا ہے، یہی قول بغوی کا ہے۔ یزید کے علاوہ لوگوں نے اسے اسرائیل سے نقل کیا ہے۔\nمیں کہتا ہوں: وہ روایت ابو داؤد اور ابن ماجہ وغیرہ میں کئی طرق سے عن اسرائیل اسی طرح مروی ہے۔ یزید کا اس میں ذکر کرنا وہم ہے۔","",{"fn":"(1) ابو داؤد کتاب الایمان باب المعاریض فی الیمین (۳۲۵۶) ابن ماجہ (۲۱۱۹) مسند احمد (۷۹/۴)\n(2) مسند احمد (۱۱۸/۴)"}],[9406,"§۹۴۴۳ ۔ یزید بن خارجہ انصاری\nابن فتحون نے بحوالہ بغوی ان کا اپنے استدراک میں ذکر کیا ہے، جو لفظی غلطی سے پیدا ہونے والا وہم ہے۔ بغوی فرماتے ہیں: سوید بن معاویہ عن عثمان بن حکیم عن خالد بن سلمہ عن موسیٰ بن طلحہ عن یزید بن خارجہ انخزرجی کی سند سے ہم سے بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: ہم آپ پہ کیسے درود بھیجا کریں۔۔۔۔ (حدیث)(1) درست زید ہے، اسی روایت کو بغوی نے وہاں دو طریق سے بحوالہ عثمان نقل کیا ہے۔ اسی طرح بطریق عیسیٰ بن یونس عن عثمان مسند احمد اور نسائی میں ہے۔ اور ابن ابی عاصم نے بطریق عیسیٰ نقل کی تو ہے لیکن انہوں نے خارجہ بن یزید کہا جو الٹ ہے۔ اس میں سوید کو ایک اور وہم ہوا ہے چنانچہ ابو نعیم نے بطریق مطین بحوالہ ان کے نقل کیا ہے، فرمایا: یزید بن حارثہ۔ ان کے والد کا نام بدل دیا، درست خارجہ ہے۔ واللہ اعلم","",{"fn":"(1) نسائی کتاب السہو باب نوع آخر (۱۲۸۶، ۱۲۸۷، ۱۲۸۸)"}],[9407,"§۹۴۴۴ ۔ یزید بن حمیر العرنی\nسیدنا معاویہ رضی اللہ عنہ کی امارت میں حمص فروکش ہوئے۔ ابن شاہین نے ان کا ذکر کیا ہے جو ان کا وہم ہے۔ اس واسطے کہ یہ مشہور تابعی ہیں۔ ان کے سب سے بڑے شیخ ابو درداء رضی اللہ عنہ ہیں۔ امام بخاری، ابن ابی حاتم اور ابن حبان نے تابعین میں ان کا ذکر کیا ہے۔"],[9408,"§۹۴۴۵ ۔ یزید بن سَلَمہ\n(1) بغوی نے ان کا ذکر کیا ہے اور بطریق سعید بن مسروق عن ابن اشوع عن یزید بن سلمہ روایت کی ہے کہ میں نے عرض کی: اللہ کے رسول! میں نے آپ کی بہت سی احادیث سنی ہیں مجھے خدشہ ہے میں انہیں بھول نہ جاؤں۔۔۔۔ (حدیث)(2) بغوی لکھتے ہیں: میرے خیال میں یہ جعفی کے علاوہ ہیں۔\nمیں کہتا ہوں: اسے ابن مندہ نے بطریق ابن اشوع نقل کیا تو کہا: عن یزید بن سلمہ الجعفی اور ترمذی نے اسی طرح روایت کی ہے۔ قسم اول میں درست نام بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۵۴) استیعاب (۱۳۷/۴) تجرید (۱۳۷/۲)\n(2) جامع المسانید (۴۲۹/۱۲) المعجم الکبیر (۲۴۲/۲۲) التاریخ الکبیر (۳۴۰/۴)"}],[9409,"§۹۴۴۶ ۔ یزید بن صحار\n(1) ابو بکر بن علی نے ان کا ذکر کیا ہے اور بطریق اسماعیل بن عیاش عن ابن خثیم عن جعفر بن یزید بن صحار العبدی عن ابیہ مرفوع روایت کی ہے: ٹھیکری، مٹکے اور درخت کے چھید میں (بنا) کوئی مشروب نہ پیا جائے۔(2)\nمیں کہتا ہوں: اسماعیل سے نقل کرنے والے کسی راوی سے غلطی ہوئی ہے، یہ تو زید ہیں، ابن مندہ نے ایک اور طریق سے عن اسماعیل نقل کیا تو فرمایا: عن جعفر بن زید عن ابیہ جو درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۶۳) تجرید (۱۳۸/۲)\n(2) جامع المسانید (۴۳۴/۱۲)"}],[9410,"§۹۴۴۷ ۔ یزید بن طلحہ\n(1) ابن رکانہ۔ بقول المستغفری: یحییٰ بن یونس شیرازی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق مالک(2) عن سلمہ بن صفوان۔ بحوالہ ان کے مرفوع روایت کی ہے: \"ہر مذہب کے اوصاف ہوتے ہیں، دین اسلام کا وصف خاص حیاء ہے\"۔ بغوی لکھتے ہیں: یہ مرسل روایت ہے اور یہ یزید، محمد بن طلحہ بن رکانہ مشہور تابعی کے بھائی ہیں۔ ابن ابی حاتم(3) فرماتے ہیں: اپنے والد اور محمد ابن الحنفیہ سے روایت کرتے ہیں۔ ابن حبان ثقات التابعین میں ان کا ذکر کرتے ہیں کہ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں، ہشام بن عبد الملک کی خلافت کے آغاز میں فوت ہوئے۔ ابن عبد البر لکھتے ہیں: امام مالک رحمہ اللہ کے تمام تلامذہ کا کہنا بھی یہی ہے، صرف ایک وکیع کہتے ہیں: عن یزید بن طلحہ عن ابیہ انہوں نے عن ابیہ کا اضافہ نقل کیا ہے۔ لکھتے ہیں: یحییٰ بن یحییٰ اللیثی کی روایت جمہور کی طرح ہے۔ انہوں نے یزید کی جگہ زید کہا۔ ابن عبد البر فرماتے ہیں: بقول وکیع حدیث مسند ہے۔ اور خود استیعاب میں طلحہ کا ذکر نہیں کیا۔ جس کا ان پہ ایک اور تعاقب ہے۔ اس واسطے کہ دار قطنی نے جو روایت غرائب مالک میں بطریق وکیع نقل کی ہے وہ عن مالک عن سلمہ عن یزید بن رکانہ عن ابیہ ہے۔ اس بنا پر صحابی رکانہ ہوئے۔ دار قطنی فرماتے ہیں: اسے علی بن زید الصدرائی نے عن مالک اسی طرح نقل کیا ہے، لیکن یزید بن طلحہ بن رکانہ کہا۔","",{"fn":"(1) اسد الغابہ (۵۵۶۶) تجرید (۱۳۸/۲)\n(2) موطا مالک کتاب حسن الخلق (۱۷۲۵)\n(3) الجرح والتعدیل (۲۷۳/۹)"}],[9411,"§۹۴۴۸ ۔ یزید بن عبد اللہ بن رکانہ\nابن المطلب المطلسی۔ کسی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے، جس کی وجہ ایک مرسل حدیث ہے جسے بیہقی نے \"الدعوات\" میں بطریق ابراہیم بن المندر عن الحسن بن زید عن جعفر بن محمد عن ابیہ عن یزید بن عبد اللہ بن رکانہ بن المطلب کی سند سے نقل کیا ہے۔ فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم کے پاس کوئی جنازہ لایا جاتا تو آپ فرماتے: اے اللہ! یہ تیرا بندہ تیرے بندے کا بیٹا تیری رحمت کا محتاج ہے۔۔۔۔ (الحدیث)(1)","",{"fn":"(1) المعجم الکبیر (۲۷۷/۸) المصنف لعبد الرزاق (۶۴۲۰)"}],[9412,"§۹۴۴۹ ۔ یزید بن عبد اللہ بن الشخیر\n(1)(2) ابو العلاء اکابر تابعین میں سے ایک، ابو موسیٰ ذیل میں لکھتے ہیں: یحییٰ بن عبد الوہاب بن مندہ نے اپنے دادا کی کتاب پہ اپنے استدراک میں ان کا ذکر کیا ہے اور بطریق ہشیم عن یونس بن عبید عن یزید بن عبد اللہ بن الشخیر روایت کی ہے۔ میرے خیال میں انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ جو کچھ بندے کو عطا کرتا ہے اس میں اس کی آزمائش کرتا ہے، اگر وہ راضی رہے تو اسے برکت دیتا ہے اور اگر ناراض ہو تو برکت اٹھا لیتا ہے۔(3)\nکسی کا یہ کہنا ہے کہ میرے خیال میں انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے، غلط ہے، اس واسطے کہ امام بخاری رحمہ اللہ نے اپنی تاریخ میں(4) نقل کیا ہے کہ یہ حضرت حسن بصری سے دس سال پہلے پیدا ہوئے اور حضرت حسن بصری کی ولادت خلافت فاروقی کے آخر میں ہوئی۔ لہذا یزید کی ولادت خلافت صدیقی میں ہوئی۔","",{"fn":"(1) اسد الغابہ (۵۵۷۴) تجرید (۱۳۹/۲)\n(2) التاریخ الکبیر (۳۴۵/۴) جمع الجوامع (۵۱۶۳) جامع المسانید (۴۳۸/۱۲) الجرح والتعدیل (۲۷۴/۹)\n(3) الطبقات الکبریٰ (۱۵۵/۷)\n(4) التاریخ الکبیر (۳۴۵/۴)"}],[9413,"§۹۴۵۰ ۔ یزید بن عبد الرحمن\n(1) ابو نعیم نے ان کا ذکر کیا اور یہ مرفوع روایت نقل کی ہے: اپنے غلاموں کا خیال رکھو! اپنے غلاموں کے بارے میں احتیاط برتو!۔۔۔۔ (حدیث)(2) ابو نعیم فرماتے ہیں: بقول بعض: یہ یزید بن جاریہ۔ ابن الاثیر(3) نے فرمایا: یہ بلاشبہ وہی ہیں۔ مذکورہ حدیث ان کے حالات میں بیان ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۷۸) تجرید (۱۳۹/۲)\n(2) مسند احمد (۳۶/۴) المعجم الکبیر (۲۴۲/۲۲) مجمع الزوائد (۲۳۶/۴) کنز العمال (۲۵۰۱۳)\n(3) اسد الغابہ (۳۴۷/۴)"}],[9414,"§۹۴۵۱ ۔ یزید بن عبد المزنی حجازی\n(1) ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور ابن ماجہ نے بطریق ایوب بن موسیٰ بحوالہ ان کے مرفوع روایت کی ہے: \"لڑکے کی طرف سے عقیقہ کیا جائے گا\"۔(2) یہ یزید تابعی ہیں۔ امام بخاری رحمہ اللہ فرماتے ہیں: انہوں نے تو یہ حدیث عن ابیہ عن النبی صلی اللہ علیہ وسلم روایت کی ہے، نیز ان کے والد کے صحابی ہونے کا ثبوت نہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۸۰)\n(2) ابن ماجہ کتاب الذبائح باب العقیقۃ (۳۱۶۶) فتح الباری (۵۹۴/۹) کنز العمال (۴۵۲۸۵) جامع المسانید (۴۳۷/۱۲)"}],[9415,"§۹۴۵۲ ۔ یزید بن عبید السلمی ابو وجزہ\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ اور بطریق ابن ابی ذئب عن عبد اللہ بن محمد بن عمرو بن حاطب عن ابی وجزہ یزید بن عبید روایت کی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک سے واپس ہوئے تو آپ کے پاس بنی فزارہ کا وفد آیا، جن میں خارجہ ابن حصین اور حارث بن قیس تھے۔ جو سب سے کم سن تھے۔ یہ لوگ رملہ بنت حارث کی حویلی میں فروکش ہوئے۔ یہ مرسل ہے ابو وجزہ تابعی ہیں جو سعدی سے مشہور ہیں۔ واقدی نے مغازی میں یہ حدیث اسی سند سے نقل کی تو اس کے سیاق میں کہا: عن ابی وجزہ السعدی۔ مرزبانی نے مبرد سے نقل کیا ہے: ابو وجزہ اصلاً سلمی ہیں، انہیں سعدی اس وجہ سے کہا جاتا ہے کہ وہ بنی سعد میں فروکش ہوئے تھے۔\nمیں کہتا ہوں: حدیث ان کے مراسیل سے مذکور ہے اور ابو وجزہ کی یہ حدیث السنن میں عن عمرو بن ابی سلمہ المخزومی پروردہ نبی صلی اللہ علیہ وسلم موجود ہے۔ مشہور شاعر ہیں، مدینہ کے رہائشی تھے اور وہیں ۱۳۰ھ میں فوت ہوئے۔"],[9416,"§۹۴۵۳ ۔ یزید بن عمر\n(1) مستغفری نے انہیں صحابہ رضی اللہ عنہم میں شمار کیا ہے اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابو عمر نے ان کا ذکر تو کیا ہے لیکن کہا: یزید بن عمرو، میں نے اس بارے میں اختلاف قسم اول میں بیان کر دیا ہے۔","",{"fn":"(1) تجرید (۱۳۹/۲)"}],[9417,"§۹۴۵۴ ۔ یزید بن عمرو\n(1) مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق ایوب عن میمون بن مہران روایت کی ہے: میری طرف ابن عمر رضی اللہ عنہما نے خط بھیجا۔ رسول اللہ صلی اللہ علیہ وسلم کا سیدہ میمونہ رضی اللہ عنہا سے نکاح کے بارے میں یزید بن عمرو سے پوچھو! میں نے ان سے پوچھا تو انہوں نے فرمایا: \"آپ نے حل (حرم سے باہر) میں ان سے نکاح کیا تھا\"۔(2)\nمیں کہتا ہوں: یہ یزید وہی یزید بن الاصم ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے۔ قسم ثانی میں ان کا ذکر ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۸۵) تجرید (۱۳۹/۲)\n(2) مسلم کتاب النکاح باب تحریم نکاح المحرم (۴۸) ابو داؤد (۱۸۴۳) ترمذی (۸۴۵) ابن ماجہ (۱۹۶۴) سنن الدارمی (۳۸/۲)"}],[9418,"§۹۴۵۵ ۔ یزید بن کعب\n(1) بقول بعض: یہ ان بہری کا نام ہے جن کا ذکر حدیث عمیر بن سلمہ الضمری میں ملتا ہے۔ جن کا تذکرہ ان کے حالات میں ہو چکا ہے۔ ابن عبد البر(2) نے ان کا ذکر کیا ہے۔ درست زید ہے جیسا کہ پہلے بیان ہو چکا۔ الدار قطنی وغیرہ نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۵۹۵) استیعاب (۱۴۱/۴) تجرید (۱۴۰/۲)\n(2) استیعاب (۱۴۱/۴)"}],[9419,"§۹۴۵۶ ۔ یزید بن محمد\n(1) عبد خیر کے والد۔ اسی طرح ابن فتحون ابن الامین اور ذہبی نے ان کا ذکر کیا ہے، جبکہ درست یزید بن محمد ہے۔","",{"fn":"(1) تجرید (۱۴۰/۲)"}],[9420,"§۹۴۵۷ ۔ یزید بن المُزَین\n(1) ابن قیس بن عدی بن امیہ انصاری الخزرجی۔ بقول ابو عمر: یہ نام واقدی(2) نے ذکر کیا ہے جبکہ جمہور زید بتاتے ہیں، جو درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۰۰) استیعاب (۲۸۲۳) تجرید (۱۴۰/۲)\n(2) استیعاب (۱۴۱/۴)"}],[9421,"§۹۴۵۸ ۔ یزید بن معبد\n(1) القیسی الربعی الیمامی۔ جس نے انہیں یزید بن معبد الحنفی الدولی کے علاوہ قرار دیا ہے، اس سے وہم ہوا ہے بلکہ یہ ایک ہی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۰۲) استیعاب (۲۸۲۴) تجرید (۱۴۰/۲)"}],[9422,"§۹۴۵۹ ۔ یزید بن المعتمر النمیری\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے جو ان کا وہم ہے۔ یہ تو یزید بن نمیر ہیں جن کا ابو عمر نے ذکر کیا ہے۔"],[9423,"§۹۴۶۰ ۔ یزید بن نعیم\n(1) ابن ہزال الاسلمی مشہور تابعی۔ ایک مرسل حدیث بیان کی ہے تو الاثیری نے اپنے استدراک میں اور ابن الاثیر(2) نے ان کی خوشہ چینی میں ان کا ذکر کیا ہے جو وہم ہے۔ ان کی حدیث مسند بقی بن مخلد سے شامل کی ہے جو ان کی اپنے والد سے روایت سے مروی ہے۔ امام بخاری،(3) مسلم، ابن ابی حاتم(4) اور ابن حبان وغیرہ نے انہیں تابعین میں شمار کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۰۹) تجرید (۱۴۱/۲)\n(2) اسد الغابہ (۲۵۲/۴)\n(3) التاریخ الکبیر (۳۶۴/۴)\n(4) الجرح والتعدیل (۲۹۲/۹)"}],[9424,"§۹۴۶۱ ۔ یزید بن نمران شامی\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا جو ان کا وہم ہے ان کی روایت تو عن المنقد بحوالہ اس شخص کے جو نبی صلی اللہ علیہ وسلم کے پاس سے اس وقت گزرا جب آپ تبوک میں نماز پڑھ رہے تھے۔ ابن ابی حاتم(1) فرماتے ہیں: یزید بن نمران نے فرمایا: میں نے تبوک میں ایک پانچ صحابی دیکھا۔ لگتا ہے ابن شاہین نے سمجھا کہ \"لہ صحبتہ\" کی ضمیر یزید کی طرف ہے حالانکہ وہ پانچ شخص کی طرف راجع ہے۔","",{"fn":"(1) الجرح والتعدیل (۲۹۲/۹)"}],[9425,"§۹۴۶۲ ۔ یزید ابو عبد اللہ\n(1) پہلے بیان ہوا یہ غلط ہے۔","",{"fn":"(1) تجرید (۱۳۹/۲)"}],[9426,"§۹۴۶۳ ۔ یزید\n(1) عبد اللہ انظمی کے والد۔ یہ حدیث \"مصیبت زدہ تو وہ ہے جس نے آگے کوئی اولاد نہیں بھیجی\"۔ انما الرقوب۔۔۔۔ روایت کی ہے۔ اس میں تامل ہے۔ ابن مندہ اور ابن الاثیر(2) نے اسی طرح نقل کیا ہے جو ان کا وہم ہے اس لیے محمد ثمین نے ان کا ذکر کیا ہے وہ یزید بن حصین ہیں۔","",{"fn":"(1) اسد الغابہ (۵۵۷۶) استیعاب (۱۴۲/۴) تجرید (۱۳۹/۲)\n(2) اسد الغابہ (۳۴۷/۴)"}],[9427,"§۹۴۶۴ ۔ یزید ابو ہانی الحنفی\n(1) ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور بطریق ہانی بن یزید عن ابیہ روایت کی ہے کہ ان کے بھائی بشر بن معبد و حارث بن ظفر کی لڑائی ہو گئی۔ انہیں ان کا اپنے استدراک میں شامل کرنے سے وہم ہوا کیونکہ یہ تو وہی یزید بن معبد ہیں جن کا ابن مندہ نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۱۱) تجرید (۱۴۱/۲)"}],[9428,"§۹۴۶۵ ۔ یزید العقیلی\n(1) ایک مرسل حدیث بیان کی ہے جس کی وجہ سے مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کر دیا ہے اور لکھتے ہیں: مجھے ان کا صحابی ہونا معلوم نہیں۔\nمیں کہتا ہوں: ابن ابی حاتم(2) نے جزم سے لکھا ہے کہ ان کی حدیث مرسل ہے جسے بقیہ نے عن نافع بن یزید عن نافع بن سلیمان عن یزید العقیلی نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عنقریب میری امت میں ایسے لوگ ہوں گے جن کی وجہ سے اللہ تعالیٰ حدود (ملکی) کو بدر گئے گا\"۔ (حدیث)","",{"fn":"(1) اسد الغابہ (۵۵۶۲) تجرید (۱۳۹/۲)\n(2) الجرح والتعدیل (۳۰۱/۹)"}],[9429,"§۹۴۶۶ ۔ یزید (حکیم کے والد)\n(1) ان کی حدیث حماد بن سلمہ نے عن عطاء بن السائب عن حکیم بن یزید عن ابیہ کی سند سے نقل کی ہے، درست یوں ہے: عن حکیم بن ابی یزید، جیسا کہنیوں میں بھی تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۵۵۳۸) استیعاب (۲۸۲۹) تجرید (۱۳۶/۲)"}],[9430,"§۹۴۶۷ ۔ یسار بن نُمیر ابو لیلیٰ\n(1) مولا بنی عمرو بن عوف۔ فرضی نے المؤتلف میں ان کا ذکر کیا ہے۔ ابن الاثیر نے اپنے استدراک میں ان کا ذکر کیا ہے اور تجرید(2) میں انہی کی خوشہ چینی کی گئی ہے۔ یہ ابو لیلیٰ عبد الرحمن کے والد ہیں، جس نے ان دونوں میں فرق کیا ہے، اس سے وہم ہوا۔ ابو عمر نے ان کے نام میں اختلاف ذکر کیا ہے۔ ان کے متعلق تمام اقوال میں سے ایک قول ہے \"یسیر بن نمیر\" جو امام بخاری(3) اور کا قول ہے جیسا کہ پہلے بیان ہوا ہے۔","",{"fn":"(1) تجرید (۱۴۲/۲)\n(2) تجرید (۱۴۲/۲)\n(3) التاریخ الکبیر (۴۲۰/۴)"}],[9431,"§۹۴۶۸ ۔ یُسیر\nابن عبد اللہ، جھوٹوں میں سے ایک جس نے صحابی ہونے کا دعویٰ کیا ہے۔ حسین بن خارجہ کا گمان ہے اس کی مصر میں اس سے ملاقات ہوئی ہے اس نے اس سے ذکر کیا کہ اس کی عمر تین سو(۳۰۰) سال ہے۔ حافظ ابن عساکر رحمہ اللہ نے \"السباعیات\" میں بطریق حسین بن خارجہ بحوالہ اس کے کئی احادیث نقل کی ہیں۔ ذہبی میزان میں لکھتے ہیں: اس تک کی سند میں ظلمات ہیں۔ میر۔ دو مشہور اشعار میں اس کا ذکر ملتا ہے جس کے مطلع میں حدیث ابن نسطور یسیر اور نعیم ہے۔ وہ نعیم یہی میسر ہے، کچھ ہی دیر بعد نعیم ذکر ہوگا۔"],[9432,"§۹۴۶۹ ۔ الیسع بن المغیرہ المخزومی\nچھوٹے مشہور تابعی ہیں، حاکم نے ان کی حدیث اپنے متدرک میں نقل کی ہے جسے بطریق اسماعیل بن ابی اویس عن محمد بن طلحہ التمیمی عن عبد الرحمن بن ابی بکر بن المغیرہ نقل کیا ہے کہ \"رسول اللہ صلی اللہ علیہ وسلم بازار میں ایک آدمی کے پاس سے گزرے جو بازاری نرخ سے کم بھاؤ پہ اناج بیچ رہا تھا۔۔۔۔\"۔ (حدیث) جس سے حاکم نے سمجھ لیا یہ صحابی ہیں، یہ تو تابعی ہیں۔ حالانکہ ابو داؤد نے مراسیل میں ان کی حدیث بطریق الزبیر بن سعید عن الیسع بن المغیرہ نقل کی ہے کہ خالد بن ولید نے رسول اللہ صلی اللہ علیہ وسلم سے اپنے گھر کی تنگی کی شکایت کی تو آپ نے فرمایا: رونے میں کشادگی اختیار کرو، طبرانی نے اسے المیج مذکور روایت میں عن ابیہ عن خالد بن ولید موصولاً ذکر کیا ہے۔ الیسع کو عطاء بن ابی رباح، محمد بن سیرین وغیرہ سے بھی روایت حاصل ہے۔ ابو حاتم الرازی ان کے بارے میں کہتے ہیں: قوی نہیں۔ جبکہ ابن ابی حاتم(1) اور ابن حبان نے ثقات التابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۳۰۸/۹)"}],[9433,"§۹۴۷۰ ۔ یُسیر ابن العنبس انصاری\n(1) ابن الاثیر(2) نے اپنے استدراک میں ان کا ذکر کیا ہے جو ان کا وہم ہے، یہ نام تو نون سے ہے، پہلے درست بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۳۵) تجرید (۱۴۲/۲)\n(2) اسد الغابہ (۳۶۰/۴)"}],[9434,"§۹۴۷۱ ۔ یُسیر بن یزید انصاری\n(1) بیہقی نے الشعب میں بطریق محمد بن اسحاق البلخی عن عمرو بن قیس عن ابیہ عن جدہ عن خالد روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"احمق محروم ہوا\"۔ پھر بیہقی اپنے شیخ حاکم سے روایت کرتے ہیں کہ قیس کے دادا کا نام یسیر بن یزید انصاری ہے اور ان کی اسانید بہت شتم ہیں، بیہقی نے اپنے شیخ پر اس کی نکیر کی ہے وہ لکھتے ہیں: صحابہ رضی اللہ عنہم میں یسیر بن یزید نامی کوئی بھی نہیں۔ یہ تو یسیر بن عمرو ہیں مخزومی تابعی ہیں۔ پھر مذکورہ حدیث بطریق یعقوب بن سفیان عن ابی سعید الاشج عن عمرو بن قیس انھی الفاظ میں نقل کی ہے۔ مرفوع بیان نہیں کی۔ فرماتے ہیں: ایک موقوف زیادہ صحیح ہے۔ قسم ثالث میں یسیر بن عمرو کا ذکر ہو چکا ہے اس کا اول (پہلا حرف) ہمزہ سے بدل جاتا ہے، حرف الف میں اس کی طرف اشارہ ہوا ہے۔","",{"fn":"(1) استیعاب (۲۸۴۱)"}],[9435,"§۹۴۷۲ ۔ یعقوب بن اوس الثقفی\n(1) مشہور تابعی ہیں۔ بقول بعض: ان کا نام عقبہ ہے۔ ابن ابی خیثمہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، جو وہم ہے۔ بغوی ان کی شبہ عمد کے بارے میں مرفوع روایت کرتے ہیں: بغوی لکھتے ہیں: یہ سند ابی خیثمہ سے شک کے ساتھ ہے اور ہم سے یہ روایت احمد بن ابی خیثمہ نے عن ابیہ بیان کی اس کی یا کسی صحابی سے۔\nمیں کہتا ہوں: ابن ابی خیثمہ اس حدیث کو نقل کرنے کے بعد فرماتے ہیں: یعقوب صحابی نہیں۔ یہ روایت تو انہوں نے عبد اللہ ابن عمرو سے نقل کی ہے۔ اور یہ حدیث ابو داؤد کی کتاب مس بروایت حماد بن یزید و وہیب بن خالد دونوں عن خالد الحذاء عن القاسم بن ربیعہ عن عقبہ بن اوس عن عبد اللہ بن عمرو ودی ہے۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے روز خطاب فرمایا، پھر ایک حدیث ذکر کی۔ اس میں ہے: \"خطا کی دیت شبہ العمد جب تک کوڑوں اور لاٹھی سے مارا گیا ہو سو(۱۰۰) اونٹ ہے ان میں چالیس حاملہ اونٹنیاں رہی ہوں گی\"۔(2) یہی روایت نسائی نے بطریق حماد بن زید نقل کی تو کہا: عن عقبہ بن اوس عن رجل من الصحابہ اور بطریق ابن ابی عدی عن خالد عن القاسم عن عقبہ بن اوس نقل کی رسول اللہ صلی اللہ علیہ وسلم نے فرمایا۔۔۔۔ پھر وہ حدیث مرسلاً ذکر کی۔ جو بطریق بشر بن المفضل و یزید بن زریخ دونوں عن خالد و وہیب کی روایت جیسی روایت کرتے ہیں لیکن صحابی رضی اللہ عنہ کا نام نہیں لیا۔ اور قاسم کے شیخ کا نام یعقوب بتایا ہے۔ ابو داؤد نے اس میں قاسم بن ربیعہ سے آگے ایک اور اختلاف بھی ذکر کیا ہے۔ آیا یہ عبد اللہ بن عمرو ہیں یا ابن عمر؟ اس لیے کہ قاسم اور ان کے درمیان کوئی نہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۳۶) استیعاب (۲۸۴۲)\n(2) ابو داؤد کتاب الدیات باب فیمن قتل فی عمیاء بین قوم (۴۵۹۱) نسائی کتاب القسامۃ باب من قتل بحجر او سبوط (۴۸۰۳)"}],[9436,"§۹۴۷۳ ۔ یعلی بن حازم الثقفی\n(1) حلیف بنی زہرہ، یمامہ میں شہادت پائی۔ تجرید میں اسی طرح لکھا ہے جو وہم ہے ان کے والد کا نام غلط لکھ دیا ہے یہ تو ابن جاریہ ہیں پہلے ذکر ہو چکا ہے۔","",{"fn":"(1) تجرید (۱۴۴/۲)"}],[9437,"§۹۴۷۴ ۔ یعلی بن صفوان\nابن امیہ، ابن فتحون نے بحوالہ مغازی اموی ان کا اپنے استدراک میں ذکر کیا ہے کہ فتح مکہ کے بعد یعلی بن صفوان بن امیہ اپنے بیٹے کو ہجرت کی بیعت کرانے نبی صلی اللہ علیہ وسلم کے پاس لائے۔ ابن قانع نے بھی اسی طرح نقل کیا ہے جو الٹ ہے اس میں کسی راوی کو وہم ہوا ہے، درست ہے۔ عن مجاہد عن صفوان بن یعلی بن امیہ ہے کہ یعلی اپنے بیٹے کو لائے، اس سے ابن فتحون نے خبردار کیا ہے۔ صفوان ابن یعلی بن امیہ مشہور تابعی ہیں۔"],[9438,"§۹۴۷۵ ۔ یعلی بن طَلق\n(1) ابن قانع نے ان کا ذکر کیا ہے، جو وہم ہے۔ یہ تو علی بن طلق ہیں چنانچہ ابن قانع اپنی سند سے عن جعفر بن عوف عن یحییٰ بن سعید عن محمد بن المنکدر عن یعلی بن طلق مرفوع روایت کرتے ہیں: \"آدمی نماز تو پڑھتا ہے لیکن جو اس کا (اصل) وقت رہ جاتا ہے وہ اس کے اہل و عیال اور مال سے زیادہ افضل ہے\"۔(2)","",{"fn":"(1) تجرید (۱۴۴/۲)\n(2) مجمع الزوائد (۲۹۷/۳) السنن الکبریٰ (۱۴۵/۴) کنز العمال (۱۷۳۰۱)"}],[9439,"§۹۴۷۶ ۔ یعلی (بے نسبت)\n(1) ابن قانع نے ان کا ذکر کیا ہے اور بطریق ولید بن مسلم عن سفیان عن عمرو بن یعلی عذابیہ کی سند سے روایت نقل کی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور میرے ہاتھ (کی انگلی) میں سونے کی انگوٹھی تھی۔ فرمایا: کیا تم اس کی زکوۃ ادا کرتے ہو؟ میں نے عرض کی: کیا اس کی بھی زکوۃ ہے؟ آپ نے فرمایا: (پھر تو) یہ مونثا انگارہ ہے۔(2)\nمیں کہتا ہوں: یہ یعلی ابن ابی مرہ ہیں جیسا کہ طبرانی نے جب یہ حدیث نقل کی تو اعتماد سے کہا۔ جبکہ درست یہ ہے ان سے روایت کرنے والے عمر جو ہیں وہ اپنے دادا کے نسب عمر بن عبد اللہ بن یعلی بن خضر سے ذکر ہوئے جو مشہور ہیں ان کے اپنے والد سے بحوالہ دادا کئی احادیث ہیں۔ ریا ح ثقفنی کے حالات میں اس متن پر کچھ بحث ہو چکی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۴۵) تجرید (۱۴۴/۲)\n(2) مسند احمد (۱۷۱/۴) مجمع الزوائد (۶۶/۳) السنن الکبریٰ (۱۴۵/۴) کنز العمال (۱۷۲۰۱)"}],[9440,"§۹۴۷۷ ۔ یعلی (بے نسبت، دوسرے)\n(1) ابن فتحون نے بحوالہ یحییٰ بن یحییٰ تیمی عن عمرو بن عثمان عن ابیہ عن یعلی، ذیل میں ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ رضی اللہ عنہم ایک تنگ مقام پر پہنچے، جہاں آپ نے انہیں اپنی سواری پہ نماز پڑھائی، سجدہ رکوع اشارے سے تھا، سجدہ کا جھکاؤ رکوع کی بہ نسبت زیادہ تھا۔(2)\nمیں کہتا ہوں: یہ یعلی بھی ابن مرہ ہیں، ترمذی نے یہی روایت نقل کر کے تبصرہ کیا ہے کہ غریب ہے اس میں عمر بن الرماح منفرد ہے اور اسے الدار قطنی نے اسی سند سے نقل کیا تو کہا: یعلی بن امیہ، ہمارے شیخ شرح ترمذی میں شبابہ کی روایت کو ترجیح دی ہے۔ ہر تقدیر و صورت یہ یعلی اور ہیں۔","",{"fn":"(1) تجرید (۱۴۴/۲)\n(2) ابو داؤد کتاب الصلاۃ باب التطوع علی الراحلۃ والوتر (۱۲۲۷) نسائی (۱۱۸۸) ابن ماجہ (۱۰۱۸) مسند احمد (۳۲۴/۲)"}],[9441,"§۹۴۷۸ ۔ یوسف الانصاری\n(1) ابن قانع نے ان کا ذکر کیا ہے اور یہ روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منبر پر چڑھ کر فرمایا: \"لوگو! ابو بکر نے مجھے کبھی اذیت نہیں پہنچائی تو تم لوگ بھی اس بات کی وجہ سے ان کا لحاظ کرنا\"۔۔۔۔ (حدیث)(2) ہمارے شیخ الشیوخ العلائی فرماتے ہیں: یہ وہم ہے درست عن سہل بن یوسف بن سہل عن ابیہ عن جدہ ہے، ان کے دادا کا نام سہل بن حنیف ہے۔ ابن قانع نے یہی روایت دوسرے مقام پر بطریق محمد بن یونس عن خالد بن عمرو و ثق نقل کیا ہے۔ علائی فرماتے ہیں: یہ زیادہ مناسب ہے۔\nمیں کہتا ہوں: اسے ابن عساکر نے پہلے کی طرح نقل کیا ہے، جبکہ زکریا بن یحییٰ نے عن سلیمان بن داؤد عن خالد بن عمر عن سہل بن یوسف بن سہل بن مالک عن ابیہ عن جدہ اسی طرح زعفرانی نے عن زکریا نقل کیا ہے۔ خلیعات میں ہمیں بطریق ابی سعید الاعرابی عن الزعفرانی لکھی ملی ہے۔","",{"fn":"(1) تجرید (۱۴۵/۲)\n(2) المعجم الکبیر (۱۲۶/۶) کنز العمال (۳۳۱۳۹) (۳۵۶۴۵) لسان المیزان (۴۲۴/۳) (۷۱۹/۴) مختصر تاریخ دمشق (۱۲۹/۶)"}],[9442,"§۹۴۷۹ ۔ یونس انصاری ظفری ابو محمد\n(1) بقول ابن مندہ اہل مدینہ میں شمار ہوتے ہیں۔ ابن شاہین نے ان کا ذکر کیا ہے، پھر انہوں نے، ابن مندہ اور ابو نعیم نے بطریق ابن ابی فدیک عن ادریس بن محمد بن یونس ظفری عن ابیہ عن جدہ روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مونچھیں کاٹا کرو\"۔(2) ہمارے شیخ الشیوخ علائی نے فرمایا: یہ وہم ہے، درست ادریس بن محمد بن یونس بن انس بن فضالہ عن ابیہ عن جدہ یونس عن ابیہ محمد بن انس بن فضالہ ہے۔ یہ سند ابن مندہ نے محمد بن انس کے سوانح میں درست نقل کی ہے، جیسا قسم اول میں بیان ہو چکی ہے۔\nمیں کہتا ہوں: کنیتوں کے آخر میں بیان ہوگا کہ ابن ابی عاصم نے یہ عنوان ابو یونس کے لیے قائم کیا ہے اور اسی طریق سے عن ادریس بن محمد بن یونس عن جدہ یونس عن ابیہ روایت کی ہے کہ وہ حجۃ الوداع میں شریک تھے، اس وقت وہ بیس(۲۰) سال کے تھے، اس سے علائی کے اعتراض کو تقویت ملتی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۶۵۶)\n(2) السنن الکبریٰ (۱۵۰/۱) کنز العمال (۱۷۲۲۳) جامع المسانید والسنن (۵۰۰/۱۲)"}],[9443,"§اختتام جلد 6\nاس کتاب کے مؤلف (اللہ ان سے راضی ہو) فرماتے ہیں: میری کتاب حواشی کے ساتھ تین ذوالحجہ ۸۲۴ھ مکمل ہوئی۔ جس کی ابتداء آٹھ سو نو (۸۰۹) میں ہوئی تھی جو چالیس کے قریب ہے، لیکن اس کی کتابت تاخیر سے ہوئی۔ جو ترتیب میں نے اختیار کی تھی اس کی وجہ سے مسودات میں تین بار ہوئی۔ اب یہ تیسری بار ہے یہ نسخہ بھی مسودہ ہی ہے کیونکہ اس میں بکثرت الحاق کیا گیا ہے، دوسرے ناموں کے شامل کرنے سے تاامیدی حاصل نہیں ہوئی۔ پہلے میں نے سرخی پھر زردی سے پھر خالص صورت سے پھر اس سے حج جلتی حدوت سے اسامہ کو ممتاز کیا۔ یہ سب کچھ درجال ونساوہ کی فصل میں مہم سے پہلے کی کتاب ہے یہ مصنف کے الفاظ تھے انہی کے قلم سے ہم نے نقل کیے ہیں۔\nوالحمدللہ رب العالمین حمداً لا نھایۃ لہ وصلی اللہ علی سیدنا محمد و آلہ و صحبہ وسلّم تسلیماً کثیراً۔ آمین"],[9444,"§۹۳۸۰ ۔ ابوامیہ الفزاری(1)\nنہ کسی نے ان کا نام بتایا اور نہ نسب، ابونعیم اور یحییٰ بن معین کہتے ہیں: انہیں شرف صحابیت حاصل ہے۔ امام احمد(2) اور بغوی نے ابو جعفر الفراء رحمہ اللہ کی سند سے نقل کیا ہے، فرمایا: میں نے ابو امیہ رضی اللہ عنہ کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سینگی لگواتے دیکھا، اس کی سند قوی ہے، اسے سمویہ نے اپنے \"فوائد\" میں اور ابو علی بن السکن اور دیگر لوگوں نے اس سلسلے سے صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ بغوی کہتے ہیں: کسی نے ان کا نسب بیان نہیں کیا اور ان سے صرف یہ حدیث مروی ہے، ابو جعفر ان سے روایت کرنے میں متفرد ہیں ابو جعفر ثقہ ہیں اس نام کے متعلق اکثر علماء کہتے ہیں کہ مد اور میم کے زیر سے ہے جس کے بعد نون ہے۔ ابن عبدالبر نے ذکر کیا ہے کہ ابواحمد حاکم نے کنیتوں میں، ہمزہ کے پیش، میم کے زیر اور آخر میں یائے مشددہ سے ذکر کیا ہے۔ فرماتے ہیں: یہ کچھ بھی نہیں۔ میں کہتا ہوں: ابواحمد نے دو جگہ اس کا ذکر کیا ہے، پہلا مقام دوسرے کی طرح ہے، جبکہ انہوں نے الفزاری نہیں کہا، بلکہ یوں کہا ہے۔ انہوں نے نبی صلی اللہ علیہ وسلم کو پچھنے لگواتے دیکھا، پھر مذکورہ حدیث ذکر کی۔ اور دوسری، حرف الف کے افراد میں ہے اور الفزاری، ابن الاثیر(3) نے یہ گمان کیا ہے کہ ابو عمرو نے ان کا دو جگہ ذکر کیا ہے، وہاں بھی میں نے ایسا دیکھا ہے جیسا کہ میں نے ذکر کیا۔ ابن شاہین کو اس میں تردد ہے۔ اور ابن مندہ نے اس میں اختلاف ذکر کیا ہے اور اس بات کو درست قرار دیا ہے کہ یہ مد نون سے ہے اور ابن فتحون نے کہا ہے: میں نے \"ابن مُؤرج\" کی اصل کتاب میں، ابن السکن کی کتاب سے منقول: أَمَّة الف کے فتحہ اور میم سے بغیر مد کے لکھا دیکھا ہے۔ میں کہتا ہوں: ان کا بغیر مد کے کہنا، اگر الف کی زیادتی و اضافہ مراد ہے تو ٹھیک ورنہ ان کا قول ترک مد میں کوئی صریح اور حرف آخر نہیں ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۵۷) تجرید اسماء الصحابہ (۱۴۵/۲)\n(2) اخرجہ الامام احمد فی مسندہ (الحدیث: ۳۱۰/۴)\n(3) اسد الغابہ (۳۶۷/۴)"}],[9445,"§۹۳۸۱ ۔ ابوامیہ\nیہ دوسرے ہیں، جن لوگوں کی کنیت ابو آمنہ ہے، ان میں تذکرہ آئے گا۔"],[9446,"§۹۳۸۲ ۔ ابوابراہیم(1)\nسیدہ ام سلمہ رضی اللہ عنہا کے غلام ہیں۔ الحسن بن سفیان نے اپنی مسند میں ان کا ذکر کیا ہے اور یونس بن ابی اسحاق کی سند سے ان کے والد سے ابوابراہیم سے روایت کی ہے، فرمایا: \"(بچپن میں) قیس سیدہ ام سلمہ رضی اللہ عنہا کا غلام تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے بستر پر رات بسر کرتا اور آپ کے برتن سے وضو کرتا۔\"(2) ابو نعیم نے ان کی سند سے اور ابو موسیٰ نے بھی نقل کیا ہے، اس کی سند قوی ہے جبکہ باوردی نے اس سے مکمل روایت ذکر کی ہے، اس کے بعد ہے: \"پھر جب میں بالغ ہو گیا تو آپ نے مجھے آزاد کر دیا، اور فرمایا: ایسی جگہ چلے جاؤ کہ مجھے نظر نہ آؤ۔\" اگر اس روایت کے کسی سلسلے میں اس بات کی وضاحت ہوتی کہ وہ نبی صلی اللہ علیہ وسلم کے زمانے میں تھے (تب تو ان کا صحابی ہونا مانا جاتا) لیکن اس کا بس احتمال ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۵۹) تجرید اسماء الصحابہ (۱۴۶/۲۲)\n(2) ذکر ابن کثیر فی جامع المسانید والسنن (۵/۳) و ذکرہ ابن الاثیر فی اسد الغابہ (۳۶۷/۴)"}],[9447,"§۹۳۸۳ ۔ ابوابراہیم (بغیر منسوب)\nطبرانی اور عثمانی نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور دونوں نے جریر بن حازم کی سند سے ابوابراہیم سے نقل کیا ہے، فرمایا: میری ان سے مکہ میں ۱۰۴ھ میں ملاقات ہوئی۔ انہیں شرف صحابیت حاصل ہے، پھر انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں نے ارادہ کر لیا کہ صرف چار قبیلوں سے ہدیہ قبول کروں: قریشی، انصاری، ثقفی یا دوسی سے۔\"(1) اس کی سند میں محمد بن یونس کریمی ہے جو ضعیف ہے اور اس روایت میں وہ متفرد بھی ہے، شاید یہ بعد والے ہوں۔","",{"fn":"(1) ذکرہ الہیثمی فی مجمع الزوائد (الحدیث: ۱۴۸/۴) والطبرانی فی المعجم الکبیر (الحدیث: ۱۸/۱۱) والزبیدی فی اتحاف السادۃ المتقین (۲۹۷/۹)"}],[9448,"§۹۳۸۴ ۔ ابوابراہیم الحجبی(1)\nبنی شیبہ سے ان کا تعلق ہے، ابن مندہ نے ان کا ذکر کیا ہے اور سعید بن میسرہ کی سند سے ابراہیم بن ابی ابراہیم الحجبی سے نقل کیا اور انہوں نے اپنے والد سے نقل کیا فرمایا: \"اللہ تعالیٰ نے ابراہیم علیہ السلام کی طرف وحی بھیجی کہ میرے لیے گھر تعمیر کرو۔\"(2) ذہبی(3) فرماتے ہیں: ان کے صحابی ہونے کے بارے میں تردد ہے، بات وہی ہے جو ذہبی نے کہی، کیونکہ روایت میں اس کی وضاحت کے لیے کوئی چیز نہیں اور سعید ضعیف بھی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۵۸) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) ذکرہ ابن الاثیر فی اسد الغابہ (۳۶۷/۴)\n(3) التجرید (۱۴۶/۲)"}],[9449,"§۹۳۸۵ ۔ ابو ابیّ ابن امرأۃ عبادۃ بن الصامت(1)\nعبد اللہ بن عمرو بن قیس بن زید الانصاری ہیں۔ بعض عبد اللہ بن ابی اور بعض ابن کعب کہتے ہیں، عبادہ رضی اللہ عنہ کی بہن کے بیٹے ہیں بعض عبادہ کے بھانجے بتاتے ہیں۔ ابن حبان نے ذکر کیا ہے کہ ان کا نام شمعون ہے، ابو عمر نے ان لوگوں کے قول کو غلط قرار دیا ہے، جو کہتے ہیں کہ ان کا نام عبد اللہ بن ابی ہے، فرماتے ہیں: وہ تو عبد اللہ بن ابوابی ہیں۔ یحیی بن مندہ نے کہا ہے کہ فلسطین میں سب سے آخری جو صحابی فوت ہوئے یہ ہیں۔ عبادلہ میں ان کا تذکرہ گزر چکا ہے، ان کے والد کے نام میں اختلاف ہے، بغوی وغیرہ نے ابراہیم بن عبلہ کی سند سے ان کی حدیث نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۰) تجرید اسماء الصحابہ (۱۴۶/۲)"}],[9450,"§۹۳۸۶ ۔ ابو ابیّ\nذہبی نے بقی بن مخلد کی مسند سے ذکر کیا ہے کہ اس میں ان کی دو حدیثیں ہیں۔ اور یہ ان لوگوں میں ہیں جنہوں نے دونوں قبلوں کی جانب نماز پڑھی اور رسول اللہ صلی اللہ علیہ وسلم سے نقل کیا ہے، آپ نے فرمایا: \"سنا اور شہد کا استعمال کیا کرو ان میں سوائے موت کے ہر بیماری کی شفاء ہے۔\"(1)۔ میرے خیال میں یہ پہلے والے ہیں۔","",{"fn":"(1) اخرجہ ابن ماجہ فی کتاب الطب باب السنا والسنوت (الحدیث: ۳۴۵۷) الحاکم فی المستدرک (۲۰/۴) ابن ابی عاصم فی السلسلۃ الصحیحۃ (الحدیث: ۱۷۹۸) والنہدۃ فی کنز العمال (الحدیث: ۲۸۲۷۱ و ۲۸۲۶۷) الہیثمی فی مجمع الزوائد (الحدیث: ۸۳۰۹) الطبرانی فی المعجم الکبیر (الحدیث: ۳۹۸/۲۳) ذہبی فی الطب النبوی (۱۸/۱)"}],[9451,"§۹۳۸۷ ۔ ابواثیلہ(1)\nالف کے زبر، زیر پیش سے تصغیر ہے۔ وہ راشد اسلمی ہیں۔ اسماء میں گزر چکا ہے۔ ابوعمر نے نقل کیا ہے کہ وہ ابووائلہ ہیں بغیر تصغیر۔ ابن الاثیر(2) نے ابواثیلہ بن راشد لکھا ہے جو وہم ہے راشد تو ان کے بیٹے کا نام ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۱) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) اسد الغابہ (۳۶۸/۴)"}],[9452,"§۹۳۸۸ ۔ ابواثیلہ (دوسرے)\nابن الجوزی نے \"تنقیح\" میں ان کا ذکر کیا ہے اور ان کے متعلق کہا ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے غلام تھے۔"],[9453,"§۹۳۸۹ ۔ ابواحمد بن جحش الاسدی(1)\nام المومنین زینب رضی اللہ عنہا کے بھائی، ان کا نام \"عبد\" بغیر اضافت ہے۔ بعض نے عبد اللہ کہا ہے۔ ابن کثیر سے نقل کیا ہے، علماء نے کہا: یہ وہم ہے البتہ اس پر اتفاق ہے کہ وہ سابقین اولین سے ہیں، بعض کا قول ہے کہ انہوں نے حبشہ ہجرت کی، پھر مدینہ ہجرت کر کے آئے، بلاذری نے ان کی حبشہ کی جانب ہجرت کا انکار کیا ہے، اور کہا ہے کہ انہوں نے حبشہ ہجرت نہیں کی۔ وہ تو ان کے بھائی عبید اللہ تھے جو وہاں جا کے نصرانی ہو گئے تھے۔ ابن اسحاق(2) کا قول ہے کہ ابو سلمہ عامر بن ربیعہ اور عبداللہ بن جحش کے بعد مہاجرین میں سب سے پہلے وہ مدینہ آئے۔ اپنے گھرانے اور اپنے بھائی عبداللہ کو ساتھ لے آئے۔ ابواحمد نابینے تھے، مکہ میں اوپر نیچے بغیر قائد کے طواف کرتے تھے۔ ان کے عقد میں فارعہ بنت ابوسفیان بن حرب تھیں، بدر اور دوسری جنگوں میں شریک رہے۔ وہ مکہ میں بغیر قائد کے گھومتے تھے۔ اس کے متعلق وہ کہتے ہیں: \"مکہ کیا ہی اچھی وادی ہے جس میں میرا گھرانا۔۔۔۔۔۔ اس میں میری کیلیں جمی ہوئی ہیں، اس میں میں بغیر رہنما کے چلتا ہوں۔\" اور بلاذری نے ہر قسم کی ابتداء میں پہلے کے سوا ابی کے اضافہ سے یہ اشعار پڑھے ہیں: پھر چاروں مخزومہ ہو جائیں گے، مرزبانی نے معجم الشعراء میں ان کا ذکر کیا ہے، فرماتے ہیں، نبی صلی اللہ علیہ وسلم نے یہ اشعار پڑھے: \"ام احمد نے کوہ صفا اور مروہ پر اللہ کی قسم کھائی، اس کی قسم پوری ہوگئی، ہم وہی لوگ ہیں جو اس میں تھے پھر ہم مکہ میں ہی رہے۔ ہم دو اور ایک کے درمیان اللہ تعالیٰ کی طرف بڑھتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم کا دین اور اس کا دین برحق ہے۔\" ابن الاثیر(3) نے اس بات پر اعتماد کیا ہے کہ انہوں نے اپنی بہن زینب بنت جحش کے بعد وفات پائی۔ جبکہ اس میں نظر ہے۔ بعض کا کہنا ہے: یہ وہی ہیں جو فوت ہوئے تو ان کی بہن کو ان کی فوتگی کی خبر ملی تو انہوں نے خوشبو منگا کر ملی۔ صحیحین میں زینب بنت ام سلمہ کی سند سے منقول ہے، راوی کا بیان ہے: میں سیدہ زینب بنت جحش رضی اللہ عنہا کے پاس آیا، جب ان کے بھائی کا انتقال ہوا، تو انہوں نے خوشبو منگا کر ملی، پھر فرمانے لگیں: مجھے خوشبو کی چنداں ضرورت نہ تھی، چونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو عورت اللہ تعالیٰ اور یوم آخرت پر ایمان رکھتی ہو اس کے لیے حلال نہیں کہ وہ سوائے خاوند کے کسی میت کے لیے تین دن سے زائد سوگ کرے۔\"۔ (الحدیث)(4) جس کی تقویت اس سے ہوتی ہے کہ یہ ابو احمد ہی ہیں کیونکہ آپ کے دونوں بھائی عبداللہ اور عبید اللہ رسول اللہ صلی اللہ علیہ وسلم کی حیات میں ہی فوت ہو گئے تھے، ان میں عبداللہ جو بڑے ہیں وہ اُحد میں شہید ہوئے۔ اور چھوٹا بھائی عبید اللہ سرزمین حبشہ میں نصرانی ہو کر مر گیا۔ جس کی بیوی ام حبیبہ بنت ابی سفیان سے بعد میں رسول اللہ صلی اللہ علیہ وسلم نے شادی کر لی تھی۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۲) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) ذکرہ ابن ہشام فی السیرۃ النبویۃ عن ابن اسحاق (۸۶/۲)\n(3) اسد الغابہ (۳۶۸/۴)\n(4) اخرجہ البخاری فی کتاب الطلاق، باب تحد المتوفی عنہا زوجہا اربعۃ اشہر وعشرا (الحدیث: ۵۳۳۵) و اخرجہ مسلم فی کتاب الطلاق باب وجوب الاحداد فی عدۃ الوفاۃ (الحدیث: ۳۷۰۹)"}],[9454,"§۹۳۹۰ ۔ ابواحمد بن قیس بن لوذان(1)\nبن لوذان انصاری، سلیم کے بھائی، عدوی نے کہا: ان دونوں حضرات کو شرف صحبت حاصل ہے اور وہ ان دس میں سے ایک ہیں جنہیں سیدنا عمر رضی اللہ عنہ نے سیدنا عمار بن یاسر رضی اللہ عنہ کے ہمراہ کوفہ بھیجا تھا۔","",{"fn":"(1) تجرید اسماء الصحابہ (۱۴۶/۲)"}],[9455,"§۹۳۹۱ ۔ ابواحیحہ (دونوں حاؤں سے تصغیر ہے)\nقریشی ہیں، ان کا ذکر ابن اسحاق کی فتوح الشام میں یونس بن بکیر کی ان سے روایت میں آیا ہے، فرماتے ہیں: سیدنا خالد بن ولید رضی اللہ عنہ کی سماوہ سے دمشق کی جانب رافع طائی کی رہنمائی میں روانگی کے موقع پر ابواحیحہ نے کہا: \"خالد کی خوبیاں اللہ کے لیے ہیں جو ہدایت یافتہ آیا، جبکہ آنکھ اس سے خس و خاشاک سے ڈھک گئی۔ وہ آنکھ ایسے پیٹی ہوتی ہے گویا کہ مٹی سے بھری پڑی، وہ اپنے دل سے وہ کچھ دیکھتا ہے جو ہم نہیں دیکھتے، یاد کرنے والا دل اور میرا دل یاد کر چکا۔۔۔۔۔ (نظم کے آخری اشعار تک)۔\" ابن عساکر رحمہ اللہ یہ فرماتے ہیں: ان ابو احیحہ نے سیدنا خالد کے ساتھ فتح دمشق میں شرکت کی، اور یہ اشعار قعقاع بن عمرو تمیم سے بھی نقل کیے گئے ہیں۔ میں کہتا ہوں: یہ پہلے گزر چکا ہے کہ حجتہ الوداع کے موقع پر جو قریشی بھی حاضر تھا وہ مسلمان تھا لہذا یہ صحابی ہوئے۔"],[9456,"§۹۳۹۲ ۔ ابو احزم بن عتیک(1)\nابن نعمان ابن علیک الانصاری، سہل کے بھائی، ان کا نام حارث ہے۔ اسماء میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۰) الاستيعاب (ت: ۲۸۷۲)"}],[9457,"§۹۳۹۳ ۔ ابواخرم\nابن فتحون نے اس کا استدراک کیا ہے، فرمایا: طبری نے ان کا شعبہ کی سند سے ابومہاجر وہ کوفہ کے ایک شخص سے جسے اخرم کہا جاتا ہے کے حوالے سے نقل کرتے ہیں وہ اپنے والد سے روایت کرتے ہیں فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے مال واہل میں تبقر سے منع فرمایا۔ کسی نے ان سے پوچھا: تبقر کیا ہے؟ فرمایا: کثرت۔ میں کہتا ہوں: ان کے نسب میں اختلاف ہے، جس کا کچھ تذکرہ میں نے سعد بن الاخرم میں کر دیا ہے۔"],[9458,"§۹۳۹۴ ۔ ابوالاخنس بن حذافہ(1)\nبن قیس ابن عدی بن سعد بن سہم قرشی سہمی، عبداللہ اور خنیس کے والد، ابوعمر نے کہا: ان کا نام معلوم نہیں ہو سکا، ان کی صحابیت کے بارے میں نظر ہے۔ زبیر بن بکار نے کہا: حذافہ کی نسل میں اولاد ابوالاخنس کی ہے۔ ان میں سے صرف عبد اللہ بن محمد بن ذویب بن عمامہ بن ابی الاخنس بن حذافہ بچے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۴) تجرید اسماء الصحابہ (۱۴۶/۲)"}],[9459,"§۹۳۹۵ ۔ ابواذینہ (یا نون سے تصغیر ہے)(1)\nبغوی نے کہا: وہ اہل مصر سے تعلق رکھتے ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایک حدیث روایت کی، ان کے متعلق مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہے یا نہیں؟ ابن السکن نے کہا: ابواذینہ صدفی کو صحبت رسول حاصل ہے اور ان کی حدیث اہل مصر میں شمار ہوتی ہے۔ انہوں نے محمد بن بکار بن بلال کی سند سے موسیٰ بن علی بن رباح کے حوالہ سے نقل کیا وہ اپنے والد سے وہ ابو اذینہ صدفی سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری عورتوں میں سے بہترین عورت وہ ہے جو زیادہ محبت کرے، زیادہ بچے جنے، جس کے پاس آیا جائے، تسلی دینے والی (ان محاسن کے ساتھ) جب اللہ تعالیٰ سے ڈرتی ہو، اور تمہاری بری عورتیں وہ ہیں جو مردوں کی مشابہت اختیار کریں، منافق عورتوں سے تعلق رکھتی ہوں، بے حیا ہوں۔ ان میں سے جنت میں صرف اتنی جائیں گی جیسے سفید ٹانگوں والا کوا۔\"(2) ابو عمر نے نقل کیا ہے کہ انہیں العبدی بھی کہا جاتا ہے جو غلط ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۶) تجرید اسماء الصحابہ (۱۴۶/۲)\n(2) الہندی کنز العمال (الحدیث: ۴۴۵۶۹) زبیدی، اتحاف السادۃ المتقین (۲۹۷/۵) العراقی، مغنی المحتاج فی حمل الاسفار (۲۷/۲) ابن کثیر \"جامع المسانید والسنن\" (۱۱/۱۳) ابن الأثیر فی اسد الغابہ (۳۶۹/۴)"}],[9460,"§۹۳۹۶ ۔ ابوارطاۃ الاحمسی(1)\nجریر کے قاصد، ان کا نام حصین بن ربیعہ ہے، اسماء میں ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۴) الاستيعاب (ت: ۲۸۷۶)"}],[9461,"§۹۳۹۷ ۔ ابوالارقم القرشی(1)\nارقم کے والد ہیں، ابن ابوخیثمہ اور طبری نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔ ابو علی الجیانی فرماتے ہیں: امام مسلم نے کتاب \"الاخوۃ والاخوات\" میں ان کا ذکر کیا ہے جہاں باب ہے، جنہوں نے نبی صلی اللہ علیہ وسلم سے سنا، انہیں اور ان کے والد کو شرف صحابیت حاصل ہے۔ ابوالارقم اور الارقم بن ابی الارقم۔ یہ ارقم، ان ارقم مخزومی کے علاوہ ہیں جن کا اسماء میں ذکر ہوا، اور وہ ارقم وہ والے ہیں جن کا ذکر سیرت میں رسول اللہ صلی اللہ علیہ وسلم کے دار ارقم میں داخل ہونے سے پہلے آئے گا۔ ان کے والد کا نام عبد مناف ہے اور یقینی بات ہے کہ انہیں شرف صحبت حاصل نہیں۔ جیسا کہ ابن عبدالبر نے دوسی کے (ترجمہ) حالات میں کہا ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۱۴۷/۲)"}],[9462,"§۹۳۹۸ ۔ ابواروی الدوسی(1)\nان کا نام اور نسب معروف نہیں۔ ابن السکن نے کہا ہے: انہیں شرف صحابیت حاصل ہے۔ وہ ذوالحلیفہ میں پڑاؤ کرتے تھے، ابن السکن اور حاکم نے عاصم بن عمر العمری کی سند سے سہیل بن ابی صالح کے حوالہ سے، محمد بن ابراہیم تیمی سے وہ ابوسلمہ بن عبدالرحمن سے وہ ابواروی دوسی سے نقل کرتے ہیں، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس بیٹھا تھا کہ اچانک حضرات ابوبکر و عمر رضی اللہ عنہما آ گئے۔ تو آپ نے فرمایا: اللہ تعالیٰ کے لیے تمام تعریفیں ہیں جس نے تم دونوں کے ذریعہ میری تائید کی۔(2) اس کی سند ضعیف ہے۔ ان کی ایک اور حدیث ہے جسے امام احمد اور بغوی رحمہ اللہ نے ابو واقد لیثی کی سند سے۔ ان کا نام صالح بن محمد بن زائدہ ہے۔ ابواروی الدوسی سے نقل کیا ہے، فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عصر کی نماز پڑھ رہا تھا پھر آپ غروب آفتاب سے پہلے چٹان کے پاس آئے۔(3) اور ابن مندہ اور ابونعیم نے ان الفاظ سے نقل کی ہے: \"ابھی تک سورج ڈوبا نہ تھا کہ آپ مقام ذوالحلیفہ پیدل آئے۔\" ابن ابی خیثمہ نے اسی سند سے نقل کی ہے جو ان کے ہاں ابو واقد کی سند سے ہے، فرمایا: \"مجھ سے ابواروی نے بیان کیا۔ فرماتے ہیں: میں نے ان کے متعلق یحیی بن معین سے پوچھا، تو انہوں نے اپنے قلم سے ابو واقد کے متعلق لکھا وہ ضعیف ہے۔ اور واقدی نے ذکر کیا ہے کہ ابواروی غزوہ قرقرہ الکدر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شریک تھے۔ ابن السکن اور ابو عمر کا کہنا ہے: ان کا انتقال امیر معاویہ رضی اللہ عنہ کی خلافت کے آخر میں ہوا، وہ عثمانی تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۸) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) الحاکم فی المستدرک (۷۴/۳) الہیثمی، مجمع الزوائد (۵۰/۹) الطبرانی، المعجم الکبیر (۹۲۶/۲۲) الہندی، کنز العمال (۳۲۶۸۱) ابن الاثیر اسد الغابہ (۳۷۰/۴)\n(3) اخرجہ الامام احمد فی مسندہ (الحدیث: ۹۲۶/۲۲) والطبرانی فی المعجم الکبیر (۹۲۵/۲۲) الہیثمی فی مجمع الزوائد (۳۰۷/۱)"}],[9463,"§۹۳۹۹ ۔ ابوالازور ضرار بن الخطاب(1)\nپہلے ذکر ہو چکا۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۷)"}],[9464,"§۹۵۰۰ ۔ ابوالازور ضرار بن الازور(1)\nپہلے ذکر ہو چکا۔","",{"fn":"(1) الاستيعاب (ت: ۲۸۷۹)"}],[9465,"§۹۵۰۱ ۔ ابوالازور الاحمری(1)\nابن مندہ نے ان کا ذکر کیا اور ابراہیم بن اسمعیل بن ابی حبیبہ کی سند سے عمر بن ابی سفیان کے حوالہ سے نقل کیا وہ اپنے والد سے وہ ابوالازور الاحمری سے روایت کرتے ہیں، فرماتے ہیں: وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"رمضان کا عمرہ حج کے برابر ثواب رکھتا ہے۔\"(2)","",{"fn":"(1) اسد الغابہ (ت: ۵۶۶۹) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) بخاری کتاب العمرۃ باب عمرۃ فی رمضان الحدیث (۱۷۸۲) مسلم کتاب الحج باب فضل العمرۃ فی رمضان (الحدیث: ۳۰۲۸) نسائی کتاب الصیام باب الرخصۃ فی ان یقال لشہر رمضان (الحدیث: ۲۱۰۹) ترمذی کتاب الحج باب ما جاء فی عمرۃ رمضان (الحدیث: ۹۴۰) ابن ماجہ کتاب المناسک باب العمرۃ فی رمضان (الحدیث: ۲۹۹۳) الامام احمد فی مسندہ (الحدیث: ۶/۴۶) ابن الأثیر فی اسد الغابہ (۳۷۰/۴)"}],[9466,"§۹۵۰۲ ۔ ابوالازور (دوسرے)\nابو عمر نے انہیں پہلے والے سے ملا دیا ہے صحیح یہ ہے کہ دونوں میں فرق ہے۔ عبدالرزاق نے اپنی مصنف میں لکھا ہے، ابن جریج سے روایت ہے، فرمایا: جب ابو عبیدہ شام کے گورنر تھے اس وقت کی بات ہے مجھے بتایا گیا کہ انہوں نے ابوجندل بن سہیل، ضرار بن الخطاب اور ابوالازور کو شراب نوشی میں مصروف پایا، تو ابو جندل بولے: \"وہ لوگ جو ایمان لائے اور اعمال صالحہ کیے، جب وہ ایمان تقویٰ اور اعمال صالحہ کے ساتھ کچھ کھا لیں تو ان پر کوئی حرج نہیں۔\"(1) تو ابو عبیدہ رضی اللہ عنہ نے واقعہ کی اطلاع کے لیے سیدنا عمر رضی اللہ عنہ کو خط لکھا کہ ابو جندل نے ان آیات کے ذریعہ سے مجھ سے جھگڑا کیا ہے تو سیدنا عمر رضی اللہ عنہ نے انہیں جواباً لکھا: جس نے ابو جہل کو غلطی اچھی کر دکھائی اس (شیطان) نے ابو جندل کے لیے جھگڑے کو مزین کر دیا۔ انہیں حد لگاؤ! اس پر ابوالازور نے کہا: اگر تم نے ہمیں حد لگانی ہی ہے تو ہمیں کل دشمن سے مڈبھیڑ کر لینے دو اگر ہم مارے گئے تو بہتر ورنہ تمہاری طرف لوٹ آئے تو ہمیں حد لگا لینا۔ دشمن سے مقابلہ ہوا۔ ابوالازور تو شہید ہو گئے اور باقی دو صاحبان کو حد لگی۔ دونوں میں فرق کی دلیل یہ ہے کہ الاحمری کا دور اتنا مؤخر ہوا کہ ان سے ابوسفیان ثقفی نے روایت کی ہے اور ابوسفیان نے خلافت عمر کا دور نہیں پایا۔","",{"fn":"(1) سورۃ المائدۃ (۹۳)"}],[9467,"§۹۵۰۳ ۔ ابوالازھر الانماری(1)\nانہیں ابوزھیر بھی کہا جاتا ہے، ابوداؤد نے سنن میں اچھی شامی سند سے نقل کیا کہ مجھ سے ابوالازھر انماری اور وائلہ بن الاسقع رسول اللہ صلی اللہ علیہ وسلم کے صحابیوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے علم طلب کیا پھر اسے پالیا تو اس کے لیے اجر کے دو پیمانے ہیں۔\"۔ (الحدیث)(2) اور ابوداؤد نے یحیی بن حمزہ کی سند سے ثور بن یزید کے حوالہ سے خالد سے نقل کیا ہے جب وہ سونے لگتے تو فرماتے: \"اللہ کے نام سے میں نے اپنا پہلو رکھا۔\"۔ (الحدیث)(3) اس کے بعد کہا: ابو ہمام الاہوازی نے اسے ثور سے روایت کیا تو کہا: ابوزھیر نے کہا۔ میں کہتا ہوں: کہ ابو ہمام کی بات کی متابعت صدقہ بن عبد اللہ نے کی ہے۔ ابن ابی حاتم نے کہا: میں نے ابوزرعہ سے سنا، ان کے سامنے ابوزھیر انماری کا ذکر ہوا، فرمایا: ان کا کوئی نام نہیں لیا جاتا، وہ صحابی نہیں، انہوں نے تین احادیث روایت کی ہیں۔ میں نے اپنے والد سے کہا کہ ایک شخص نے ان کا نام یحیی بن نفیر بتایا ہے، تو انہوں نے ناواقفیت ظاہر کی۔ میں کہتا ہوں: آمین کے بارے میں ان کی حدیث ہے جسے ان سے ابواصبح قرشی روایت کرتے ہیں۔ کثیر بن مرہ اور شریح بن عبید نے بھی ان سے روایت نقل کی ہے۔ بغوی نے کہا: ابوالازھر انماری کا نسب بیان نہیں کیا جاتا، مجھے معلوم نہیں وہ صحابی ہیں یا نہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۱) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) الہیثمی فی مجمع الزوائد (الحدیث: ۱/۱۲۳) الطبرانی فی المعجم الکبیر (الحدیث: ۱۶۵/۲۲) ابن الأثیر فی اسد الغابہ (۳۷۱/۴) الہندی فی کنز العمال (۲۸۸۳۸) المنذری فی الترغیب والترہیب (۹۶/۱)\n(3) اخرجہ ابوداؤد فی کتاب الادب باب ما یقال عند النوم (الحدیث: ۵۰۵۴) و اخرجہ الطبرانی فی المعجم الکبیر (الحدیث: ۷۵۸/۲۲) ابن کثیر فی جامع المسانید والسنن (۱۵/۱۳) الہندی فی کنز العمال (الحدیث: ۱۸۲۳۶) والزبیدی فی اتحاف السادۃ المتقین (۱۸۲۳۶)"}],[9468,"§۹۵۰۴ ۔ ابواسحاق\nسعد بن ابی وقاص پہلے ذکر گزر چکا۔"],[9469,"§۹۵۰۵ ۔ ابواسرائیل الانصاری(1)\nیا قریشی عامری ہیں۔ بغوی وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے۔ ابو عمر نے کہا: ان کا نام یسیر (یا، سین سے تصغیر ہے)۔ ابن اسکن اور باوردی نے حرف قاف قشیر میں اس نام کو نقل کیا ہے۔ امام احمد(2) رحمہ اللہ نے فرمایا: عبدالرزاق نے ابن جریج، ابن طاؤس نے نقل کیا وہ اپنے والد سے وہ ابو اسرائیل سے روایت کرتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف لائے تو ابو اسرائیل نماز پڑھ رہے تھے، کسی نے آپ سے عرض کیا: وہ یہ ہیں، یا رسول اللہ! (کھڑے ہیں) بیٹھتے نہیں، نہ لوگوں سے بات کرتے ہیں۔ نہ سائے میں بیٹھتے ہیں۔ انہوں نے اس طرح کا روزہ رکھا ہے، آپ نے فرمایا: وہ بیٹھ جائیں، لوگوں سے بات کریں، سائے میں آجائیں، لوگوں سے بات کریں، سائے میں آجائیں اور روزہ رکھ لیں۔ اسے بغوی اور ابونعیم نے لیث بن ابی سلیم کی سند سے طاؤس کے حوالہ سے ابو اسرائیل سے روایت کیا ہے، فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں دھوپ میں کھڑے دیکھ کر فرمایا: انہیں کیا ہوا؟ لوگوں نے عرض کیا: نذر مانی ہے پھر اسی طرح کا مفہوم ذکر کیا۔ اس کی اصل صحیحین میں ہے جو ابن عباس رضی اللہ عنہما کی حدیث سے ثابت ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دھوپ میں کھڑے دیکھا۔۔۔۔۔ (الحدیث) اسے بھی بغوی نے محمد بن کریب سے، انہوں نے ابن عباس رضی اللہ عنہما سے نقل کیا ہے: ابو اسرائیل قشیر نے کھڑے ہونے کی نذر مانی۔۔۔، پھر حدیث ذکر کی۔ اور بخاری رحمہ اللہ میں عکرمہ کی ابن عباس رضی اللہ عنہما کی سند سے مروی روایت ہے کہ وہ ابو اسرائیل تھا۔ اکثر روایات میں ان کا نام نہیں لیا گیا۔ اسی طرح امام مالک نے حمید بن قیس اور ثور سے بغیر نام کے مرسل روایت کیا ہے۔ اور خطیب نے مہمات میں جریر بن حازم سے، ایوب، مجاہد سے وہ ابن عباس رضی اللہ عنہما کی سند سے روایت کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جمعہ کے روز لوگوں سے خطاب فرماتے، تو آپ کی نظر بنی عامر بن لوئی کی شاخ قریش کے ایک شخص پر پڑی جسے ابواسرائیل کہا جاتا تھا۔۔۔۔ پھر اس روایت کو ذکر کیا۔ عبد الغنی نے مہمات میں کہا ہے کہ صحابہ رضی اللہ عنہم میں ان کے علاوہ کسی کی کنیت ابو اسرائیل نہیں ہے۔ اور اسماء میں گزر چکا ہے کہ ان کا نام قشیر ہے (شین سے تصغیر ہے) اسے ابن السکن نے روایت کیا اور ابوعمر نے اسے لفظی غلطی قرار دے کر کہا: قیسر (سین مفتوح سے پہلے یاء ساکن)۔ زبیر بن بکار نے نسب قریش میں ذکر کیا کہ بزدہ بنت عامر بن الحارث بن السباق بن عبدالدار، مہاجر خواتین سے تھیں۔ جن سے ابو اسرائیل فہری نے نکاح کر لیا تو ان کے ہاں جنگ جمل سے پہلے اسرائیل کی ولادت ہوئی۔ شاید وہ ابو اسرائیل یہی ہوں۔ عبد الغنی کے قول: \"صحابہ رضی اللہ عنہم میں ان کے علاوہ کسی کی کنیت ابو اسرائیل نہیں\" سے اس بات کی تائید ہوتی ہے کہ ابو اسرائیل ان کے علاوہ ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۳) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) مسند احمد (۱۶۸/۴)"}],[9470,"§۹۵۰۶ ۔ ابواسماء السکونی\nغضیف بن الحارث، ناموں میں ذکر ہو گیا ہے۔"],[9471,"§۹۵۰۷ ۔ ابواسماء الشامی(1)\nابواحمد حاکم نے احمد بن یوسف بن ابی اسماء کی سند سے نقل کیا ہے، فرماتے ہیں: میں نے اپنے دادا ابواسماء بن علی بن ابی اسماء سے بحوالہ ان کے والد ان کے دادا ابو اسماء سے سنا، فرمایا: میں نبی کریم صلی اللہ علیہ وسلم کے پاس گیا، آپ سے بیعت کی، آپ نے مجھ سے مصافحہ کیا۔ اس کے بعد سے میں نے قسم کھالی کہ میں کسی سے مصافحہ نہیں کروں گا۔ چنانچہ وہ کسی سے مصافحہ نہیں کرتے تھے۔(2) ان میں اور غضیف میں فرق کیا گیا ہے۔ اسے ابن مندہ نے مذکورہ بالا احمد بن یوسف کی سند سے روایت کیا ہے اور ان کی سند میں غیر معروف راوی ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۷۴) تجرید اسماء الصحابہ (۱۴۷/۲)\n(2) مسند احمد (۷۹/۵) المعجم الکبیر (۹۵۰/۲۲) مجمع الزوائد (۱۷۹/۴)"}],[9472,"§۹۵۰۸ ۔ ابو اسماء المزنی\nمزینہ کے جو لوگ \"خزاعی بن عبد نعم\" کے ہاتھ پر اسلام لائے ان میں سے ایک ہیں۔ وہ فتح مکہ میں شریک تھے یہ بات پہلے \"خزاعی بن عمرو\" کے سوانح میں گزر چکی ہے جسے \"تجرید\" میں اصل کی پیروی کرتے ہوئے نظر انداز کر دیا۔"],[9473,"§۹۵۰۹ ۔ ابواسماء بن عمرو الجذامی(1)\nواقدی نے ان کا جذام کے ان لوگوں کے وفد میں ذکر کیا ہے جو نبی صلی اللہ علیہ وسلم کے پاس یہ بتانے آئے تھے کہ ان کے مسلمان ہو چکنے کے بعد بھی زید بن حارثہ نے ان سے تعرض کیا ہے، چنانچہ آپ نے ان کے قیدی رہا کر دیئے۔ اور ان کا لیا مال واپس کر دیا۔","",{"fn":"(1) اسد الغابہ (۵۶۸۱)"}],[9474,"§۹۵۱۰ ۔ ابوالاسود الجذامی\nیہ دوسرے ہیں، عبداللہ بن سندر، پہلے ذکر ہو چکا ہے۔"],[9475,"§۹۵۱۱ ۔ ابوالاسود\nعبدالرحمن بن یعمر، ان کا تذکرہ بھی پہلے ہو گیا ہے۔"],[9476,"§۹۵۱۲ ۔ ابوالاسود بن یزید(1)\nبن معدی کرب بن سلمہ بن مالک بن حارث بن معاویہ اکرمین کندی ابن کلبی نے بحوالہ طبری ذکر کیا ہے: وہ معزز انسان تھے، نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر اسلام لائے۔ ابوعلی جیانی نے استیعاب پر اپنے اضافہ میں ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۷۷) تجرید (۱۴۷/۲)"}],[9477,"§۹۵۱۳ ۔ ابوالاسود السلمی\nآخری قسم میں تذکرہ آئے گا۔"],[9478,"§۹۵۱۵ ۔ ابوالاسود القرشی\nمالکی بھی کہا جاتا ہے \"جرح و تعدیل\" میں ابن ابی حاتم نے عبد اللہ بن اسود قرشی کے سوانح میں ذکر کیا ہے کہ وہ اپنے والد کے واسطہ سے اپنے دادا سے روایت کرتے ہیں۔ وہ نبی صلی اللہ علیہ وسلم سے کہ آپ نے فرمایا: جس حکمران نے ہمیشہ تجارت کی اس نے انصاف نہیں کیا۔ ابن وہب نے خالد بن عمیر سے بحوالہ ان سے نقل کیا ہے۔ ابن فتحون نے استیعاب پر اضافہ کرتے ہوئے استدراک کیا ہے۔ ابواحمد حاکم نے بقیہ کی سند سے بحوالہ خالد بن حمید روایت کیا ہے کہ ابن الاسود مالکی نے بواسطہ اپنے والد اپنے دادا سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس حکمران نے رعیت میں تجارت کی اس نے انصاف نہیں کیا۔\"(1)","",{"fn":"(1) کنز العمال (۱۴۶۷۶) المطالب العالیۃ (۲۱۰۷)"}],[9479,"§۹۵۱۶ ۔ ابوالاسود النهدی(1)\nباوردی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور یونس بن بکیر بحوالہ عنبسہ بن ازہر، ابوالاسود نہدی سے نقل کیا ہے انہوں نے نبی صلی اللہ علیہ وسلم کا دور پایا ہے۔ فرمایا: آپ غار کی جانب متوجہ تھے اور آپ کی انگشت پا زخمی ہوگئی۔ آپ نے فرمایا: تو ایک انگلی ہی تو ہے جو خون آلود ہوگئی، تجھے یہ تکلیف اللہ کی راہ میں پہنچی ہے۔(2) میں کہتا ہوں: اس کی سند میں تامل ہے۔ بعض کا قول ہے: ان کا نام عبد اللہ ہے۔","",{"fn":"(1) الاستيعاب (۲۸۸۳)\n(2) بخاری کتاب الجہاد والسیر باب من ینکب او یطعن فی سبیل اللہ (۲۸۰۲) مسلم کتاب الجہاد والسیر باب ما نہی النبی صلی اللہ علیہ وسلم اذی المشرکین والمنافقین (۱۷۹۶) مسند احمد (۱۸۸۳۰)"}],[9480,"§۹۵۱۷ ۔ ابواسید بن ثابت انصاری(1)\nالزرقی المدنی، زیتون کی فضیلت میں ان کی حدیث دارمی، ترمذی، نسائی اور حاکم نے عبداللہ بن عیسی کی سند سے بحوالہ ایک عطا نامی شامی شخص روایت کی ہے۔ نسائی کی روایت میں ہے۔ مجھے عطاء (ایک شخص جو ساحل پر رہتا تھا) نے بیان کیا اور ابواسید بن ثابت سے یہ روایت نقل کی۔ ابو حاتم رحمہ اللہ فرماتے ہیں: احتمال ہے کہ وہ شخص عبداللہ بن ثابت ہوں، جو نبی صلی اللہ علیہ وسلم کی خدمت کرتے تھے اور شعبی ان سے روایت لیتے ہیں کہ سیدنا عمر رضی اللہ عنہ ایک تحریر لائے\"۔ دارقطنی نے یہ نام شروع کے زبر سے قلمبند کیا ہے۔ پیش بھی نقل کیا ہے لیکن اسے کمزور قرار دیا ہے۔ اس میں اس پر بھی رد ہے، جس نے انہیں ساعدی کے ساتھ ملا دیا۔ چنانچہ ان کی مذکورہ حدیث امام احمد وغیرہ نے ابواسید ساعدی کی سند میں داخل کر دی ہے اور ابو عمر کے ہاں: ابواسید ثابت انصاری لکھا ہے، ان کی حدیث ہے: \"زیتون کھایا کرو۔\"(2) یوں ان کا نام ساقط کر دیا۔ میں نے دمیاطی کے قلم سے لکھا ہوا پڑھا ہے: ابن ابی حاتم نے فرمایا: عطاء شامی نے ابواسید عبداللہ بن ثابت سے روایت لی ہے۔ ابو عمر نے ان کا نام ثابت بتایا ہے اور ابن فتحون نے اس پر کوئی تنبیہ نہیں کی۔","",{"fn":"(1) اسد الغابہ (۵۶۷۸)\n(2) ترمذی کتاب الاطعمۃ باب ما جاء فی اکل الزیت (۱۸۵۲) مسند احمد (۴۹۷/۳) ابن ماجہ کتاب الاطعمۃ باب الزیت (۳۳۱۹) المعجم الکبیر (۵۹۶/۱۹، ۵۹۷)"}],[9481,"§۹۵۱۸ ۔ ابواسید بن ثابت انصاری (دوسرے)(1)\nان کا نام عبداللہ ہے جو ناموں میں گزر چکا ہے، ان کی حدیث کی سند میں جابر بھی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۵)"}],[9482,"§۹۵۱۹ ۔ ابواسید بن جعونہ\nیہ وفد میں آئے، ابن بشکوال نے ان کا ذکر کیا ہے۔ ایسا ہی تجرید میں لکھا ہے لیکن مجھے ابن بشکوال کے حاشیے میں نظر نہیں آیا۔ الاستیعاب میں ابوزہیر بن اسید بن جمعونہ لکھا ہے: پس اسے لکھ لیا جائے۔"],[9483,"§۹۵۲۰ ۔ ابواسید بن علی(1)\nبن مالک انصاری ابوالعباس السراج نے ان کا صحابہ رضی اللہ عنہم میں ذکر کیا اور ابن مندہ نے اسے نقل کیا ہے۔ اور بسطام کی سند سے بحوالہ حسن بصری ابواسید بن علی سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تجھے عمارتیں سلع پہاڑ تک پہنچی ہوئی دکھائی دیں تو شام کے جہاد میں نکل جانا ورنہ امیر کی بات سننا اور اس کا کہنا ماننا۔(2) وہ حدیث جو سراج نے ذکر کی ہے اسے ان سے ابواحمد نے کنیتوں میں نقل کیا ہے، جس کی سند زہیر بن عباد بحوالہ سعید، قتادہ سے مروی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے ابواسید بن علی کو بنی عامر بن صعصعہ کی ایک خاتون کی اپنے لئے منگنی کرنے بھیجا، آپ نے اسے دیکھا نہیں تھا، پھر نبی صلی اللہ علیہ وسلم کے دیکھے بغیر ابواسید نے اس کا آپ سے نکاح کرا دیا۔ تمہید میں ابو عمر نے اس کا تعاقب کرتے ہوئے لکھا ہے: اس میں حاکم کو وہم ہو گیا ہے یہ قصہ تو ابواسید ساعدی کا ہے۔ جبکہ اس میں تامل ہے اس لیے کہ دونوں قصے مختلف ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۷۹) تجرید (۱۴۸/۲)\n(2) جامع المسانید (۲۱/۱۳) اسد الغابہ (۳۷۲/۴)"}],[9484,"§۹۵۲۱ ۔ ابواسید الساعدی(1)\nنام مالک بن ربیعہ تھا، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۱۴۸)"}],[9485,"§۹۵۲۲ ۔ ابواسیرہ بن حارث(1)\nبن علقمہ، واقدی(2) نے شہدائے اُحد میں ان کا ذکر کیا ہے، جس کی سند حارث بن عبداللہ بن کعب بن مالک تک پہنچاتے ہیں۔ وہ فرماتے ہیں: مجھ سے اس شخص نے بیان کیا جس نے ابوالسیرۃ بن حارث بن علقمہ کو دیکھا وہ بنی ابی عزیز کے ایک شخص کے سامنے ہوئے دونوں کی تلواریں ٹکرائیں وہ ایک دوسرے کو مارنے کے لیے تیار تھے، مجھے وہ یوں نظر آئے یوں لگ رہا تھا کہ دو خونخوار درندے ہیں۔ پھر دونوں نے ایک دوسرے کو دبوچا، ابوالسیرۃ نے اسے اوپر اٹھایا اور ایسے ذبح کر دیا جیسے بکری ذبح کی جاتی ہے۔ اتنے میں خالد بن ولید رضی اللہ عنہ نے (جو ابھی مسلمان نہیں ہوئے تھے) ابوالسیرۃ کو پیچھے سے نیزہ مارا تو وہ گر کر شہید ہو گئے۔ ابن ماکولا(3) کہتے ہیں کہ واقدی نے ان کی یہی کنیت بیان کی ہے جبکہ دوسروں نے ابو ہبیرہ لکھی ہے۔ میں کہتا ہوں: جس کا ذکر نہیں وہ ابن اسحاق ہیں۔ ابو عمر کہتے ہیں: واقدی نے اُحد میں شہید ہونے والوں میں ان کا تذکرہ کیا ہے۔ اور ان کے متعلق کہا ہے کہ وہی ابو ہبیرہ ہیں اور کبھی انہیں ابوالسیرۃ کہا۔ فرماتے ہیں: بعض کا قول ہے کہ ابوالسیرۃ کہنا واقدی کی غلطی ہے، وہ تو ابو ہبیرہ ہیں۔ موسیٰ بن عقبہ کے ہاں ابوالسیرۃ لکھا ہے اور ابن القداح نے ان کی موافقت کی کہ وہ ابن الحارث بن علقمہ ہیں، خالد بن الیاس کہتے ہیں: ابو ہبیرہ کا نام حارث بن علقمہ ہے۔ ابن عائذ نے ان کی کنیت ابوسیرۃ لکھی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۵۶۸۱) الاستيعاب (۲۸۸۶) تجرید (۱۴۸/۲)\n(2) المغازی (۲۵۳، ۲۵۴)\n(3) الاکمال (۳۹/۱)"}],[9486,"§۹۵۲۳ ۔ ابوالاشعث(1)\nابن الاثیر(2) نے بحوالہ ابن الدباغ ان کا تذکرہ کیا ہے، ایسا ہی ابن فتحون نے ان کا استدراک کیا ہے جسے بزار کی طرف منسوب کیا ہے۔ \"تجرید\" میں ذہبی(3) نے بزار سے یونہی ذکر کیا ہے۔ مسند بزار میں کنیت کے لفظ سے مرقوم نہیں، اس میں سلیمان بن عبد اللہ کی سند سے بحوالہ محمد بن اشعث بن قیس، ان کے والد، ان کے دادا سے روایت ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تیل محتاجی کو ختم کرتا، کپڑا بے نیازی کو ظاہر کرتا اور خادم سے نیکی و احسان دشمن کو ہلاک کرتا ہے۔\"(4) اس کی سند میں غیر معروف راوی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۸۲) تجرید (۱۴۸/۲)\n(2) اسد الغابہ (۳۷۳/۴)\n(3) التجرید (۱۴۸/۲)\n(4) کنز العمال (۱۷۲۱۱) مجمع الزوائد (۱۳۲/۵) جامع المسانید (۳۷/۱۳) اسد الغابہ (۳۷۳/۴) کشف الاسرار (۳۹۶۵)"}],[9487,"§۹۵۲۴ ۔ ابوالاعور\nسعید بن زید بن عمرو بن نفیل العددی، یکے از عشرہ مبشرہ، پہلے تذکرہ ہو چکا ہے۔"],[9488,"§۹۵۲۵ ۔ ابوالاعور بن ظالم(1)\nبن عبس بن حرام بن جندب بن عامر بن تمیم بن عدی بن النجار انصاری خزرجی۔ بدر و اُحد میں شریک رہے۔ ابن اسحاق(2) نے ان کا نام کعب بن حارث بتایا ہے جبکہ عدوی نے کہا: ان کا نام حارث بن ظالم ہے اور موسیٰ بن عقبہ کہتے ہیں: ابوالاعور بن حارث۔","",{"fn":"(1) اسد الغابہ (۵۶۸۳) تجرید (۱۴۸/۲)\n(2) السیرۃ النبویۃ (۲۶۳/۲)"}],[9489,"§۹۵۲۶ ۔ ابوالاعور السلمی\nعمرو بن سفیان، پہلے ذکر ہو چکا۔ ابو حاتم نے کہا: یہ صحابی نہیں ہیں۔"],[9490,"§۹۵۲۷ ۔ ابوالاعور الجرمی(1)\nابن ابی عیشہ نے ان کا ذکر کیا ہے اور سعید بن منان کی سند سے بحوالہ ابو زاہر، جبير سے روایت نقل کی ہے کہ قبیلہ جرم کا ایک شخص جسے ابوالاعور کہا جاتا تھا وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر کہنے لگا: السلام علیک یا رسول اللہ! آپ صلی اللہ علیہ وسلم نے فرمایا: وعلیک السلام ورحمۃ اللہ، ابوالاعور کیسے ہو؟(2) ابن مندہ نے اسی سند سے نقل کی ہے اور بغوی نے ابو عیشہ سے روایت کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۴) تجرید (۱۴۸/۲) الاستيعاب (۲۸۸۸)\n(2) جامع المسانید (۳۹/۱۳) اسد الغابہ (۳۷۴/۴)"}],[9491,"§۹۵۲۸ ۔ ابوامامہ اسعد بن زرارہ انصاری(1)\nخزرجی، نقیبوں میں سے ایک ہیں پہلے تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۷) الاستيعاب (۲۸۹۲) تجرید (۱۴۹/۲)"}],[9492,"§۹۵۲۹ ۔ ابوامامہ بن ثعلبہ الانصاری(1)\nثم الحارثی، اکثر کے ہاں ان کا نام \"ایاس\" ہے، بعض نے عبد اللہ بھی کہا ہے۔ اسی پر احمد بن حنبل رحمہ اللہ نے اعتماد کیا ہے۔ بعض نے ثعلبہ بن سہیل، تو بعض نے ابن عبد الرحمن بتایا ہے ابو عمر کہتے ہیں: ان کا نام ایاس تھا۔ کسی نے ثعلبہ، تو کسی نے سہیل کہا۔ جبکہ ایاس کے سوا کوئی نام صحیح نہیں۔ یہ ابو بردہ بن نیار کے بھانجے لگتے ہیں۔ نبی صلی اللہ علیہ وسلم سے کئی احادیث روایت کی ہیں جن میں سے چند امام مسلم اور اصحاب السنن نے درج کی ہیں۔ ان سے ان کے بیٹے عبد اللہ، عبد اللہ بن عطیہ بن عبد اللہ بن انیس انھیں بھی روایت کرتے ہیں۔ ابواحمد حاکم نے کہا: وہ نبی صلی اللہ علیہ وسلم کے ساتھ جہاد کے لیے نکلے تو آپ نے انہیں ان کی والدہ کی بیماری کی وجہ سے واپس کر دیا۔ جب واپس آئے تو وہ وفات پا چکی تھیں۔ ان کا جنازہ پڑھا۔ پھر یہی روایت عبد اللہ بن سنیب کی سند سے بحوالہ ان کے دادا عبد اللہ بن ابی امامہ بن ثعلبہ نقل کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۹) تجرید (۱۴۸/۲)"}],[9493,"§۹۵۳۰ ۔ ابوامامہ الباہلی\nان کا نام صدی بن عجلان ہے، پہلے ذکر ہو چکا ہے۔"],[9494,"§۹۵۳۱ ۔ ابوامامہ بن سہل انصاری(1)\nثم البیاضی۔ واقدی کہتے ہیں: یہ صحابی ہیں۔ خلیفہ اور بغوی نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور محمد بن اسحاق کی سند سے بحوالہ محمد بن مالک، وہ اپنے بھائی عبد اللہ بن کعب سے وہ ابوامامہ بن سہل سے جو بنی بیاضہ کے فرد ہیں، روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جو شخص اپنی قسم سے کسی مسلمان کا حق مارتا ہے، اللہ تعالیٰ اس پر جنت (کا اولین داخلہ) حرام کر دیتا ہے اور جہنم (میں بطور سزا جانا) اس کے لیے واجب کر دیتا ہے۔(2) اس کی سند مضبوط ہے۔ البتہ مسلم اور بغوی نے اسے علاء بن عبد الرحمن کی سند سے بحوالہ معبد بھی اور انہوں نے اپنے بھائی سے روایت کیا ہے، فرماتے ہیں: ابوامامہ بن ثعلبہ سے مروی ہے، جو محفوظ سند ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۵) الاستيعاب (۲۸۹۳)\n(2) مسلم کتاب الایمان باب وعید من اقتطع حق ... (۳۵۱) ابن ماجہ کتاب الاحتکام باب من خلف علی یمین فاجرۃ (۲۳۲۴)"}],[9495,"§۹۵۳۲ ۔ ابوامامہ انصاری(1)(2)\nبے نسبت، بے نام۔ ابن مندہ نے ان میں اور باہلی میں فرق کیا ہے اور کہا: عثمان بن عوف نے بحوالہ جریری، ابوالنضرہ سے وہ ابو سعید سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے وہاں آپ انصار کے ایک شخص سے ملے جسے ابوامامہ کہا جاتا تھا۔۔۔۔ پھر وہ حدیث ذکر کی۔ ابوداؤد نے یہ روایت اسی سند سے روایت کی ہے جس میں کہا آپ نے نماز کے وقت کے علاوہ ایک انصاری شخص کو بیٹھے دیکھا وہ عرض کرنے لگا: یا رسول اللہ! مجھے پریشانیوں اور قرضوں نے گھیرا ہوا ہے۔ آپ نے فرمایا: \"کیا میں تجھے ایسا قول نہ بتاؤں جسے تو کہے تو اللہ تعالیٰ تیرا قرض ادا کر دے؟\" میں نے عرض کیا: یا رسول اللہ! کیوں نہیں۔۔۔۔۔ پھر وہ حدیث ذکر کی۔ اس کے آخر میں ہے کہ میں نے وہ کلمات کہے تو اللہ تعالیٰ نے میرا قرض ادا کر دیا۔ شروع سے حدیث کے سیاق سے یہ ظاہر ہوتا ہے کہ وہ ابو سعید خدری کی حدیث ہے اور آخر سے لگتا ہے کہ انہی ابوامامہ کی روایت ہے۔ تہذیب اور اطراف میں مزنی(3) نے ان کے سوانح چھوڑ دیے جس پر میں نے ان دونوں کتابوں میں ان کی اس کمی کو دور کیا ہے۔ اور الکنیٰ میں ابواحمد حاکم بھی ان سے غافل رہے۔ ہو سکتا ہے یہ ابوامامہ بن ثعلبہ حارثی ہوں، لیکن ابن مندہ نے انہیں علیحدہ ذکر کیا ہے اور ابو نعیم نے بھی ان کی پیروی کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۸۷) تجرید (۱۴۹/۲)\n(2) ابوداؤد کتاب الصلاۃ باب فی الاستعاذۃ (۱۵۵۵)\n(3) تہذیب التہذیب (۱۴/۱۲)"}],[9496,"§۹۵۳۳ ۔ ابوامیہ (تمیرے) الجشمی (جیم کے پیش اور شین کے زبر سے)(1)\nابو عمر کہتے ہیں: صحابہ رضی اللہ عنہم کے بعض مؤلفین نے انہیں ذکر کیا ہے اور لیث کی سند سے بحوالہ معاویہ بن صالح، عصام بن یحییٰ سے بحوالہ ان کے روزوں کے متعلق ایک حدیث روایت کی ہے، جو انس بن مالک قشیری کعبی کی حدیث جیسی ہے کہ \"اللہ تعالیٰ نے مسافر سے روزے اور آدھی نماز کو ساقط کر دیا ہے۔\"(2) فرماتے ہیں: حدیث مضطرب ہے۔ انہیں ابوامیہ اور ابو تمیمہ بھی کہا گیا ہے، جو صحیح نہیں۔ میں کہتا ہوں: ابن ابی خیثمہ نے بحوالہ قتیبہ، لیث سے اسی سند سے ذکر کیا ہے۔ لیکن عصام اور صحابی کے درمیان سے دو آدمی ساقط ہو گئے۔ ابن مندہ نے ان کا عنوان ابوامیہ ضمری دیا اور حدیث لیث کی سند سے بیان کر کے ان دونوں حضرات کا ذکر کیا ہے۔ وہ ابو قلابہ الجرمی عبد اللہ بن زیاد سے روایت کرتے ہیں۔ لیکن انہوں نے \"ابوامیہ بن جعدہ کے بھائی سے مروی ہے\" کہا۔ پھر دوسری سند قتیبہ کی روایت جیسی نقل کی لیکن اس میں بھی ابوامیہ کہا، ایسا ہی طبرانی نے یہ روایت مسند شامیین میں معاویہ بن صالح کے سوانح میں، دولابی نے الکنیٰ میں عبد اللہ بن صالح بحوالہ معاویہ نقل کی لیکن انہوں نے \"عن ابی امیہ جعدی\" کہا۔ ایسا ہی بغوی نے انس بن مالک قشیری کی سوانح میں ابراہیم بن حانی بحوالہ عبد اللہ بن صالح ان کا علیحدہ ذکر کیا ہے، گویا ان کے نزدیک وہ وہی ہیں، جو جعدی نہیں۔ بعض نے عمرو بن امیہ ضمری کے سوانح میں ذکر کیا ہے کہ ان کی کنیت بھی ابوامیہ ہے تو جس نے ضمری کہا اس کی مراد یہ ہیں اور جس نے قشیری کہا اس کی مراد انس بن مالک ہیں جو کعبی ہیں۔ اس لیے جن کی طرف قشیری لوگ منسوب ہوتے ہیں وہ قشیر بن کعب بن ربیعہ بن عامر بن صعصعہ ہیں اور جس نے جعدی کہا تو انہیں ان کے چچا کی طرف منسوب کر دیا کیونکہ جعدہ، ابن کعب ہیں جو قشیر بن کعب کے بھائی ہیں۔ جہاں تک ضمری کا تعلق ہے تو وہ ان کے ساتھ صرف مضر بن نزار بن معد بن عدنان سے ملتے ہیں جو قشیر یوں اور جعد یوں کے دادا ہیں۔ وہ معاویہ بن بکر بن ہوازن بن منصور بن عکرمہ بن حفصہ بن قیس غیلان بن مضر ہیں اور ضمرہ بن بکر بن عبد مناف بن کنانہ بن خزیمہ بن مدرکہ بن الیاس بن مضر ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۹۱) تجرید (۱۴۹/۲)\n(2) نسائی کتاب الصیام باب ذکر وضع الصیام عن المسافر والاختلاف علی الاوزاعی فی خبر عمرو بن امیہ (۲۲۶۷، ۲۲۶۸) المعجم الکبیر (۹۰۶/۲۲، ۹۰۷) اسد الغابہ (۳۷۶/۴)"}],[9497,"§۹۵۳۴ ۔ ابوامیہ دوسی ثم زہرانی\nبعض ازدی پھر صقعی (صاد پر زبر قاف ساکن پھر با ہے) کہتے ہیں۔ صقب بن دھمان بن نضر بن حارث کی طرف نسبت ہے جو ام قافہ بنت ابی قافہ، صدیق اکبر رضی اللہ عنہ کی بہن کے، اشعث سے پہلے والے شوہر ہیں۔ ان کی ان سے ایک بیٹی تھی جس کا نام امیمہ تھا جس سے عبد اللہ بن زبیر رضی اللہ عنہ نے نکاح کیا تھا۔ یہ بات ابن کلبی اور ابن درید نے ذکر کی ہے۔ اس بنا پر وہ اس قسم سے ہوئے۔ اس لیے کہ سیرت شامیہ میں ہے: ام قافہ فتح مکہ کے موقع پر مکن تھیں۔ اس واسطے ان کے والد ان کی شادی کسی مسلمان سے ہی کریں گے اور جو صدیق اکبر کے سسرالی رشتہ دار ہوں گے وہ ضرور نبی صلی اللہ علیہ وسلم سے ملے ہوں گے۔"],[9498,"§۹۵۳۵ ۔ ابوامیہ(1)\nوہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، جب لوٹنے لگے، فرمایا: دوپہر کے کھانے کا انتظار نہیں کرتے ہو؟ ابن ابی حاتم کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے مسافر سے روزہ اور آدھی نماز معاف کر دی ہے۔(2) اسے بغوی نے نقل کیا ہے، فرماتے ہیں بعض لوگ کہتے ہیں: وہ عمرو بن امیہ ضمری ہیں اور بعض کا قول ہے: ابوامیہ ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۹۶) تجرید (۱۴۹/۲)\n(2) ابوداؤد کتاب الصوم باب اختیار الصوم (۲۴۰۸) بنحوہ، ترمذی کتاب الصیام باب ما جاء فی الرخصۃ فی الافطار (۷۱۱) نسائی کتاب الصوم باب وضع الصیام عن الحبلی والمرضع (۲۳۱۴) ابن ماجہ کتاب الصیام باب ما جاء فی الافطار للحامل والمرضع (۱۶۶۷) مسند احمد (۳۴۷/۴) (۲۹/۵)"}],[9499,"§۹۵۳۶ ۔ ابوامیہ ازدی(1)\nجنادہ کے والد، امام بخاری(2) اور ابو حاتم(3) فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔ میں نے جنادہ کے سوانح میں وضاحت کر دی ہے کہ ان کے والد کا نام مالک ہے اور جس نے ان کا نام کثیر بتایا اس نے انہیں دوسرے سے ملا دیا ہے۔ جن لوگوں نے ان کے \"مالک\" نام پر بھروسا کیا ہے ان میں سے خلیفہ بن خیاط ہیں۔","",{"fn":"(1) اسد الغابہ (۵۶۹۲) تجرید (۱۴۹/۲)\n(2) التاریخ الکبیر (۶/۲)\n(3) الجرح والتعدیل (۵۱۵/۱)"}],[9500,"§۹۵۳۷ ۔ ابوامیہ بن عمرو\nبن وہب بن معتب ثقفی۔ عمرو بن امیہ بن وہب میں ان کی تحقیق گزر چکی ہے۔"],[9501,"§۹۵۳۸ ۔ ابوامیہ جمحی\nصفوان بن امیہ بن خلف تذکرہ ہو گیا۔"],[9502,"§۹۵۳۹ ۔ ابوامیہ\nوہ عمیر بن وہب ہیں، پہلے تذکرہ ہو چکا ہے۔"],[9503,"§۹۵۴۰ ۔ ابوامیہ الجمحی (یہ دوسرے ہیں)(1)\nابو عمر کہتے ہیں: بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے جبکہ اس میں تامل ہے، روایت کرتے ہیں: کسی نے رسول اللہ صلی اللہ علیہ وسلم سے قیامت کے متعلق پوچھا، آپ نے فرمایا: \"اس کی ایک نشانی یہ ہے کہ (بڑے لوگ علم سے محروم ہوں گے تو پھر) چھوٹوں سے علم حاصل کیا جائے گا۔\" ابو موسیٰ(2) کہتے ہیں: ابو مسعود نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور کہا کہ ان سے بکر بن سوادہ روایت کرتے ہیں، پھر وہ حدیث ذکر کی۔ لیکن اس کی سند بیان نہیں کی۔ جو طبرانی کے ہاں ابن لہیعہ کی سند سے بحوالہ بکر اسی مفہوم میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۴) تجرید (۱۴۹/۲)\n(2) المعجم الکبیر (۹۰۸/۲۲) مجمع الزوائد (۱۳۵/۱) جامع المسانید (۲۳۹/۱۳)"}],[9504,"§۹۵۴۱ ۔ ابوامیہ الجمحی (دوسرے ہیں)\nان کا بیان ابو غلیظ، غین نقطے والی میں آئے گا۔"],[9505,"§۹۵۴۲ ۔ ابوامیہ الجعدی\nابوامیہ ذکر ہو چکا ہے، ایسا ہی الجعثی کا بھی تذکرہ گزر چکا ہے۔"],[9506,"§۹۵۴۳ ۔ ابوامیہ الضمری(1)\nعمرو بن امیہ ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۰۳) الاستيعاب (۲۸۹۷)"}],[9507,"§۹۵۴۴ ۔ ابوامیہ الفزاری(1)\nجن کا ذکر ابو امیہ پہلے حرف الف میں ہوا ہے۔","",{"fn":"(1) الاستيعاب (۲۸۹۴)"}],[9508,"§۹۵۴۵ ۔ ابوامیہ القشیری والکعبی\nتذکرہ ہو چکا۔"],[9509,"§۹۵۴۶ ۔ ابوامیہ المخزومی(1)\nبقول ابن اسکن: ان کا شمار اہل مدینہ میں ہے۔ پھر اسحاق بن عبد اللہ بن ابی طلحہ کی سند سے بحوالہ ابو المنذر مولائے ابوذر غفاری، ابوامیہ مخزومی کی ان حدیث نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک چور لایا گیا جس نے اپنے قصور کا اعتراف کیا لیکن اس کے پاس سامان نہ ملا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے خیال میں تم نے چوری نہیں کی۔\"(2) اس نے کہا: کیوں نہیں۔ اس سے پھر پوچھا۔۔۔۔ الحدیث ابوداؤد، نسائی، ابن ماجہ اور داری نے اسی سند سے نقل کی ہے۔ ابوداؤد نے روایت کی کہ ہشام کی روایت میں اسحاق بن ابی المنذر بحوالہ ابوامیہ۔ انصار(3) کے ایک شخص۔ لکھا ہے۔ جبکہ پہلی سند زیادہ مشہور ہے ابن اسکن فرماتے ہیں: اس میں حماد اسحاق سے روایت کرنے میں منفرد ہیں۔ میں کہتا ہوں: جس روایت کی طرف ابوداؤد نے اشارہ کی ہے۔ ہشام کی روایت اس کی تردید کرتی ہے۔ جبکہ دولابی نے اپنی سند سے اسے موصول کہا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۷) تجرید (۱۴۹/۲)\n(2) ابوداؤد کتاب الحدود باب فی التلقین فی الحد (۴۳۸۰) نسائی کتاب قطع السارق باب تلقین السارق (۴۸۷۷) ابن ماجہ کتاب الحدود باب تلقین السارق (۵۶۹۷) مسند احمد (۲۹۳/۵)\n(3) جامع المسانید والسنن (۲۳۸/۱۳)"}],[9510,"§۹۵۴۷ ۔ ابواناس بن زنیم اللیثی یا دولی(1)\nساریہ بن زنیم کے بھتیجے۔ ابو عمر نے ان کا ذکر کیا کہ وہ شاعر تھے اور ان کے شرفاء سے تعلق رکھتے تھے وہی اپنے قصیدہ میں کہتے ہیں: فما حملت من ناقۃ فوق رحلہا ابر و اوفی ذمۃ من محمد(2) فرماتے ہیں: ان کا ایک بیٹا انس بن ابی اناس تھا جسے الحکم بن عمرو نے اپنی وفات(3) کے وقت خراسان کا خلیفہ مقرر کیا تھا۔ میں کہتا ہوں: اناس ھمزہ کے پیش اور نون بغیر شد کے ہے۔ مذکورہ قصیدہ کس نے کہا ہے اس میں اختلاف ہے۔ بعض کا قول ہے کہ یہی ہیں بعض انس بن زنیم، بعض ساریہ بعض اسید بن ابی اناس کہتے ہیں۔ اسی قصیدہ کو ابن اسحاق نے ایمن بن زنیم کی طرف منسوب کر کے پڑھا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۸) تجرید (۱۴۹/۲)\n(2) اسد الغابہ (۳۷۹/۴)\n(3) اسد الغابہ (۳۷۹/۴)"}],[9511,"§۹۵۴۸ ۔ ابواہاب بن عزیز(1)\nبن قیس ابن سوید بن ربیعہ بن زید بن عبد اللہ بن دارم تمیمی داری، بنی نوفل بن عبد مناف کے حلیف ان کے والد العزیز (عین کے زبر اور دو زاؤں سے) مکہ آئے اور ان سے معاہدہ کیا ہے اور ان کے ہاں سے شادی کی۔ چنانچہ ان کی بہن عمرو بن نوفل کی بیٹی ہے ان کے ہاں ابواہاب پیدا ہوئے پھر عقبہ بن عامر کی بیٹی ام یحییٰ سے شادی کی، جو ابواہاب کی بیٹی تھی، اتنے میں ایک سیاہ فام لونڈی آ کر کہنے لگی: میں نے تم دونوں کو دودھ پلایا ہے۔ حدیث جو صحیح میں مذکور ہے۔ جعفر المستغفری نے ان کا صحابہ میں ذکر کیا ہے اور کہا کہ ان سے ایک حدیث روایت کی جاتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ٹیک لگا کر کھانے سے منع فرمایا ہے،(2) فاکہی نے کتاب مکہ میں سفیان کی سند سے نقل کیا ہے کہ انہوں نے کسی شخص سے سنا کہ ابواہاب جن کا ابھی ذکر ہوا ہے پہلے شخص ہیں جب ان کی وفات ہوئی تو مسجد حرام میں ان کا جنازہ پڑھا گیا۔","",{"fn":"(1) اسد الغابہ (۵۷۰۰) تجرید (۱۵۰/۲)\n(2) مجمع الزوائد (۲۵/۵) اسد الغابہ (۳۷۹/۴)"}],[9512,"§۹۵۴۹ ۔ ابواوس الثقفی(1)\nحذیفہ بن اوس، تذکرہ ہو چکا ہے۔","",{"fn":"(1) مسند بزار (۲۸۷۰) اسد الغابہ (۵۷۰۹)"}],[9513,"§۹۵۵۰ ۔ ابواوس(1)\nجابر بن طارق ابن ابی طارق الاحمسی، طارق کے والد، انہیں جابر بن عوف بھی کہا جاتا ہے جو ان کے دادا کی طرف نسبت ہے۔ اس واسطے کہ ابو طارق کا نام عوف ہے اسماء میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۰)"}],[9514,"§۹۵۵۱ ۔ ابواوفی الاسلمی(1)\nعبد اللہ کے والد، ان کا نام علقمہ ہے، ناموں میں تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۱) الاستيعاب (۲۹۰۲)"}],[9515,"§۹۵۵۲ ۔ ابوایاس الساعدی(1)\nطبری نے ان کا ذکر تو کیا ہے لیکن ان کی کوئی روایت نقل نہیں کی جبکہ مستغفری نے ان کا ذکر کیا اور عبد العزیز بن ابان، بحوالہ صالح بن حسان، سعید بن المسیب ابوایاس الساعدی سے اپنی سند سے نقل کیا، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ سوار تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: کہو! میں نے عرض کیا: کیا؟ فرمایا: کہو وہ اللہ ایک ہے۔ پھر فرمایا: کہو! \"کہو میں پناہ طلب کرتا ہوں صبح کے رب کی۔ کہو میں پناہ مانگتا ہوں لوگوں کے رب کی۔\" اس کے بعد ارشاد فرمایا: \"اے ایاس! لوگوں نے ان جیسا کلام نہیں پڑھا۔\"(2) ایسا ہی حارث بن ابی اسامہ نے بحوالہ عبد العزیز بن ابان نقل کیا ہے اور عبد العزیز متروک راوی ہے۔ ابن ابی عاصم(3) نے اسے وحدان میں ذکر کیا کہ ابوایاس بن سہل بنی ساعدہ سے ہیں، پھر ابو شیبہ سے بحوالہ مصعب بن مقدام، محمد بن ابراہیم، ابو حازم سے روایت نقل کی کہ وہ ابن ابی ایاس بن سہل انصاری کے پاس بیٹھے۔ پھر وہ کہنے لگے: ذرا دھیان کرو میں متوجہ ہو گیا، کہنے لگے: کیا میں تمہیں اپنے والد کی نبی صلی اللہ علیہ وسلم سے کوئی روایت نہ سناؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"سورج طلوع ہونے تک نماز پڑھنا مجھے اللہ تعالٰی کی راہ میں عمدہ گھوڑے باندھنے سے زیادہ محبوب ہے۔” (حدیث)(4) یونہی فرمایا: میرے خیال میں یہ پہلے کے علاوہ ہیں یقیناً ان کا نام سہل ہے انہیں ابو ایاس اس وجہ سے کہا جاتا ہے کہ ان کے بیٹے کا نام ایاس تھا۔","",{"fn":"(1) اسد الغابہ (۵۷۰۵) تجرید (۱۵۰/۲)\n(2) ترمذی کتاب الدعوات باب فی انتظار الفرج وغیر ذلک (۳۵۷۵) نسائی کتاب الاستعاذۃ باب (۱) حدیث (۵۴۴۴) مسند احمد (۱۵۳/۴)\n(3) الاحاد والمثانی (۲۱۶/۴)\n(4) مجمع الزوائد (۱۶۹۴۶) المعجم الکبیر (۵۷۶۱)"}],[9516,"§۹۵۵۳ ۔ ابو ایاس اللیثی\nابن عساکر نے اپنی تاریخ کے حرف الف اور آخری حرف یاء میں ان کا ذکر کیا ہے۔ فرماتے ہیں: بعض لوگوں کا کہنا ہے: وہ صحابی ہیں۔ سیدنا عمر رضی اللہ عنہ کے خطبہ جابیہ میں شریک تھے۔ پھر عبید اللہ بن ابی زیاد کی سند سے بحوالہ زہری، عبید اللہ بن عبداللہ بن عتبہ، ابو ایاس لیثی ثم الاجہی، صحابی رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ ایک دفعہ وہ جابیہ میں سیدنا عمر رضی اللہ عنہ کی آمد کے وقت ان کے پاس تھے کہ آپ کے پاس ایک شخص آ کر کہنے لگا: میری بیوی نے زنا کر لیا ہے، پھر وہ قصہ ذکر کیا۔ ابن عساکر فرماتے ہیں: ان کے علاوہ کسی کا قول ہے: “ابو زائدہ لیثی سے مروی ہے یہی درست ہے۔” میں کہتا ہوں: اس کا احتمال ہے، ہو سکتا ہے یہ وہ ابو اناس ہوں جن کا تذکرہ پہلے نون سے ہو چکا ہے۔"],[9517,"§۹۵۵۴ ۔ ابو ایمن الانصاری(1)\nعمرو بن الجموح کے غلام، ابن اسحاق(2) نے شہدائے اُحد میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۰۶) تجرید (۱۵۰/۲)\n(2) السیرۃ النبویۃ عن ابن اسحاق (۹۸/۳)"}],[9518,"§۹۵۵۵ ۔ ابو ایوب انصاری(1)\nخالد بن زید بن کلیب، کنیت سے مشہور ہیں، ان کا نام پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۴) الاستیعاب (۲۹/۵)"}],[9519,"§۹۵۵۶ ۔ ابو ایوب\nجاریہ بن قدامہ تمیمی۔ ناموں میں تذکرہ ہو گیا۔ نام سے زیادہ مشہور ہیں۔"],[9520,"§۹۵۵۷ ۔ ابو ایوب الیمامی(1)\nمستغفری نے ان کا ذکر کیا ہے اور خلیفہ نے نقل کیا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ہے۔","",{"fn":"(1) تجرید (۱۵۰/۲)"}],[9521,"§۹۵۵۸ ۔ ابو ایوب (دوسرے)\nعثمانی نے صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے اور عاصم بن علی کی سند سے بحوالہ ان کے والد عبداللہ بن عثمان بن خیثم سے وہ اپنے دادا ابو ایوب سے روایت کرتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: مجھے مختصر سی نصیحت کریں۔ ابن فتحون نے ان کا ذکر کیا ہے۔"],[9522,"§۹۵۵۹ ۔ ابو ایوب الازدی\nان شاء اللہ تعالیٰ ان کا تذکرہ چوتھی قسم میں آئے گا۔"],[9523,"§۹۵۶۰ ۔ ابو ایوب المالکی\nسیف نے فتوح میں ذکر کیا ہے کہ سیدنا عمرو بن العاص نے انہیں رومیوں کی جنگ میں لشکر کا امیر بنایا تھا۔ طبری نے اپنی مسند سے ان کا ذکر کیا اور ابن فتحون نے ان کا استدراک کیا ہے۔"],[9524,"§۹۵۶۱ ۔ ابو ادریس الخولانی(1)\nعائد اللہ بن عبید اللہ تذکرہ پہلے گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۷۲) الاستیعاب (۲۸۷۴)"}],[9525,"§۹۵۶۲ ۔ ابو اسحاق\nقبیصہ بن ذویب خزاعی، ان کا ذکر بھی ہو گیا ہے۔"],[9526,"§۹۵۶۳ ۔ ابو اسحاق(1)\nابراہیم بن عبدالرحمن بن عوف زہری، تذکرہ ہو گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۷۹)"}],[9527,"§۹۵۶۴ ۔ ابو امامہ بن سہل(1)\nمحمد بن حنیف انصاری ان کا نام اسعد ہے، پہلے تذکرہ گزر گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۷)"}],[9528,"§۹۵۶۵ ۔ ابو امیہ بن الاخنس\nبن شہاب ابن شریق ثقفی، ان کے والد کے صحابی ہونے میں اختلاف ہے۔ وہ سیدنا عمر رضی اللہ عنہ سے روایت کرتے ہیں۔ ثوری نے کہا: عمرو بن عبد الرحمن سہمی سے بحوالہ ابو سلمہ بن سفیان مخزومی، ابو امیہ بن اخنس ثقفی سے روایت ہے۔ فرمایا: میں عمر رضی اللہ عنہ کے پاس تھا۔ آپ کے پاس ایک شخص آ کر کہنے لگا: میرا بیٹا اتنا زخمی کیا گیا کہ اس کی ہڈی نظر آنے لگی۔"],[9529,"§۹۵۶۶ ۔ ابو اسحاق\nکعب بن مانع، جو کعب احبار سے مشہور ہیں۔ ناموں میں تذکرہ گزر چکا ہے۔"],[9530,"§۹۵۶۷ ۔ ابو الاسود\nیزید بن الاسود الجرشی، تذکرہ ہو چکا ہے۔"],[9531,"§۹۵۶۸ ۔ ابو الاسود الدئلی\nظالم بن عمرو، ذکر ہو گیا ہے۔"],[9532,"§۹۵۶۹ ۔ ابو الاسود الہرانی\nاز عنزہ، وثیمہ نے ردّۃ میں ان کا ذکر کیا کہ وہ بنی حنیفہ میں ٹھہرے ہوئے تھے جب مسیلمہ نے صدیق اکبر کے قاصد حبیب بن عبداللہ کو شہید کر دیا تو ابو الاسود سے رہا نہ گیا، بول اٹھے۔ قاصد کا قتل کرنا گردشِ ایام سے گزشتہ زمانے سے بڑا جرم سمجھا جاتا ہے۔ وہ شخص جو بنی حنیفہ سے ہے گزر گیا یا باقی رہا اسلام کے لیے بہت برا واقع ہوگا۔ اس وقت ابو الاسود نے اپنا اسلام ظاہر کر دیا۔ ابن فتحون نے ان کا استدراک کیا ہے۔"],[9533,"§۹۵۷۰ ۔ ابو امیہ ازدی (قتادہ کے والد)(1)\nان کا نام کبیر (بروزن عظیم) ہے ناموں میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۹)"}],[9534,"§۹۵۷۱ ۔ ابو امیہ الشعبانی(1)\nنام محمد ہے، بعض نے عبداللہ بن اخامر کہا ہے، یحییٰ بن عبدالوہاب نے اپنے دادا ابو عبداللہ بن مندہ کی کتاب میں استدراک کیا۔ اور عبدالملک بن بیسار ثقفی کی سند سے بیان کیا کہ ابو امیہ شعبانی نے مجھ سے بیان کیا وہ جاہلی شخص تھے، پھر حدیث ذکر کی(2)۔ میں کہتا ہوں: یہ روایت یعقوب بن سفیان نے بحوالہ سلیمان بن عبد الرحمن، مطر بن العلاء عبدالملک بن بیار سے نقل کی ہے، جاہلی کہنے کے بعد فرماتے ہیں: مجھ سے معاذ بن جبل نے فرمایا (مرفوع روایت کرتے ہیں) تیس سال خلافت و نبوت کے تئیں(۳۰) سال خلافت و بادشاہت کے، تیس(۳۰) سال بادشاہت و سختی کے۔ اس کے بعد جو ہوں گے ان میں کچھ بھلائی نہیں۔ میں کہتا ہوں: ابو حاتم رازی نے کہا: انہوں نے زمانہ جاہلیت پایا ہے۔ اور ابو موسیٰ ذیل میں لکھتے ہیں: ابو امیہ شعبانی، ابو ثعلبہ خشنی سے روایت کرتے ہیں۔ میں کہتا ہوں: انہیں معاذ بن جبل سے بھی روایت حاصل ہے۔ سنن میں ان کی حدیث منقول ہے۔ امام بخاری رحمہ اللہ کی کتاب “خلق افعال العباد” میں عمرو بن حارثہ کی سند بحوالہ ان کے ابو ثعلبہ سے مروی ہے، نیز ان سے عبدالملک بن سفیان ثقفی اور عبد السلام بن مطلبہ روایت کرتے ہیں۔ ابن حبان نے انہیں ثقات التابعین میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۵) تجرید (۱۴۹/۲)\n(2) الجرح والتعدیل (۳۱۴/۴)"}],[9535,"§۹۵۷۲ ۔ ابو امیہ\nسوید بن غفلہ الجعفی، ناموں میں تذکرہ ہو چکا ہے۔"],[9536,"§۹۵۷۳ ۔ ابو امیہ العدوی\nسیدنا عمر رضی اللہ عنہ کے آزاد کردہ غلام، زمانہ نبوی پایا ہے۔ ابن ابی شیبہ نے ابن عباس رضی اللہ عنہما کی سند سے نقل کیا کہ سیدنا عمر رضی اللہ عنہ نے اپنے ایک غلام سے عقد مکاتبت کی جس کی کنیت ابو امیہ تھی، تو وہ اپنے وقت پر قسطیں لے کر حاضر ہو گیا، اس کی پہلی قسط اسلام میں ادا ہوئی۔ مجھے ان ابو امیہ کے والد کا نام معلوم نہیں۔"],[9537,"§۹۵۷۴ ۔ ابو امیہ الکندی\nشریح بن حارث کندی کوفہ کے قاضی، تذکرہ ہو چکا ہے۔"],[9538,"§۹۵۷۵ ۔ آبی اللحم الغفاری(1)\nابن عبدالبر نے کنیتوں کے حرف ہمزہ میں ابو الاعور کے سوانح سے پہلے اور ابو احمد بن جحش کے حالات کے بعد ان کا تذکرہ ان الفاظ میں کیا ہے: عبادلہ میں ان کا ذکر ہو چکا ہے یہ ان کی کنیت تو نہیں لیکن کنیت جیسی ہو گئی ہے۔ ایسا انہیں اس وجہ سے کہا جاتا تھا کیونکہ وہ گوشت کھانے سے انکار کرتے تھے۔ میرے گمان میں استیعاب پر جو ابن دحیہ کے قلم کا حاشیہ ہے اس میں میں نے دیکھا۔ کاش! جب انہیں پتہ بھی ہے کہ یہ کنیت نہیں تو پھر کنیتوں میں کیوں ذکر کیا اور یوں کیوں کہا: یہ کنیت کی طرح ہو گئی۔ یہ کیوں نہ کہا: لقب کی طرح ہو گئی؟ ہاں یہ کہا جا سکتا ہے کہ جس نے الف یا اور با نہ لکھی اس نے کنیت سمجھ لی۔ یوں یہ حالت جر میں کنیت کے مشابہ ہو گیا۔ تو تو جہالت سے بچ! جس سے ابتدائی طالب علم کا رتبہ بلند ہے چہ جائیکہ اس شیخ کا۔ ابو عمر سے پہلے اسے کنیت بنانے میں ترمذی جزء صغیر میں جو صحابہ رضی اللہ عنہم میں ہے پیش پیش ہیں۔ چنانچہ وہ کنیتوں میں لکھتے ہیں: ان میں سے ابو اللحم ہیں جو صحابی ہیں۔ ایسا ہی اقدام ابو احمد حاکم نے الکنی میں افراد کے حرف ہمزہ میں کیا ہے۔ جس میں ابن مندہ کو ایک اور وہم ہوا۔ جو سب غلط ہے۔ انہیں حرف ہمزہ میں کنیت فرض کر کے شامل کرنا دوسری غلطی ہے۔ اس کا مقام تو لام ہے۔ اگر چہ الف اور باء کنیت کے حروف ہیں پھر حروف کی ترتیب میں ان کے بعد والے حروف کا اعتبار ہوتا ہے۔ اسی روش پر دولابی، ابن السکن اور ابن مندہ چلے ہیں۔ ان سب نے انہیں حرف لام کے تحت کنیتوں میں ذکر کیا ہے۔ ابو نعیم نے ابن مندہ پر نکیر کی جو درست ہے۔","",{"fn":"(1) الاستیعاب (۲۸۶۹)"}],[9539,"§۹۵۷۶ ۔ ابو الاسود التمیمی(1)\nابو موسیٰ نے بحوالہ مستغفری ان کا استدراک کیا اور عبدالرزاق کی سند سے بحوالہ معمر نقل کیا فرماتے ہیں مجھے تمیم کے ایک شیخ نے ان کے ایک شیخ کے حوالہ سے بتایا جنہیں ابو الاسود کہا جاتا تھا کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: “جھوٹی قسم رشتوں کو کاٹ دیتی ہے۔”(2) جہاں تک میرا علم ہے آپ نے یہ بھی فرمایا: “شہروں کو ویران کر دیتی ہے۔” اس میں لفظی غلطی ہوئی ہے۔ درست ابو سود ہے (ضمہ سین واؤ ساکن) اس کے شروع میں الف نہیں۔ ایسا ہی احمد نے ابن المبارک کی سند سے بحوالہ معمر ذکر کیا ہے، عنقریب آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۶۷۵) تجرید (۱۴۷/۲)\n(2) مسند احمد (۷۹/۵) المعجم الکبیر (۹۵۰/۲۲) مجمع الزوائد (۱۷۹/۴)"}],[9540,"§۹۵۷۷ ۔ ابو الاسود الدوسی\nفرمایا: ہم لوگ نبی صلی اللہ علیہ وسلم کے ساتھ تھے۔ ایسا ہی یزید بن ہارون نے کہا، اس میں یحییٰ بن معین کو وہم ہو گیا، اور کہا: درست ابو اسحاق سے بحوالہ ابو ہریرہ رضی اللہ عنہ ہے۔ ابن فتحون نے ان کا ذکر کیا ہے۔ میں کہتا ہوں: مذکورہ حدیث یزید بن ابی حبیب کی سند سے بحوالہ بکیر بن اشج، سلیمان بن یسار، ابو اسحاق سے وہ ابو ہریرہ رضی اللہ عنہ سے، ایسا ہی یعقوب بن ابراہیم بن سعد، بحوالہ اپنے والد وہ ابن اسحاق سے وہ یزید بن ابی حبیب سے، اسی طرح ان کے علاوہ ابن اسحاق سے روایت کرتے ہیں۔"],[9541,"§۹۵۷۸ ۔ ابو الاسود الدّیلی\nابن شاہین نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا اور عبداللہ بن عثمان بن خیثم کی سند سے بحوالہ محمد بن خلف بن الاسود سے روایت نقل کی کہ ابو الاسود نے انہیں بتایا کہ نبی صلی اللہ علیہ وسلم فتح مکہ کے روز لوگوں کے ساتھ تشریف لائے۔ (الحدیث) وہم ہے جو سقوط سے پیدا ہوا، درست یوں ہے ان کے والد اسود نے بیان کیا وہ اسود بن خلف۔ اسماء میں سے حرف ہمزہ میں ان کا حال گزر چکا ہے۔"],[9542,"§۹۵۷۹ ۔ ابو الاسود\nعبد الرحمن بن یعمر دولی، ناموں میں ذکر ہو چکا ہے۔ ان کی حدیث ہے: “حج عرفہ ہے۔” جسے ابن شاہین نے “ظالم ابو الاسود” کے سوانح میں درج کر دیا ہے جو خطا ہے غلط فہمی سے پیدا ہوئی۔ یہ کنیت اور نسبت عبد الرحمن اور ظالم میں مشترک ہے صحبت اور حدیث عبد الرحمن کی ہے نہ کہ ظالم کی۔ ظالم کا تذکرہ قسم ثالث میں ہو چکا ہے۔"],[9543,"§۹۵۸۰ ۔ ابو الاسود السلمی(1)\nیہ نبی صلی اللہ علیہ وسلم سے عمارت کے منہدم ہونے اور گر کر ہلاک ہونے سے پناہ کے بارے میں ایک حدیث روایت کرتے ہیں۔ تہذیب میں مری لکھتے ہیں: ابن اسکن کی روایت بحوالہ نسائی میں یوں ہی لکھا ہے، جو وہم ہے درست ابو الیسر (یاء نقطوں والی جس کے نیچے دو نقطے ہیں اس کے سین بغیر نقطوں کے) حاکم نے بھی اسی سند سے نقل کیا ہے، جس سے نسائی نے کیا وہی درست ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۲) الاستیعاب (۲۸۸۹)"}],[9544,"§۹۵۸۱ ۔ ابو امامہ\nعبد اللہ بن اسعد بن زرارہ کے سوانح میں ان کا ذکر آتا ہے۔ جس نے انہیں اسعد بن زرارہ کے علاوہ کوئی شخصیت سمجھا ہے اسے غلطی لگی ہے۔"],[9545,"§۹۵۸۲ ۔ ابو امیہ التغلبی(1)\nامام احمد رحمہ اللہ نے اپنی مسند میں ان کا عنوان قائم کیا ہے۔ ابو موسیٰ نے ان کا استدراک کیا مجھے عالی مسند سے ہلال الحفار کے جزء میں ایک حدیث ملی ہے، فرمایا: ہمیں محمد بن سدی نے بحوالہ جریر، عطاء بن السائب سے وہ جندب بن ہلال سے وہ ابو امیہ سے (جو بنی تغلب کے ایک فرد ہیں) روایت کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: “جزیہ مسلمانوں کے ذمہ نہیں، جزیہ تو یہود و نصاریٰ پر واجب ہے۔”(2) ابو موسیٰ نے کہا: اس روایت میں ایسا ہی جندب بن ہلال لکھا ہے۔ جسے شریح بن یونس نے جریر سے روایت کیا فرماتے ہیں: حرب بن عبید اللہ، اپنے والد سے، اپنے دادا ابو امیہ سے روایت کرتے ہیں نام بیان نہیں کیا۔ ابو داؤد نے یہ روایت نقل کی تو کہا: حرب سے وہ اپنے نانا سے وہ اپنے والد سے ایسا ہی مفہوم روایت کرتے ہیں۔ جریر اور ابو الاحوص نے عطاء کی یادداشت کھو جانے کے بعد انہیں پر روایت بیان کرنے پر مجبور کیا۔ جبکہ ثوری نے اسے روایت کیا وہ عطاء سے پرانے سننے والوں میں سے ہیں۔ بکر بن وائل کے ایک شخص سے وہ اپنے ماموں سے روایت کرتے ہیں، انہوں نے کہا: میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم وکیع فرماتے ہیں: سفیان سے اسی سند سے مرسل مروی ہے کہ ان کے والد نے انہیں بتایا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ اسے ابو داؤد نے نقل کیا۔ نیز انہوں نے وکیع کی سند سے یہ روایت نقل کی ہے، جس میں ثوری بحوالہ عطاء وہ حرب سے مرسل نقل کرتے ہیں۔ اور ابو حمزہ بیشکری کی سند سے بحوالہ عطاء بن السائب، حرب بن عبید اللہ ثقفی ان کے والد نے بتایا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ اس شدید اختلاف کا خلاصہ یہی نکلتا ہے کہ جریر کی روایت غلط ہے جو اُن کا قول: ان کے نانا سے لے کر ابو امیہ تک ہے، درست پہلا طریق ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۳) تجرید (۱۴۹/۲)\n(2) ابو داؤد کتاب الخراج والفی والامارۃ باب فی تعشیر اہل الذمۃ (۳۰۴۶) ترمذی کتاب الزکاۃ باب ما جاء لیس علی المسلمین جزیۃ (۶۳۳، ۶۳۴) مسند احمد (۴۷۴/۳) (۴۱۰/۳) جامع المسانید والسنن (۲۴۰/۱۳)"}],[9546,"§۹۵۸۳ ۔ ابو انس انصاری(1)\nدولابی نے کنیتوں میں ان کا ذکر کیا جہاں فضائل صحابہ رضی اللہ عنہم کی بحث ہے، لیکن ان کی کوئی حدیث ذکر نہیں کی۔ جبکہ ابن مندہ نے ابراہیم بن ابی یحییٰ کی سند سے بحوالہ مالک بن حمزہ بن ابی انس، وہ اپنے والد سے، وہ اپنے دادا سے نقل کرتے ہیں۔ جو خطاء پر مبنی ہے۔ درست ابراہیم سے بحوالہ مالک بن حمزہ بن ابی اسید وہ اپنے والد سے وہ اپنے دادا سے ہے۔ اسے امام بخاری رحمہ اللہ نے حمزہ بن ابی اسید(2) کی روایت سے مفہوماً نقل کیا ہے۔ ایسا ہی ابو داؤد نے حمزہ بن ابی اسید سے بحوالہ ان کے والد ان کے دادا سے اس حدیث کے علاوہ ایک حدیث روایت کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۶۹۹) تجرید (۱۵۰/۲)\n(2) بخاری کتاب المغازی باب (۳۹۸۴/۱۰)"}],[9547,"§۹۵۸۴ ۔ ابو اوس تمیم بن حجر\nبغوی نے ایسا ہی کیا ہے، جبکہ ان کے علاوہ کا قول ہے: ابو تیم اوس بن حجر اور یہی درست ہے۔"],[9548,"§۹۵۸۵ ۔ ابو ایوب (بے نسبت)(1)\nابو موسیٰ نے ان کا استدراک کیا جسے ابو بکر بن ابو علی کی طرف منسوب کیا۔ اور عبد الرحمن بن ابی زیاد افریقی کی سند سے وہ اپنے والد سے بحوالہ ابو ایوب روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “ایک مسلمان پر ایک مسلمان کے لیے چھ باتیں ضروری ہیں، جو نیکی کی ہیں۔”(2) پھر وہ حدیث ذکر کی۔ میں کہتا ہوں: یہ روایت اسحاق بن راہویہ نے مسند ابو ایوب انصاری میں نقل کی ہے۔ ایسا ہی اسے امام بخاری رحمہ اللہ(3) نے الادب المفرد میں درج کیا وہ بھی افریقی کی سند سے ان کے والد سے بحوالہ ابو ایوب انصاری ہے۔ حدیث میں ایک قصہ ہے جو ابو ایوب کی مذکورہ حدیث کو روایت کرنے کا سبب ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۰۹) تجرید (۱۵۰/۲)\n(2) المعجم الکبیر (۴۰۷۶/۴) مجمع الزوائد (۱۸۵/۸)\n(3) الادب المفرد (۹۲۲)"}],[9549,"§۹۵۸۶ ۔ ابو ایوب الازدی\nمستدرک میں حاکم لکھتے ہیں: دنیا سے بے رغبت صحابی تھے۔ پھر ابو اسحاق فزاری کی سند سے بحوالہ ابراہیم بن کثیر، عمارہ بن غزیہ سے ایک روایت نقل کی کہ ابو ایوب ازدی معاویہ رضی اللہ عنہ کے پاس آئے۔ ان سے ذرا بے وفائی محسوس ہوئی تو فرمانے لگے: نبی صلی اللہ علیہ وسلم نے ہمیں خبر دار کیا تھا کہ ہم آپ کے بعد “خود غرضی دیکھیں گے”۔ فرمایا: پھر تمہیں کیا حکم دیا؟ فرمایا: “صبر کرنا” یہ کہا تھا۔ امیر معاویہ بولے: تو صبر کرو! حاکم فرماتے ہیں: یہ مرسل روایت ہے، اس واسطے کہ عمارہ نے ابو ایوب کو نہیں دیکھا۔ یہ حدیث بحوالہ ابو ایوب انصاری دوسری سند سے مروی ہے۔ میں کہتا ہوں: شاید بعض راویوں نے ابو ایوب انصاری کو ازدی نسب بنا دیا ہو۔ کیونکہ انصار کا تعلق ازد سے ہے، تابعین میں ابو ایوب ازدی دوسرے ہیں۔ جنہیں مراغی کہا جاتا ہے۔ وہ عبداللہ بن عمرو بن العاص وغیرہ سے روایات لیتے ہیں۔ ان کی مرسل روایت آئی ہے۔ واللہ اعلم!"],[9550,"§۹۵۸۷ ۔ ابو بجیر (بے نسبت)(1)\nابن مندہ نے ان کا تذکرہ کیا ہے اور عثمان بن عبد الرحمن کی سند سے بحوالہ عبداللہ بن بجیر وہ اپنے والد سے وہ اپنے دادا سے نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: قرآن میرے رب کا کلام ہے۔۔۔۔ (حدیث)(2) اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۰) تجرید (۱۵۰/۲)\n(2) کنز العمال (۲۴۷۰) الدر المنثور (۳۲۶/۵) کشف الخفاء (۱۴۰/۲) (۳۴۱/۲) تاریخ بغداد (۳۸۹/۲) جامع المسانید (۳۳۱/۱۳) الجرح والتعدیل (۴۲۵/۱) اسد الغابہ (۳۸۳/۴)"}],[9551,"§۹۵۸۸ ۔ ابو البجیر(1)\nابن الامین نے ان کا استدراک کیا اور اسے ابن فرضی کی جانب مؤتلف میں منسوب کیا ہے، شاید یہ وہ ابن الجیر ہیں جن کا تذکرہ مبہمات میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۷۱۷)"}],[9552,"§۹۵۸۹ ۔ ابو بجیلہ\nذہبی نے تجرید میں بحوالہ یحییٰ بن مخلد ان کا ذکر کیا ہے، مجھے خدشہ ہے کہ یہ نام نون اور حا سے ہے جو آ رہا ہے۔"],[9553,"§۹۵۹۰ ۔ ابو بحر\nدولابی نے کنیتوں میں ان کا ذکر کیا اور عبداللہ بن عمرو بن علقمہ کی سند سے بحوالہ ابو بحر بکراوی نقل کیا، فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا: “جسے اللہ تعالیٰ خوبرو اور خوب مقام بنایا، اس کے والدین نے اس کا برا نام نہ رکھا ہو وہ بروز قیامت اللہ کے خالص بندوں میں سے ہوگا۔”(1) میں کہتا ہوں: مجھے اندیشہ ہے یہ حدیث مرسل نہ ہو۔","",{"fn":"(1) اللالی (۱۹/۱)"}],[9554,"§۹۵۹۱ ۔ ابو بحینہ\nذہبی نے تجرید میں بحوالہ یحییٰ بن مخلد ان کا تذکرہ کیا ہے، میرے خیال میں یہ بحینہ کے بیٹے ہیں جو عبد اللہ ہیں جن کا تذکرہ ہو چکا ہے۔"],[9555,"§۹۵۹۲ ۔ ابو البداح بن عاصم انصاری(1)\nاسماعیل بن اسحاق قاضی نے احکام القرآن میں ذکر کیا ہے کہ یہ معقل بن یسار کی بہن کے خاوند ہیں جن کی وجہ سے یہ آیت “پھر انہیں مت روکو کہ وہ اپنے تجویز کردہ خاوندوں سے نکاح کریں۔”(2) اور ابن جریج کی سند سے یہ روایت بیان کی کہ مجھے عبداللہ بن معقل نے بتایا کہ جمل بنت یسار جو معقل بن یسار کی بہن تھیں وہ ابو البداح کے نکاح میں تھیں، انہوں نے طلاق دی، عدت گزرنے کے بعد پیام دیا، یہ سند صحیح ہے اگر چہ بظاہر مرسل ہے اگر ثابت ہو جائے تو یہ ابو البداح بن عاصم بن عدی کے علاوہ ہیں جن کا ذکر چوتھی قسم میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۷۱۱) تجرید (۱۵۰/۲)\n(2) البقرۃ (۲۳۲)"}],[9556,"§۹۵۹۳ ۔ ابو البراد(1)\nتمیم داری کے غلام۔ مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور محمد بن حسن بن قتیبہ کی سند سے بحوالہ سعید بن زیاد، ابن فائدہ سے وہ اپنے والد سے وہ اپنے دادا سے وہ ابو ہند سے روایت کرتے ہیں کہ تمیم داری شام سے مدینہ اپنے ساتھ قنادیر، تیل اور دھاگے لائے جس دن مدینہ پہنچے تو جمعہ تھا، آپ نے اپنے غلام ابو البراد نامی کو حکم دیا، وہ اٹھا اس نے دھاگے بٹے اور ان سے قنادریلیں لٹکا کر ان میں پانی اور تیل ڈالا، قتیلے رکھے، جو نہی سورج غروب ہوا وہ قندیلیں روشن کر دیں۔ رسول اللہ صلی اللہ علیہ وسلم مسجد آئے تو وہ جگمگا رہی تھی۔ فرمایا: یہ بندوبست کس نے کیا ہے؟ لوگوں نے عرض کیا: یا رسول اللہ! تمیم داری نے۔ آپ صلی اللہ علیہ وسلم نے (خوش ہو کر) فرمایا: “تم نے اسلام (کے مرکز) کو روشن کیا، اللہ تعالیٰ تمہیں دنیا و آخرت میں منور کرے۔ اگر میری کوئی بیٹی ہوتی تو میں اس سے تمہاری شادی کر دیتا۔”(2) نوفل بن حارث بن عبد المطلب بولے: یا رسول اللہ صلی اللہ علیہ وسلم میری ام المغیرہ بنت نوفل نامی بیٹی ہے (اسے اپنی بیٹی سمجھتے ہوئے) اپنی مرضی سے جہاں چاہیں اس کا نکاح کر دیں، تو آپ صلی اللہ علیہ وسلم نے اسی جگہ ان(3) سے ان کا نکاح کر دیا۔ اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۲) تجرید (۱۵۱/۲)\n(2) اسد الغابہ (۳۸۳/۴)\n(3) المستدرک (۲۴۶/۳) اسد الغابہ (۳۸۴/۴)"}],[9557,"§۹۵۹۴ ۔ ابو بردہ بن سعد\nبن حزانہ بن معید بن وہیب بن عمرو بن عائذ بن عمر بن مخزوم، زبیر بن بکار نے ان کا ذکر کیا اور کہا کہ ان کا بیٹا عبد الرحمن جنگ جمل میں شہید ہوا، جو سیدہ عائشہ رضی اللہ عنہا کے لشکر میں تھا۔"],[9558,"§۹۵۹۵ ۔ ابو بردہ بن قیس الاشعری(1)\nابو موسیٰ اشعری رضی اللہ عنہ کے بھائی، اپنے بھائی کی طرح اپنی کنیت سے مشہور ہیں۔ بقول بغوی رحمہ اللہ کوفہ میں رہے۔ ان کی حدیث امام احمد اور حاکم نے عاصم الاحول کی سند سے بحوالہ کریب بن حارث، وہ ابو موسیٰ رضی اللہ عنہ کے بیٹے سے وہ اپنے چچا ابو بردہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! میری اُمت کی ہلاکت اپنی راہ میں قتل اور طاعون میں بنا دے۔”(2) ان کا ایک اور حدیث میں بھی ذکر ہے جو یزید بن عبداللہ کی سند سے بحوالہ ابن ابی بردہ بن ابی موسیٰ، وہ اپنے دادا سے وہ ابو موسیٰ رضی اللہ عنہ سے روایت کرتے ہیں کہ ہم اپنی قوم کے کوئی پچاس سے زائد افراد کے ساتھ سفر میں نکلے، ہم تین بھائی تھے ابو موسیٰ، ابو بردہ، اور ہم(3) تو ہمیں کشتی نے نجاشی تک پہنچا دیا۔ یہ روایت بغوی نے اسی سند سے نکالی ہے پھر ایک اور سند سے بحوالہ کریب بن حارث وہ ابو بردہ بن قیس سے روایت کرتے ہیں، فرمایا: میں نے ابو موسیٰ سے طاعون کے زمانہ میں کہا: ہمیں مال کے کسی حیلے کی طرف لے چلو! تو وہ بولے: میں تو اللہ تعالیٰ کی طرف بھاگتا ہوں نہ کہ حیلے کی طرف۔","",{"fn":"(1) اسد الغابہ (۵۷۱۶) تجرید (۱۵۱/۲)\n(2) مسند احمد (۴۳۷/۳) (۲۳۸/۴) المستدرک (۹۳/۲)\n(3) اسد الغابہ (۳۸۵/۴)"}],[9559,"§۹۵۹۶ ۔ ابو بردہ بن نیار الانصاری(1)\nبراء بن عازب کے ماموں۔ ان کا نام ہانی ہے جو حرف ہاء میں گزر چکا ہے۔ بعض مالک بن ہبیرہ، بعض حارث بن عمرو کہتے ہیں۔ ایسا ہی المزی نے ابن معین سے نقل کیا ہے اور ابن عبد الہادی نے اپنے استدراک میں ان کا ذکر کیا ہے کہ ابن معین نے تو یہ ابن ابی موسیٰ کے بارے میں کہا ہے۔ میں کہتا ہوں: براء کی حدیث میں لکھا ہے: میں اپنے ماموں حارث بن عمرو سے ملا۔ ابو بردہ بن نیار نے خود بتایا کہ وہ براء(2) کے ماموں ہیں۔ یہ اس شخص کا شبہ ہے جو ان کا نام حارث بتاتا ہے ہو سکتا ہے وہ براء کے دوسرے ماموں ہوں۔ واللہ اعلم۔ (لیکن) پہلا قول زیادہ صحیح ہے۔ بعض کہتے ہیں: وہ براء کے چچا ہیں (مگر) پہلا قول (ماموں ہونے کا) زیادہ مشہور ہے۔ ابو بردہ بدر اور بعد کے واقعات میں شریک رہے وہ نبی صلی اللہ علیہ وسلم سے اور ان سے براء بن عازب، جابر بن عبداللہ، اور ان کے بیٹے عبد الرحمن بن جابر، کعب بن عمیر بن عقبہ بن نیار، نصر بن بیار نے روایت کی ہے۔ جو لوگ ان کا نام حارث بتاتے ہیں اس کا سبب یہ ہے کہ براء رضی اللہ عنہ نے کہا: میں اپنے ماموں حارث بن عمرو سے ملا۔ لیکن احتمال ہے ان کے کوئی اور ماموں ہوں یہی زیادہ مناسب ہے۔ مزی نے عباس دوری سے بحوالہ ابن معین نقل کیا انہوں نے روایت کی کہ ابو بردہ بن نیار کا نام “حارث” ہے۔ ان کا تعاقب کر کے کہا گیا کہ ابن معین کا یہ قول ابو بردہ بن ابی موسیٰ کے متعلق ہے۔ بقول ابو عمر: خلافت معاویہ کے ابتدائی دور میں فوت ہوئے۔ اس سے پہلے سیدنا علی رضی اللہ عنہ کے ساتھ تمام مہمات میں شریک رہ چکے تھے۔ بقول بعض ان کا انتقال اکتالیس بقول بعض بیالیس اور ایک قول کے مطابق پینتالیس ہجری میں ہوا۔","",{"fn":"(1) اسد الغابہ (۵۷۱۷) تجرید اسماء الصحابۃ (۱۵۱/۲)\n(2) اسد الغابہ (۳۸۵/۴)"}],[9560,"§۹۵۹۷ ۔ ابو بردہ جمیع بن عمیر کے ماموں(1)\nشریک نے وائل بن داؤد سے بحوالہ جمیع وہ اپنے ماموں ابو بردہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: آدمی کی سب سے فضیلت والی کمائی اس کی اولاد ہے اور ہر (جائز) سودا (عند اللہ) مقبول ہے۔(2) اس روایت کو بغوی نے یحییٰ الحمانی سے بحوالہ شریک روایت کیا ہے۔ بحوالہ شریک کئی لوگوں نے ان کی متابعت کی ہے ثوری فرماتے ہیں: سند یوں ہے، وائل سے وہ سعید بن عمیر سے وہ اپنے چچا سے، یہ ابن مندہ نے نقل کی ہے۔ میں کہتا ہوں: سعید بن عمیر کا نام ابن عقبہ بن نیار ہے اس لحاظ سے ان کے چچا ابو بردہ بن نیار ہوئے برخلاف جمیع کے مجھے معلوم نہیں آیا وہ ایک شخص ہے جس کے نام میں اختلاف ہے یا دو شخصیتیں ہیں؟","",{"fn":"(1) اسد الغابہ (۵۷۱۴) تجرید (۱۵۱/۲)\n(2) مسند احمد (۴۶۶/۳) المستدرک (۱۰/۲) المعجم الکبیر (۵۱۹/۲۲، ۵۲۰) السلسلۃ الصحیحۃ (۶۰۷) مجمع الزوائد (۴۔۔۔۔۔۶۰) (۱۵۴/۴) کنز العمال (۹۲۲۶) جمع الجوامع (۳۷۸۰)"}],[9561,"§۹۵۹۸ ۔ ابو بردہ الاسلمی\nثعلبی نے اپنی تفسیر میں ان کا تذکرہ کیا کہ نبی صلی اللہ علیہ وسلم نے انہیں اسلام کی دعوت دی تو انہوں نے نہ مانی۔ بعد میں ان کے بیٹوں نے ان سے گفتگو کی تو وہ مان گئے۔ اور اسلام لے آئے۔ طبرانی میں ایک بہترین سند سے بحوالہ ابن عباس رضی اللہ عنہما مروی ہے فرمایا: ابو بردہ الاسلمی کاہن تھے یہودی لوگوں کے درمیان فیصلے کرتے تھے پھر اللہ تعالیٰ کے ارشاد “اے نبی! کیا آپ نے ان لوگوں کا حال دیکھا جو دعویٰ تو یہ کرتے ہیں کہ ان کا تم پر نازل شدہ اور تم سے پہلے نازل کردہ کتابوں پر ایمان ہے مگر چاہتے یہ ہیں کہ اپنے معاملات کا فیصلہ طاغوت کے پاس کرانے جائیں۔”(1)","",{"fn":"(1) سورۃ النساء: ۶۰"}],[9562,"§۹۵۹۹ ۔ ابو بردہ ظفری انصاری اوسی(1)\nابن سعد نے مصر فروکش ہونے والوں میں ان کا تذکرہ کیا ہے۔ بقول ابو نعیم ان کا شمار کوفیوں میں ہوتا ہے۔ بغوی اور امام احمد کے ہاں عبد اللہ بن معتب بن ابی بردہ ظفری کی سند سے بحوالہ ان کے والد وہ اپنے دادا سے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: کاہنوں میں سے ایک شخص مسلمان ہو کر قرآن کو ٹھیک انداز سے ایسے پڑھے گا کہ پھر اس جیسا (خاص انداز لے کر) اس کے بعد کوئی نہیں پڑھے گا۔(2) یہ روایت امام احمد اور ابن خیثمہ وغیرہ نے ابن وہب کی سند سے عمرو بن الحارث سے بحوالہ ابو سحر نقل کی ہے اور ابن مندہ نے نافع بن یزید کی سند سے بحوالہ ابو مسخر روایت کی ہے۔ تنبیہ ☆ اکثر علماء کے نزدیک لفظ مُعتب میم کے پیش عین کے زبر، تائے مشددہ زیر والی آخر میں ب ہے۔ جبکہ ابو عمر نے کہا ہے عین کا زیر پھر یا ساکن آخر میں طاء ہے۔ ابن فتحون فرماتے ہیں: میں نے ابن مفرح کی اصل کتاب بزار میں یہ لفظ معتب اسی جیسا لکھا دیکھا لیکن وہ معین اور باء سے ہے۔ بزار ابن السکن اور باوردی وغیرہ کا اس پر اتفاق ہے کہ عبد اللہ مکبر لفظ ہے جبکہ ابو عمر کے ہاں عبید اللہ مصغر لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۱۵) تجرید (۱۵۱/۲)\n(2) مسند احمد (۱۰/۶) المعجم الکبیر (۵۱۸/۲۲) (۷۹۴/۲۲) مجمع الزوائد (۱۶۷/۷)"}],[9563,"§۹۶۰۰ ۔ ابو برزہ الاسلمی(1)\nشہرت یافتہ شخصیت ہے ان کا نام “نضلہ بن عبید” ہی صحیح ہے بعض ابن عبد اللہ بعض ابن عائذ اور بعض عبد اللہ بن نضلہ کہتے ہیں۔(2) اسے واقدی نے اپنے مسودے سے نقل کیا ہے بعض کے نزدیک تصغیر سے ہے۔ ہیشم بن عدی نے کہا خالد بن نضلہ، نون میں گزر گیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۱۹) تجرید (۱۵۱/۲)\n(2) مسند احمد (۴۱۹/۴)"}],[9564,"§۹۶۰۱ ۔ ابو برقان السعدی(1)\nنبی صلی اللہ علیہ وسلم کے رضاعی چچا۔ ابو موسیٰ فرماتے ہیں: مستغفری نے ان کا تذکرہ کیا ہے اور محمد بن معن سے بحوالہ عیسیٰ بن یزید نقل کیا ہے فرماتے ہیں: نبی صلی اللہ علیہ وسلم کے (رضاعی) چچا ابو برقان جو بنی سعد بن بکر سے تعلق رکھتے تھے آ کر کہنے لگے: اے محمد! (صلی اللہ علیہ وسلم) تیری قوم کو تجھ سے زیادہ کوئی نوجوان محبوب نہیں اور نہ تجھ سے بڑھ کر کوئی قابل تعریف ہے۔ جبکہ یہ سب کچھ لے لیتے ہیں۔ آپ نے فرمایا: ابو برقان! کیا تمہیں مقام حیرہ معلوم ہے؟ انہوں نے کہا: میں نے عرض کیا: جی ہاں، فرمایا: اگر تمہاری زندگی لمبی ہوئی تو اس کے متعلق تم ضرور سنو گے کہ مسافر وہاں سے بغیر کسی حفاظت کے گزرے گا وہ کہنے لگے: میں نہیں جانتا آپ کیا کہنا چاہتے ہیں۔ میں ابھی فلاں مقام سے پہرے دار کو ساتھ لے کر گزرا ہوں۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں قیامت کے دن ضرور تمہارا ہاتھ پکڑ کر تمہیں یہ بات یاد دلاؤں گا۔”(2) سیدنا عثمان بن عفان رضی اللہ عنہ ابو برقان سے فرماتے حضور تمہارا ہاتھ اس لیے پکڑیں گے کہ تم نیک آدمی ہو۔ ابو برقان فرماتے ہیں: بعد میں میرا حیرہ سے گزر ہوا تو میں نے اسے ویسا ہی پایا جیسا کہ مجھ سے بیان کیا گیا تھا۔(3) میں کہتا ہوں: عیسیٰ بن یزید وہی ہیں جو “ابن داب اخباری” سے مشہور ہیں۔ ناقدین نے ان کی تکذیب کی ہے اس کنیت میں لفظی غلطی ہوئی ہے جیسا کہ ثاء میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۷۲۰) تجرید (۱۵۱/۲)\n(2) جامع المسانید (۳۶۲/۱۳) اسد الغابہ (۳۸۶/۴)\n(3) التاریخ الکبیر (۴۰۲/۳) الجرح والتعدیل (۲۹۱/۳) میزان الاعتدال (۳۲۸/۳) جامع المسانید (۱۳۔۔۔۔۳۶۲) اسد الغابہ (۳۸۷/۴)"}],[9565,"§۹۶۰۲ ۔ ابو بریدہ\nعمرو بن سلمہ جرمی، اسماء میں تذکرہ ہو گیا ہے۔"],[9566,"§۹۶۰۳ ۔ ابو برّہ المکی المخزومی(1)\nبن مخزوم کے غلام ہیں۔ ابن قانع نے ان کا تذکرہ کیا اور امام بخاری سے نقل کیا ہے کہ ان کا نام سیار تھا۔ ابن قانع اور ابو الشیخ دونوں فرماتے ہیں: ہمیں ابو خبیب (خاء نقطے والی پھر باء اور یاء تصغیر والیاں البرتی باء کے زیر، راء ساکن اس کے بعد تا) نے بحوالہ احمد بن ابی ہرہ بتایا۔ وہ ابن محمد بن قاسم بن ابی برہ ہیں۔ فرمایا: مجھ سے میرے والد نے بحوالہ میرے دادا ابو برہ کے نقل کیا، فرمایا: “میں اپنے آقا عبد اللہ بن سائب کے ساتھ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ میں نے آپ کے ہاتھ، سر اور پاؤں پر بوسہ دیا۔”(2) یہ روایت ابو بکر بن المقری نے “ہاتھ چومنے کی رخصت” نامی رسالے میں نقل کی ہے۔ جو بحوالہ ابو الشیخ ہے۔ ابو موسیٰ نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۲۱) تجرید (۱۵۱/۲)\n(2) جامع المسانید (۳۶۳/۱۳) اسد الغابہ (۳۸۷/۴)"}],[9567,"§۹۶۰۴ ۔ ابو بشار یا یسار\nکنیتوں کے آخری حرف یاء میں تذکرہ آئے گا۔"],[9568,"§۹۶۰۵ ۔ ابو البشر(1)\nابن الحارث العبدری از بنی عبد الدار، محمد بن وضاح فرماتے ہیں: یہ وہ نوجوان ہیں جنہوں نے سبیعہ اسلمیہ کو اس وقت نکاح کا پیغام دیا جب ان کے ہاں بچے کی ولادت ہو چکی تھی۔ تو ان کا میلان ہو گیا (مائل ہوئیں)۔(2) اتنے میں ابو سنابل ان کے پاس آ کر کہنے لگے: جب تک چار ماہ دس دن نہیں گزر جاتے میں نکاح نہیں کرنے کا۔ ابن دباغ اور ابن فتحون نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۲۲) تجرید (۱۵۱/۲)\n(2) اسد الغابہ (۳۸۷/۴)"}],[9569,"§۹۶۰۶ ۔ ابو بشر انصاری\nابن ابی خیثمہ نے ان کا ذکر کیا اور مخرمہ بن بکیر کی سند سے بحوالہ ان کے والد، وہ سعید بن نافع سے روایت کرتے ہیں۔ مجھے ابو البشر صحابی رسول نے دیکھا کہ میں سورج طلوع ہو چکنے کے بعد نماز پڑھ رہا تھا، انہوں نے اس پر مجھے ڈانٹا اور فرمایا: رسول اللہ صلی اللہ علیہ وسلم کا ارشاد ہے: “جب سورج بلند ہونے لگے اس وقت کوئی نماز نہ پڑھا کرو، اس واسطے کہ وہ شیطان کے دو سینگوں میں طلوع ہوتا ہے۔”(1) ابن ابی خیثمہ نے ان میں اور ابو بشر انصاری میں فرق کیا ہے جن کی حدیث صحیحین میں آتی ہے۔ تو یہ نام ایسا ہے کہ اس کے شروع میں زیر پھر سکون ہے۔ اور جو آئندہ والا ہے اس میں زبر پھر زیر ہے (یعنی بَشِر ہے)۔ ابن عبد البر نے دونوں کو ایک کر دیا ہے اور کہا: یہ وہی ہیں جن سے عمارہ بن غزیہ یہ حدیث نقل کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے مدینہ کے دونوں پہاڑوں کے درمیانی علاقہ کو حرام قرار دیا، اور فرماتے ہیں ان کی یہ بھی حدیث ہے: “بخار جہنم کی گرمی ہے”۔ راجح دونوں میں فرق ہی ہے۔","",{"fn":"(1) مسند احمد (۲۱۶/۵) کنز العمال (۱۹۶۱۸) المطالب العالیہ (۳۰۴)"}],[9570,"§۹۶۰۷ ۔ ابو بشر خثعمی\nان کی بقی بن مخلد کی مسند میں ایک حدیث ہے۔"],[9571,"§۹۶۰۸ ۔ ابو بشر\nبراء بن معرور، انصار کے سردار، ناموں میں تذکرہ ہو چکا ہے۔"],[9572,"§۹۶۰۹ ۔ ابو بشر سلمی(1)\nذیل میں ابو موسیٰ نے ان کا استدراک کیا ہے کہ ابو بکر بن علی وغیرہ نے انہیں صحابہ رضی اللہ عنہم میں ذکر کیا ہے اور ہشام بن سعد کی سند سے بحوالہ زید بن اسلم، ابو بشر سلمی سے روایت کرتے ہیں، جو صحابی رسول صلی اللہ علیہ وسلم تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس کی خواہش ہو کہ اس کی مشکل حل جائے اور اس کی دُعا قبول ہو اسے چاہیے کہ وہ تنگدست (قرضدار) کو مہلت دے دے یا معاف کر دے۔”(2) ابو موسیٰ فرماتے ہیں: شاید وہ ابو الیسر ہیں یاء اور سین کے زبر سے، ان کا نام کعب بن عمرو ہے، کیونکہ یہ متن انہی سے مشہور ہے۔ میں کہتا ہوں: لیکن دونوں حدیثوں کا مآخذ مختلف ہے اور مآخذ میں کثرت ہو تو یہ راویوں کی کثرت کی دلیل ہے، برخلاف اس صورت کے جب مآخذ ایک ہو اور اس میں کوئی مانع نہیں کہ ایک حکم کو دو صحابیوں سے روایت کیا جائے۔ سیاق کا اختلاف کثرت کی دلیل ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۷۲۳) تجرید (۱۵۱/۲)\n(2) ابن ماجہ کتاب الصدقات باب اظہار المعسر (۲۴۱۹) مجمع الزوائد (۱۳۴/۴) مسند احمد (۴۲۷/۳) کنز العمال (۱۵۴۱۷) المعجم الکبیر (۳۷۶/۱۹) (۳۷۷/۱۹) جامع المسانید (۳۶۴/۱۳)"}],[9573,"§۹۶۱۰ ۔ ابو بشیر انصاری الساعدی(1)\nمازنی، اور حارثی بھی کہا جاتا ہے۔ صحیحین میں ان کی حدیث عباد بن تمیم کی سند سے بحوالہ ان کے مروی ہے، حدیث کا متن ہے: “قلادہ کے علاوہ کوئی چیز ہرگز (جانور کی) گردن میں نہ چھوڑی جائے۔”(2) ضمرہ بن سعید اور سعید بن نافع بھی ان سے روایت کرتے ہیں۔ ابو احمد حاکم نے ان لوگوں میں ان کا تذکرہ کیا جن کا نام معروف نہیں۔ بقول بعض ان کا نام قیس بن عبید بن الحریر (حاء راہ سے تصغیر) ہے جسے طبری وغیرہ نے قلمبند کیا ہے۔ ابو عمر کے ہاں “حارث” لکھا ہے۔(3) بقول محمد بن سعد وہ عبید بن حارث بن عمرو بن جعد ہیں۔ واقدی سے منقول ہے: وہ لڑکپن میں اُحد میں شریک ہوئے۔ اور ابن سعد نے غزوہ خندق کے شرکاء کے طبقہ میں ان کا نام درج کیا ہے۔ بغوی نے ان کا ذکر کیا کہ وہ ابو بشیر انصاری مدینہ میں رہائش پذیر تھے، اسی سند سے ان کی حدیث نقل کی ہے۔ خلیفہ لکھتے ہیں: ابو بشیر حرہ کے بعد فوت ہوئے۔ انہوں نے لمبی عمر پائی۔ بقول بعض: ۴۰ ھ میں فوت ہوئے۔ نسباً وہ ساعدی ہیں۔ انہیں مازنی، حارثی بھی کہا جاتا ہے۔ ضمرہ بن سعید، اور سعید بن نافع ان سے روایت لیتے ہیں۔ لوگ کہتے ہیں کہ اس کا یہ آخری بوڑھا ہے جس کی کنیت ابو بشر ہے، یہ ابن ابی خیثمہ کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۲۴) تجرید (۱۵۸/۲)\n(2) بخاری کتاب الجہاد والسیر باب ما قیل فی الجرس و نحوہ فی اعناق الابل (۳۰۰۵) مسلم کتاب اللباس والزینۃ باب کراہیۃ قلادۃ الوتر فی رقبۃ البعیر (۵۵۱۵)\n(3) الاکمال (۱۳۱/۱)"}],[9574,"§۹۶۱۱ ۔ ابو بشیر انصاری\nیہ اور ہیں۔ حارث بن خزیمہ نام ہے، ناموں میں تذکرہ ہو چکا ہے۔"],[9575,"§۹۶۱۲ ۔ ابو بشیر (کسی قبیلہ سے منسوب نہیں)\nابن فتحون نے بحوالہ طبری ان کا استدراک کیا اور ان کی روایت نقل کی۔ جو شعبہ کی سند سے، حبیب مولی انصار سے مروی ہے، فرمایا: میں نے ابن ابی بشر اور ابن ابی بشیر سے سنا، دونوں اپنے اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “بخار جہنم کی گرمی ہے اسے پانی سے ٹھنڈا کر لیا کرو”۔(1) میں کہتا ہوں: یہ پہلے گزر چکا ہے کہ ابو عمر نے اس پر یقین کا اظہار کیا ہے کہ یہ پہلے والی شخصیت ہے۔ لہذا غیر کے احتمال کے باوجود اس پر استدراک درست نہیں۔ بغوی نے ابو جندل بن سہیل کے سوانح میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اخرجہ الامام احمد فی مسندہ حدیث (۲۱۶/۳)"}],[9576,"§۹۶۱۳ ۔ ابو البشیر انصاری\nبقول بعض یہ کعب بن مالک کی کنیت ہے۔ ابن ماکولا(1) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) الاکمال (۶۲/۱)"}],[9577,"§۹۶۱۴ ۔ ابو البشیر(1)\nپہلے کی طرح شروع میں الف لام کا اضافہ ہے، رسول اللہ صلی اللہ علیہ وسلم کے غلام۔ ابو موسیٰ نے بحوالہ مستغفری ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۹۷۲۵) تجرید (۱۵۲/۲)"}],[9578,"§۹۶۱۵ ۔ ابو البشیر المعاوی(1)\nبزار نے ان کا تذکرہ اور ابن الامین نے استدراک کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۲) تجرید (۱۵۲/۲)"}],[9579,"§۹۶۱۶ ۔ ابو بصرہ غفاری(1)\nابن بصرہ بن ابی بصرہ بن وقاص بن حبیب بن غفار اور بقول بعض: ابن حاجب بن غفار۔ وہ نبی صلی اللہ علیہ وسلم سے اور ان سے ابو ہریرہ رضی اللہ عنہ، ابو تمیم جیشانی عبد اللہ بن ہبیرہ، عبید بن جبر، اور ابو الخیر یزنی وغیرہ روایت کرتے ہیں۔ ان کی حدیث مسلم اور نسائی نے ابن اسحاق کے طریق سے، بحوالہ یزید بن ابی حبیب، جبیر بن نعیم سے انہوں نے عبد اللہ بن ہبیرہ سے وہ ابو تمیم جیشانی سے انہوں نے سیدنا ابو بصرہ غفاری رضی اللہ عنہ سے نقل کی فرمایا: “ہمیں رسول اللہ صلی اللہ علیہ وسلم نے عصر کی نماز پڑھائی”۔ (الحدیث) اسی میں ہے: “جب تک شاہد یعنی ستارہ دکھائی نہ دے کوئی نماز نہیں۔”(2) نسائی نے کلیب بن دہل کے طریق سے بحوالہ عبید بن جبر نقل کیا ہے۔ فرماتے ہیں: میں رمضان میں صحابی رسول ابو بصرہ کے ساتھ تھا، پھر انہوں نے سفر میں روزہ نہ رکھنے کا ذکر کیا۔ ابن یونس فرماتے ہیں: فتح مصر میں شریک ہوئے وہیں ان کی حویلی ہے وفات وہیں ہوئی اور مصر کے مقبرہ میں دفن ہوئے۔ ابو عمر: حجاز میں رہتے تھے، منتقل ہو گئے۔ بقول بعض: عزہ کثیر کی محبوبہ ان کی اولاد سے ہے، اس کی طرف کثیر نے اپنے حاجبیہ میں اشارہ کیا ہے۔ جبکہ ابن الاثیر نے اس کا انکار کرتے لکھا ہے: عزہ کے نسب میں ابو بصرہ کا کوئی تذکرہ نہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۲۵) تجرید ایضاً\n(2) مسلم کتاب صلاۃ المسافرین باب الاوقات التی نہی عن الصلاۃ فیہا (حدیث: ۱۹۲۴) نسائی کتاب المواقیت باب تاخیر المغرب (حدیث: ۵۲۰)"}],[9580,"§۹۶۱۷ ۔ ابو بصرہ الغفاری(1)\nسابقہ شخصیت کے دادا، ان کے پوتے کے حالات میں ان کا ذکر ہو چکا ہے کہ انہیں ان کے والد اور دادا کو شرف صحابیت حاصل ہے۔","",{"fn":"(1) تجرید (۱۵۲/۲)"}],[9581,"§۹۶۱۸ ۔ ابو بصیر بن اسید(1)\nبن جاریہ ثقفی، ان کا نام عتبہ پہلے تذکرہ ہوا ہے۔ بقول بعض: نام عبید ہے جسے ابن عبد البر نے بھی نقل کیا ہے، جبکہ پہلا نام ہی مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۴) استیعاب (۲۹۱۵)"}],[9582,"§۹۶۱۹ ۔ ابو بصیر (دوسرے)\nابو غسل کے سوانح میں تین نقطے والی میں ذکر آئے گا۔"],[9583,"§۹۶۲۰ ۔ ابو بصیرہ(1)\nابو عمر۔ سیف بن عمر نے یمامہ میں شریک انصاریوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۲۸) استیعاب (۲۹۱۵) تجرید (۱۵۲/۲)"}],[9584,"§۹۶۲۱ ۔ ابو بکر الصدیق بن ابی قحافہ(1)\nنام عبد اللہ، بقول بعض عتیق بن عثمان تھا، ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۷) استیعاب (۲۹۱۷)"}],[9585,"§۹۶۲۲ ۔ ابو بکر بن شعوب اللیثی\nنام شداد، بقول بعض: اسود، شداد بن اسود ہے، اس پر علماء کا اتفاق ہے کہ شعوب ان کی والدہ ہیں، انہی کے متعلق جب جنگ اُحد میں ابو سفیان بن حرب نے ان کی مدافعت کی تو کہا تھا: “اگر میں چاہتا تو مجھے دھاری داری تیز رفتار گھوڑا بچا لیتا، اور میں ابن شعوب کی اونٹنی پر سوار نہیں ہوا”۔ جعونہ نامی ان کا ایک بھائی بھی ہے جن کا تذکرہ جیم میں گزر گیا ہے۔ نوادر مجموعہ میں جرمی نے ایک واقعہ نقل کیا ہے اور میں نے بھی انہی کے قلم سے صحیح سند کے ذریعہ بحوالہ ابو عبید ان لوگوں کے حالات میں نقل کیا ہے جو اپنی والدہ کی طرف منسوب ہوئے۔ ابو بکر بن شعوب اپنی والدہ کی نسبت سے مشہور ہیں جبکہ ان کے والد کا تعلق بنی لیث بن بکر بن کنانہ سے ہے وہی یہ اشعار کہتے ہیں پھر مشرکین بدر کے مقتولین کے بارے مرثیہ کے اشعار ذکر کیے۔ فرماتے ہیں: بعد میں ابن شعوب اسلام لے آئے تھے۔ مرزبانی: ان کی والدہ شعوب خزاعیہ تھیں۔ ان کے علاوہ علماء کا کہنا ہے کہ کنانیہ تھیں۔ بخاری میں لکھا ہے: کلبیہ تھیں، چنانچہ یونس کے طریق سے بحوالہ زہری، عروہ وہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں کہ سیدنا ابو بکر نے ایک کلبی خاتون سے شادی کی جس کا نام ام بکر تھا۔ جب سیدنا ابو بکر رضی اللہ عنہ نے ہجرت کی تو اسے طلاق دے گئے تو اس سے اس کے چچا زاد اسی شاعر نے شادی کر لی جو کفار قریش کے مرثیہ میں ایک قصیدہ کہتا ہے: “قلیب بدر کے اس کنویں میں کیا ہے؟” اسماعیلی نے احمد بن صالح کے طریق سے بحوالہ وہب، ابن یونس سے نقل کیا تو از کلب نہیں کہا۔ بلکہ یہ اضافہ کیا ہے: سیدہ عائشہ رضی اللہ عنہا فرمایا کرتی تھیں، ابو بکر رضی اللہ عنہ نے نہ جاہلیت میں اشعار کہے اور نہ اسلام میں۔ حکیم ترمذی نے نوادر الاصول میں زبیدی کے طریق سے بحوالہ زہری عروہ سے وہ سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں کہ آپ اس شخص کے لیے بددعا کیا کرتی تھیں جو یہ کہتا کہ ابو بکر رضی اللہ عنہ نے یہ قصیدہ کہا ہے۔ اللہ کی قسم! ابو بکر رضی اللہ عنہ نے نہ جاہلیت میں اور نہ اسلام میں ایک شعر بھی نہیں کہا۔ واقعہ یہ ہے کہ انہوں نے بنی کنانہ پھر بنی عوف کی ایک خاتون سے شادی کی تھی اور ہجرت کے وقت اسے طلاق دے دی، جس سے اس عورت کے چچا زاد اس شاعر نے شادی کر لی تھی، اسی نے کفار قریش کے بارے میں ایک مرثیہ کہا تھا جو بدر میں مارے گئے تھے۔ جس عورت کو سیدنا ابو بکر رضی اللہ عنہ نے طلاق دی تھی اس کی وجہ سے لوگوں نے ابو بکر رضی اللہ عنہ سے دشمنی رکھ لی حالانکہ وہ تو ابو بکر بن شعوب تھا۔ میں کہتا ہوں: سیدہ عائشہ رضی اللہ عنہا کا اشارہ اس حدیث کی طرف ہے جو فاکہی نے کتاب مکہ میں یحییٰ بن جعفر سے بحوالہ علی بن عاصم، عوف بن ابی جمیلہ سے انہوں نے ابو القموص سے روایت کی ہے کہ ابو بکر رضی اللہ عنہ نے زمانہ جاہلیت میں شراب پی لی اور یہ اشعار کہنے لگے۔ پھر وہ اشعار ذکر کیے۔ نبی صلی اللہ علیہ وسلم کو پتہ چلا آپ اپنا تہبند گھسیٹتے کھڑے ہوئے یہاں تک کہ گھر میں داخل ہوئے آپ کے ساتھ ابو بکر رضی اللہ عنہ بھی تھے سیدنا عمر رضی اللہ عنہ سے ملاقات ہو گئی۔ آپ نے دیکھا کہ نبی صلی اللہ علیہ وسلم کا چہرہ غصہ سے سرخ ہو رہا ہے۔ کہنے لگے: ہم رسول اللہ صلی اللہ علیہ وسلم کے غصہ سے اللہ کی پناہ مانگتے ہیں۔ اللہ کی قسم! یہ کبھی ہمارے سر میں داخل نہیں ہوگی (یعنی شراب نہیں پیوں گا جس سے دماغ پر اثر پڑتا ہے) چنانچہ سب سے پہلے انہوں نے اپنے لیے شراب حرام کر لی۔ نفطویہ نے اس روایت پر اعتماد کر کے لکھا ہے کہ ابو بکر رضی اللہ عنہ نے شراب کی حرمت سے پہلے شراب پی تھی۔ اور مشرکین کے بدر میں مارے گئے لوگوں کا مرثیہ کہا تھا۔ رہی وہ روایت جو بزار نے بحوالہ ابو کریب اور جنادہ نے بحوالہ یونس بن بکیر، مطر بن میمون سے نقل کی کہ ہم سے انس بن مالک رضی اللہ عنہ نے بیان کیا کہ میں لوگوں کو شراب پلا رہا تھا، ان میں بنی کنانہ کا ابو بکر نامی ایک شخص تھا جب اس نے پی لی تو کہنے لگا: “ام بکر! سلام بھیج! کیا تیری قوم کے بعد بھی مجھے سلام پہنچ سکتا ہے۔ ہم سے رسول (صلی اللہ علیہ وسلم) بیان کرتا ہے کہ ہم زندہ ہوں گے، انسانی لاشوں اور کھوپڑیوں کی کیسی زندگی؟” فرمایا: یوں شراب کی حرمت نازل ہوئی، پھر وہ حدیث ذکر کی۔ اسی میں برتن توڑنے اور ان میں پڑی شراب بہانے کا ذکر ہے۔ ابن فتحون فرماتے ہیں: یہ اشعار ابو بکر شداد بن اسود بن شعوب کے ہیں، جو اس قصیدے میں سے ہیں جس میں مقتولین بدر کا مرثیہ کہا ہے۔ شاید ابو بکر کنانی نے نشے کی حالت میں انہیں کہہ دیا ہو۔ میں کہتا ہوں: ابن فتحون سے یہ بات مخفی رہ گئی کہ ابو بکر بن شعوب ہی ابو بکر کنانی ہیں، جن کے متعلق انہوں نے گمان ظاہر کیا کہ وہ مسلم تھے اور ابن شعوب اسلام نہیں لائے، اسی بنا پر اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن ہشام نے زیادات “سیرۃ” میں ذکر کیا ہے کہ ابن شعوب اسلام لائے پھر مرتد ہو گئے۔ واللہ اعلم!"],[9586,"§۹۶۲۳ ۔ ابو بکر الثقفی\nنفیع بن حارث، جن کا ذکر پہلے ہو چکا ہے۔"],[9587,"§۹۶۲۴ ۔ ابو البنات\nابو سفیان میں ذکر آئے گا۔"],[9588,"§۹۶۲۵ ۔ ابو بھیسہ فزاری(1)\nالکنی میں ابو بشر دولابی نے ان کا ذکر کیا اور کھمس کے طریق سے بحوالہ یار بن منظور، ابو بھیسہ سے نقل کیا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے اندر آنے کی اجازت طلب کی، وہاں پہنچنے کے بعد انہوں نے آپ صلی اللہ علیہ وسلم کی قمیص میں ہاتھ ڈالا اور مہر نبوت کو چھوا۔(2) انہوں نے اسی طرح نقل کیا، یہی روایت ابو داؤد اور نسائی میں اسی سند سے مروی ہے لیکن انہوں نے کہا: بھیہ (خاتون) سے بحوالہ ان کے والد مروی ہے کہ انہوں نے اجازت طلب کی۔ ابن مندہ نے اسے نقل کیا ہے، لیکن فرماتے ہیں: بیار سے بحوالہ ان کے والد وہ بھیسہ سے فرماتی ہیں: میرے والد نے نبی صلی اللہ علیہ وسلم سے آپ کی قمیض میں ہاتھ ڈالنے کی اجازت چاہی۔ (الحدیث) ابن عبد البر نے ذکر کیا ہے کہ بھیہ کے والد کا نام عمیر ہے جو عین میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۲) تجرید (۱۵۲/۲)\n(2) ابو داؤد، کتاب الزکوۃ، باب ما لا یجوز منعہ (حدیث: ۱۶۶۹) کتاب الاجارۃ باب فضل الماء و اثمان الکلاب (حدیث: ۳۴۷۶) مسند احمد (۴۸۰/۳) السنن الکبریٰ (حدیث: (۱۵۰/۶) المعجم الکبیر (۱۷۸۹/۲۲)"}],[9589,"§۹۶۲۶ ۔ ابو بھیسہ البکری(1)\nنام عبد اللہ بن حرب، تذکرہ ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۰)"}],[9590,"§۹۶۲۷ ۔ ابو بحریہ التراغمی\nکنیت سے مشہور ہیں۔ نام عبد اللہ بن قیس، ناموں میں ذکر ہو چکا ہے۔ جس بات سے اس کی تائید ہوتی ہے کہ انہوں نے دور جاہلیت پایا ہے وہ روایت ہے جسے ابن المبارک نے کتاب الجہاد میں ابو بکر بن عبد اللہ بن حویطب کے طریق سے بحوالہ ابو بحریہ نقل کیا ہے کہ فرمایا: میں اس لشکر یا سریے میں تھا جو سب سے پہلے سرزمین روم میں داخل ہوا۔ اور تمہارا چچا زاد عبد اللہ بن سعدی ہم پر غالب رہا، اس نے سیدنا عمر رضی اللہ عنہ کے دور میں کہا: “ہمارے قدم ہمارے جوتے ہیں۔” جس سے پتہ چلتا ہے کہ ہجرت کے تیرھویں سال کا واقعہ ہے۔"],[9591,"§۹۶۲۸ ۔ ابو بسرہ الجہنی\nفرماتے ہیں: میں جابیہ میں سیدنا عمر رضی اللہ عنہ کے پاس تھا، آپ کے پاس ایک شخص لایا گیا جو شراب پی کر نشے میں ہو گیا تھا، آپ نے اس پر حد خمر جاری کی۔ ابن عساکر نے ان کا ذکر کیا ہے۔"],[9592,"§۹۶۲۹ ۔ ابو بصیرہ الیشکری\nدور نبوت پایا ہے۔ ابو الفرج اصبہانی: مسیلمہ کذاب کے پاس ابو بصیرہ لائے گئے، اس نے اس کے سر پر ہاتھ پھیرا تو یہ نابینے ہو گئے۔ ابو بصیرہ مذکور خالد قشیری کی عراق پر حکومت کے دور تک زندہ رہے۔"],[9593,"§۹۶۳۰ ۔ ابو بکر العنسی\nفرماتے ہیں: میں سیدنا عمر رضی اللہ عنہ کے ہمراہ صدقہ کے باغ میں داخل ہوا۔"],[9594,"§۹۶۳۱ ۔ ابو بجیلہ\nابو الخیر اور ابو حسینہ۔ قسم اول میں سب کا ذکر ہو چکا ہے۔ ویسے ان کا ذکر مبہمات میں ہونا چاہیے۔"],[9595,"§۹۶۳۲ ۔ ابو البداح بن عاصم(1)\nبن عدی ابن الجعد بن عجلان البلوی، انصار کے حلیف۔ ابو عمر: ان کے متعلق اختلاف ہے۔ بقول بعض: ان کے والد صحابی ہیں اور یہ تابعی ہیں۔ کسی نے کہا: یہ صحابی ہیں۔ یہ وہی ہیں جو سبیعہ اسلمی کو بیوہ چھوڑ مرے تھے، جنہیں ابو سنابل بن بعکک نے پیام نکاح بھیجا تھا، ابن جریج وغیرہ نے ان کا ذکر کیا ہے۔ یہی صحیح ہے کہ وہ صحابی نہیں اکثر لوگوں نے انہیں صحابہ میں ذکر کیا ہے۔ اس بات پر چند اعتراضات ہیں۔ اوّل: امام مالک نے موطا میں عبد اللہ بن ابی بکر بن محمد بن عمرو بن حزم سے بحوالہ ان کے والد انہوں نے ابو البداح سے ایک حدیث نقل کی ہے۔ اس سے پتہ چلتا ہے کہ ابو البداح کا زمانہ نبی صلی اللہ علیہ وسلم سے بعد کا ہے۔ اس لیے کہ ابو بکر بن محمد بن عمرو بن حزم نے زمانہ نبوی نہیں پایا ہے۔ ابو البداح سے ابو بکر بن عبد الرحمن بن حارث بن ہشام اور ان کے بیٹے عبد الملک وغیرہ نے بھی روایت کی ہے۔ ایک جماعت نے ان کی تاریخ وفات ۱۱۷ھ لکھی ہے۔ واقدی فرماتے ہیں: ۱۱۰ھ میں چوراسی(۸۴) سال کی عمر میں فوت ہوئے۔ اس بنا پر ان کی ولادت چھبیس (۲۶ھ) نبی صلی اللہ علیہ وسلم سے پندرہ(۱۵) سال بعد بنتی ہے۔ اس تمام بحث سے ان کے صحابی ہونے کی نفی ہوتی ہے۔ اور ابن مندہ کے اس قول کی بھی تردید ہو جاتی ہے کہ انہوں نے دور نبوی پایا ہے۔ انہی ابن عاصم نے اپنے والد سے روایت کی ہے ان کی ان سے مروی حدیث سنن میں ہے، ان سے ان کا بیٹا عاصم وغیرہ روایت کرتے ہیں۔ ابن سعد بحوالہ واقدی لکھتے ہیں: ابو البداح لقب اور کنیت ابو عمرو ہے۔ ثقہ ہیں۔ بہت کم حدیث بیان کرتے۔ ابن فتحون فرماتے ہیں: ابو عمر کا یہ کہنا ہے کہ وہ سبیعہ کو بیوہ چھوڑ مرے تھے وہم ہے۔ ابو البداح تو جمل بنت یسار جو معقل بن یسار کی بہن تھیں ان کے شوہر تھے۔ میں کہتا ہوں: سابقہ قصہ کو ابو البداح کا قصہ بنا کر قسم اول میں ذکر کرنا، جو یقیناً وہ نہیں، یوں انہیں بھی التباس ہوا جیسا دیگر لوگوں کو وہم ہوا ہے۔ جس نے یہ ذکر کیا کہ وہ صحابی ہیں اسے یوں منطبق کیا جا سکتا ہے کہ جن کے متعلق یہ کہا گیا کہ وہ سیدنا معقل بن یسار رضی اللہ عنہ کی ہمشیرہ کے خاوند تھے، شاید ان کے متعلق یہ کہا گیا ہو کہ وہ دور نبوی صلی اللہ علیہ وسلم میں فوت ہوئے اور اپنی بیوی کو حاملہ چھوڑ مرے تھے۔ لیکن سبیعہ کے خاوند کا نام سعد بن خولہ مشہور ہے، جو اپنی بیوی کے حمل کے وقت فوت ہوئے تھے۔ واللہ سبحانہ و تعالی اعلم","",{"fn":"(1) اسد الغابہ (۵۷۱۱) تجرید (۱۵۰/۲)"}],[9596,"§۹۶۳۳ ۔ ابو بردہ انصاری(1)\nنبی صلی اللہ علیہ وسلم سے تعزیر کے متعلق روایت کرتے ہیں۔ ان سے جابر بن عبد اللہ روایت کرتے ہیں۔ نسائی نے ان کی حدیث درج کی ہے۔ ابو عمر نے ان میں اور ابو بردہ بن نیار جو براء بن عازب کے ماموں ہیں فرق کرتے ہیں انہیں براء رضی اللہ عنہ کا ماموں لکھا ہے۔۔۔۔ ابن ابی خیثمہ اس شخصیت کے متعلق لکھتے ہیں: جن سے جابر روایت کرتے ہیں۔ مجھے معلوم نہیں وہ ظفری ہیں یا کوئی اور؟(2) اس کی وجہ یہ ہے کہ ان کی روایت میں ابو بردہ ظفری لکھا ہے۔ ابو عمر فرماتے ہیں: یہ ان کے علاوہ ہیں جن سے جابر روایت کرتے ہیں۔ وہ ابو بردہ بن نیار ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۱۳) استیعاب (۲۹۰۹) تجرید (۱۵۱/۲)\n(2) مسند احمد (۴۴۶/۳)"}],[9597,"§۹۶۳۴ ۔ ابو بردہ (دوسرے ہیں)(1)\nجس نے مسند طیالسی(2) جمع کی ہے اس نے ان میں اور ابو بردہ بن نیار میں فرق کیا ہے۔ ابو داؤد طیالسی فرماتے ہیں: سلام بن سلیم جو احوص ہیں، انہوں نے ہمیں بحوالہ سماک بن حرب، قاسم بن عبد الرحمن سے بحوالہ اپنے والد وہ ابو بردہ سے (ابو موسیٰ کے بیٹے نہیں) روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “برتنوں میں مشروبات پیتے رہو لیکن کوئی نشہ آور چیز نہ پیو۔”(3) اسے نسائی نے ہناد بن سری سے بحوالہ ابو الاحوص نقل کیا ہے۔ چنانچہ وہ اپنی روایت میں فرماتے ہیں: ابو بردہ بن نیار سے روایت ہے اس کے بعد نسائی فرماتے ہیں: اس میں ابو الاحوص سے غلطی ہوئی۔ سماک کے شاگردوں میں سے ہمارے علم کے مطابق کسی نے ان کی متابعت نہیں کی۔ اسی روایت کو دارقطنی نے یحییٰ بن یحییٰ کی روایت سے بحوالہ محمد بن جابر سماک سے نقل کیا ہے۔ فرماتے ہیں: قاسم سے وہ ابو بردہ سے وہ اپنے والد سے روایت کرتے ہیں۔ الدار قطنی فرماتے ہیں: اس حدیث کے متن اور سند میں ابو الاحوص سے وہم ہوا ہے، درست روایت یہی محمد بن جابر والی ہے۔ میں کہتا ہوں: اس بنا پر تو ابو الاحوص سے لفظی غلطی ہوئی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۲۵)\n(2) مسند ابی داؤد طیالسی (۱۳۶۹)\n(3) نسائی کتاب الاشربۃ باب ذکر الاخبار التی اعتقل بہا (۵۶۸۸)"}],[9598,"§۹۶۳۵ ۔ ابو بکر بن حفص(1)\nابو مسعود سلیمان بن ابراہیم اصبہانی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا اور حماد بن سلمہ کے طریق سے بحوالہ علی شاید وہ ابن زید بن جدعان ہیں، ابو العالیہ سے بحوالہ علی شاید وہ ابن زید بن جدعان ہیں، ابو العالیہ سے بحوالہ ابو بکر بن حفص ایک روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم عبد اللہ بن رواحہ کی عیادت کرنے گئے۔۔۔۔ (الحدیث)(2) جو شہداء کے ذکر میں ہے۔ ابو موسیٰ فرماتے ہیں: اس روایت کو شعبہ نے ابو بکر بن حفص سے انہوں نے ابو صبح سے انہوں نے عبادہ بن صامت رضی اللہ عنہ سے روایت کیا ہے۔ میں کہتا ہوں: مذکورہ شخصیت ابو بکر بن حفص، ابن حفص بن عمر بن سعد بن ابی وقاص ہیں۔ مختار ثقفی نے حفص اور ان کے والد کو شہید کیا تھا۔ ابو بکر بن حفص متوسط درجہ کے تابعی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۲۹) تجرید (۱۵۲/۲)\n(2) مسند احمد (حدیث: ۲۰۶/۴) مجمع الزوائد (۳۰۰/۵)"}],[9599,"§۹۶۳۶ ۔ ابو بلال بن سعد\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا اور اسے طبرانی کی طرف منسوب کیا، یہ ان کی کنیت نہیں اس سے مراد بلال بن سعد کے والد ہیں۔ عنوان سعد کا قائم ہے جو بلال کے والد ہیں اور سعد وہی ابن تمیم سکونی ہیں جیسا کہ پہلے اسماء میں گزر چکا ہے۔ بلال مشہور تابعی ہیں۔ واللہ اعلم"],[9600,"§۹۶۳۷ ۔ ابو تجراۃ (تا زیر والی جیم ساکن)\nشیبہ بن عثمان الجحی کے حلف کی وجہ سے مولی، ان کی بیٹی برہ صحابیہ ہیں۔ نیز ان کی بیٹی حبیبہ صحابیہ ہیں۔ زبیر کے ذکر کردہ بیان سے پتہ چلتا ہے کہ وہ اس قسم سے تعلق رکھتے ہیں۔ چنانچہ انہوں نے عبد الرحمن بن عبد العزیز کے طریق سے نقل کیا ہے کہ شیبہ بن عثمان امیر معاویہ کی طرف اپنے حلیف ابو تجراۃ کے ساتھ سعد بن طلحہ بن ابی طلحہ کی امارت کے سلسلہ میں گئے۔ شیبہ نے یہ اشعار کہے: “مکہ میں ابو تجراۃ کو اپنے گھرانے کی صحت سے راحت ملتی ہے اور سفر کے دوران وہ سائے کا دلدادہ ہے۔ پراگندہ ہو کر اور دھوپ سے اعراض کر کے نقاب ظاہر کرتا ہے۔” نیز شیبہ کہتے ہیں: ایک دفعہ دو پہر میں نے بھی ایسا ہی کپڑا کیا، مجھے سعد کے بارے نرم بچھونوں کا خوف تھا۔ میں کہتا ہوں: ابو تجراۃ خلافت امیر معاویہ تک زندہ رہے جس سے پتہ چلتا ہے کہ وہ اس قسم سے تعلق رکھتے ہیں۔ اس لیے کہ مکہ میں جو بھی موجود تھا وہ حجتہ الوداع کے موقع پر حاضر تھا۔ اور یہ بھی کی تھے، عمر بن شبہ نے حلفاء بنی نوفل میں ان کا ذکر کر کے کہا: وہ ابو فکیھہ بن یسار کے بھائی ہیں۔"],[9601,"§۹۶۳۸ ۔ ابو تخی(1)\nانصار کے شیخ۔ ان کا ذکر ایک صحیح حدیث میں آتا ہے جسے ابو یعلی ابن خزیمہ وغیرہ اسود بن قیس کے طریق سے بحوالہ ثعلبہ بن عباد، سمرہ بن جندب رضی اللہ عنہ سے نقل کیا ہے۔ فرماتے ہیں: ایک دفعہ نبی صلی اللہ علیہ وسلم کے دور میں میں اور انصار کا ایک لڑکا نشانہ بازی کر رہے تھے۔ اسی دوران سورج طلوع ہو گیا جو دیکھنے والے کو افق سے ایک یا دو نیزے کے فاصلے پر لگتا تھا۔ پھر سیاہ ہو گیا اور ایسی حالت ہو گئی جیسے وہ اسے سلا رہا ہے۔۔۔۔ (حدیث) اس میں نبی صلی اللہ علیہ وسلم کا سورج گرہن کے موقع کا خطبہ ہے، اسی میں دجال کا ذکر ہے کہ اس کی بائیں آنکھ ایسی ہاتھ پھری ہوگی جیسی ابو تخی(2) کی آنکھ ہے۔ ایک بوڑھے شخص جو آپ کے اور حجرہ عائشہ رضی اللہ عنہا کے درمیان تھے۔ یہ حدیث سنن اربعہ میں مختصر ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۴) تجرید (۱۵۲/۲)\n(2) مسند احمد (۱۶/۵) الدر المنثور (۳۵۵/۵)"}],[9602,"§۹۶۳۹ ۔ ابو تمیم(1)\nان کی حدیث ان کا پوتا عمرو بن تمیم بن ابی تمیم بحوالہ اپنے والد اپنے دادا نبی صلی اللہ علیہ وسلم سے روایت کرتا ہے: “اپنے سامنے مرنے والا شکار کھا لو اور جو آنکھوں سے اوجھل مرے اسے چھوڑ دو”۔(2)","",{"fn":"(1) تجرید (۱۵۳/۲)\n(2) مجمع الزوائد (۶۸/۵) المعجم الکبیر (۲۷/۱۲)"}],[9603,"§۹۶۴۰ ۔ ابو تمیمہ (بے نسبت)(1)\nابن مندہ نے ان کا ذکر کیا ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سماع کیا ہے اور آپ سے روایت کی ہے، ان سے حسن، ابو سلیل روایت کرتے ہیں۔ ابو نعیم نے اسحاق بن بیج کے طریق سے بحوالہ عطاء خراسانی، حسن سے نقل کیا ہے۔ فرماتے ہیں: میں نے ابو تمیمہ سے سنا اور وہ ان لوگوں میں سے تھے جنہوں نے دور نبوی پایا تھا۔ فرماتے ہیں: میں نے آپ صلی اللہ علیہ وسلم سے انصاف کی قسموں کے متعلق پوچھا، آپ نے ارشاد فرمایا: تمہارا اپنے نفس سے لوگوں کو انصاف دینا، علم والے کو سلام کرنا، اور اللہ تعالیٰ کا ذکر کرنا۔۔۔۔ (حدیث)(2) اور اسحاق کمزور ترین راوی ہے۔ ابو نعیم نے یہ روایت ابو اسحاق کی روایت سے بحوالہ ابو تمیمہ ان کے حالات میں نقل کی ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے عرض کیا یا کسی اور نے کہا: کب تک آپ اللہ تعالیٰ کی طرف بلاتے رہیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “میں اس اللہ کی طرف بلاتا رہوں گا، جب تمہیں کوئی تکلیف پہنچتی ہے تو تم اسے پکارتے ہو وہ تمہاری تکلیف دور کر دیتا ہے۔” یہ حدیث ابو تمیمہ قیمی کی مشہور ہے(3) جن کا ذکر چوتھی قسم میں آئے گا۔ ابن عبد البر(4) لکھتے ہیں: ابو تمیمہ کا ذکر عقیلی نے صحابہ رضی اللہ عنہم میں کیا ہے، اور ابو عبد اللہ کے طریق سے ان کی ایک روایت نقل کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا: “میری امت اس وقت تک فطرت پر قائم رہے گی، جب تک امانت کو غنیمت، زکوۃ کو فیکس اور خلافت کو بادشاہت نہیں سمجھے گی۔” (حدیث) فرماتے ہیں اس کی سند صحیح ہے۔","",{"fn":"(1) استیعاب (۲۹۲۱)\n(2) حلیۃ الاولیاء (۲۰۷/۵)\n(3) مسند احمد (۶۴/۵)\n(4) استیعاب (۲۹۲۱)"}],[9604,"§۹۶۴۱ ۔ ابو تمیم جیشانی(1)\nنام عبد اللہ بن مالک ہے پہلے تذکرہ ہو چکا ہے ابو بشر دولابی نے باب الصحابہ میں اور کتاب الکنی میں جنہوں نے دور نبوی پایا ان میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۶) تجرید (۱۵۳/۲)"}],[9605,"§۹۶۴۲ ۔ ابو تمام ثقفی(1)\nابو موسیٰ نے غلطی سے ان کا ذکر کیا ہے۔ وہ ابو عامر ثقفی ہیں جیسا کہ حرف عین میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۷۳۵) تجرید اسماء الصحابہ (۱۵۲/۲)"}],[9606,"§۹۶۴۳ ۔ ابو تمیمہ الہجیمی\nمشہور تابعی ہیں۔ ان کا نام طریف بن مجالد ہے، قسم اول میں ان کا ذکر گزر چکا ہے۔"],[9607,"§۹۶۴۴ ۔ ابو ثابت سعد بن عبادہ انصاری خزرج\nخزرج کے سردار، تذکرہ ہو چکا ہے۔"],[9608,"§۹۶۴۵ ۔ ابو ثابت سہل بن حنیف انصاری\nتذکرہ ہو گیا ہے۔"],[9609,"§۹۶۴۶ ۔ ابو ثابت اسید بن ظہیر انصاری\nذکر ہو چکا ہے۔"],[9610,"§۹۶۴۷ ۔ ابو ثابت بن عبد(1)\nبن عمرو بن قیطی بن عمرو بن یزید بن جشم انصاری حارثی، ابو عمر فرماتے ہیں: اُحد میں شریک ہوئے۔ بقول بعض عدی بن ثابت کے دادا ہیں جو بے اصل بات ہے۔ میں کہتا ہوں: اس کا قائل دولابی ہے۔ طبرانی کہتے ہیں: ابو ثابت انصاری، عدی بن ثابت کے دادا ہیں لیکن نہ ان کے والد کا اور نہ اوپر کے کسی شخص کا نام لیا۔","",{"fn":"(1) اسد الغابہ (۵۷۳۸) تجرید (۱۵۳/۲)"}],[9611,"§۹۶۴۸ ۔ ابو ثابت بن یعلی ثقفی\nطبری نے صحابہ رضی اللہ عنہم میں اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[9612,"§۹۶۴۹ ۔ ابو ثابت قرشی(1) (وحی کے پڑوسی)\nابن مندہ نے ان کا ذکر کیا ہے اور بزار وغیرہ نے ان کی حدیث نقل کی ہے جو عبد اللہ بن رجاء جمعی کے طریق سے بحوالہ شرحبیل بن حکم، حکیم بن عمیر سے راشد حرانی سے مروی ہے، فرماتے ہیں: مجھے ابو ثابت قریش کے ایک بوڑھے شخص نے بیان کیا جنہیں وحی کا پڑوسی کہا جاتا تھا، کیونکہ ان کا گھر نبی صلی اللہ علیہ وسلم کے اس گھر کے پاس تھا جس میں وحی نازل ہوئی تھی۔ فرماتے ہیں: میں نے نبی صلی اللہ علیہ وسلم کے ساتھ عشاء کی نماز پڑھی تو جبرائیل علیہ السلام نے آپ کو بلایا جیسا کہ خود آپ نے ہمیں بتایا ہے، وہ کہنے لگے: چلیں! نبی صلی اللہ علیہ وسلم نے فرمایا: اگر چاہیں تو میں آپ کے پاس آ جاؤں، اور اگر مرضی ہو تو آپ آ جائیں، جبرائیل نے کہا: میں آپ کے پاس آیا، تو ان کے لیے دیوار پھٹ گئی۔ پھر وہ اندر آئے۔ اور آپ کا ہاتھ پکڑ کر چل پڑے اور ایسی سواری پر بیٹھا جو خچر کی طرح تھی۔۔۔۔ (الحدیث)(2) جو اسراء کے متعلق ہے کہ اس کی انتہاء بیت المقدس تک ہوئی۔ اور انبیاء وغیرہ کی ملاقات و دیدار کا ذکر۔ اس روایت کو نقل کرنے کے بعد بزار لکھتے ہیں: ابن مندہ نے کہا: غریب روایت ہے جس میں عبد اللہ بن رجاء حمصی متفرد ہے۔ ابو نعیم لکھتے ہیں: اسے ابو حاتم رازی نے بحوالہ اسحاق یعنی ابن زُریق، انہوں نے عبد اللہ بن رجاء سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۹) تجرید (۱۵۳/۲)\n(2) ترمذی کتاب التفسیر باب و من سورۃ بنی اسرائیل (حدیث: ۳۱۳۲) المستدرک (۳۶۰/۲) الصحیح لابن حبان کتاب الاسراء باب ذکر البیان بان جبرائیل شد البراق بالصخرۃ (۴۷) اسد الغابہ (۳۹۵/۴)"}],[9613,"§۹۶۵۰ ۔ ابو ثروان سعدی\nباء میں ابو برقان گزر چکا ہے، یہ نام ایک ہی ہے جن میں سے ایک غلط لکھ دیا گیا۔"],[9614,"§۹۶۵۱ ۔ ابو ثروان بن عبد العزی سعدی\nنبی صلی اللہ علیہ وسلم کے رضاعی چچا۔ ابن سعد نے طبقات میں حلیمہ نبی صلی اللہ علیہ وسلم کی رضاعی ماں کے سوانح میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مجھ سے محمد بن عمر یعنی واقدی نے بحوالہ معمر، زہری سے وہ عبد اللہ بن جعفر سے وہ ابن ابی سبرہ وغیرہ سے روایت کرتے ہیں کہ ہوازن کا وفد نبی صلی اللہ علیہ وسلم کے پاس جعرانہ میں غنیمت تقسیم ہونے کے بعد آیا۔ اس میں نبی صلی اللہ علیہ وسلم کے رضاعی چچا ابو ثروان بھی تھے، انہوں نے کہا: یا رسول اللہ! ان باڑوں میں وہ خواتین ہیں جو آپ کی پھوپھیوں، خالاؤں اور بہنوں کی جگہ رکھتی ہیں۔ ہم نے آپ کو اپنے ہاں (دودھ پیتے دیکھا) گود کھلایا، آپ سے بڑھ کر کوئی دودھ پیتا بچہ بہتر نہ تھا۔ پھر ہم نے آپ کی جوانی دیکھی آپ سے بہتر کوئی جوان نہ تھا پھر بھلائی کی تمام خصلتیں آپ میں پایہ تکمیل تک پہنچ گئیں۔ اس کے باوجود ہم آپ رشتہ دار و قرابت دار ٹھہرے۔ سو آپ ہم پر احسان فرمائیے، اللہ تعالیٰ آپ پر کرم کرے گا۔ ان کے پاس وفد ہوازن اپنا اسلام پیش کر چکا تھا، قوم کا سردار اور منتظم ابو مرد زہیر بن صرد تھا پھر اس کا قصہ ذکر کیا۔ میں کہتا ہوں: چچا کا ذکر حرف باء میں گزر چکا ہے۔ ابو موسیٰ نے مستغفری کی پیروی کرتے ہوئے کہا ہے کہ وہ ابو برقان تھے۔ جو واقدی نے ذکر کیا ہے وہ زیادہ بہتر ہے (جو ثاء اور راء سے ہے)۔ دوسری جگہ بھی ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم نے اپنی رضاعی بہن سے ان کے باقیماندہ لوگوں کے متعلق پوچھا تو انہوں نے اپنے چچا، بہن اور بھائی کے زندہ ہونے کی اطلاع دی۔ اور یہ گزر چکا ہے کہ ان کا بھائی عبد اللہ بن حارث تھا اور بہن کا نام انیسہ تھا، جس کا تذکرہ کتاب النساء میں ان شاء اللہ تعالیٰ آئے گا۔"],[9615,"§۹۶۵۲ ۔ ابو ثروان راعی تمیمی(1)\nدولابی نے کنیتوں میں ان کا ذکر کیا ہے اور احمد بن داؤد کی سے بحوالہ ابراہیم بن زکریا، عبد الملک بن ہارون بن عنترہ سے نقل کیا، فرماتے ہیں: مجھے میرے والد نے بتایا کہ میں نے ابو ثروان کو فرماتے سنا: میں بنی عمرو بن تمیم کے اونٹ چراتا تھا نبی صلی اللہ علیہ وسلم قریش سے نکل کر میرے اونٹوں میں آ گئے اور ان کے درمیان آ کر بیٹھ گئے جس سے اونٹ منتشر ہو گئے۔ میں نے کہا: کون ہیں آپ؟ میرے اونٹوں کو منتشر کر دیا ہے۔ آپ نے فرمایا: میں نے چاہا تم سے اور تمہارے اونٹوں سے اپنی وحشت دور کروں۔ میں نے دوبارہ پوچھا: آپ ہیں کون؟ فرمایا: اگر تم مجھ سے نہ پوچھو تو تمہارا نقصان تو نہیں؟ میں نے کہا: میرے خیال میں آپ وہ نبی تو نہیں ہیں۔ آپ نے فرمایا: میں تمہیں اس کی دعوت دیتا ہوں کہ تم یہ گواہی دو کہ اللہ کے سوا کوئی دعا و پکار کے لائق نہیں اور محمد اللہ تعالیٰ کے (بھیجے ہوئے) رسول ہیں۔ میں نے کہہ دیا آپ میرے اونٹوں سے نکل جائیں خدا ان اونٹوں میں برکت نہ دے جن میں آپ موجود ہوں۔ آپ نے فرمایا: اے اللہ! اس کی بدبختی اور زندگی بڑھا دے۔ ہارون فرماتے ہیں: میں نے انہیں انتہائی بڑھاپے کے عالم میں موت کی تمنا کرتے دیکھا ہے، لوگ ان سے کہنے لگے: ابو ثروان! تم تو ہلاک ہی ہو گئے تمہیں نبی صلی اللہ علیہ وسلم نے بددعا دی ہے۔ وہ کہنے لگے: نہیں۔ جب اسلام ظاہر ہو گیا تو میں آپ کی خدمت میں آ کر مسلمان ہو گیا تھا، آپ نے میرے لیے مغفرت کی دعا بھی فرمائی تھی لیکن آپ کی پہلی بددعا اپنا کام کر گئی۔(2) محمد بن سلیمان ساعدی نے بحوالہ عبد الملک ان کی متابعت کی ہے۔ اور عبد الملک متروک راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۰) تجرید (۱۵۳/۲)\n(2) الکنی والاسماء (۲۰/۱) جامع المسانید (۴۴۲/۱۳) اسد الغابہ (۳۹۶/۴)"}],[9616,"§۹۶۵۳ ۔ ابو ثریہ\nبروزن عطیہ۔(1) بقول تصغیر ہے، سبرہ بن معبد الجہنی، پہلے تذکرہ ہوا ہے۔","",{"fn":"(1) تجرید (۱۵۳/۲)"}],[9617,"§۹۶۵۴ ۔ ابو ثعلبہ اشجعی(1)\nامام بخاری رحمہ اللہ(2) فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، امام بخاری رحمہ اللہ سے ہی حاکم ابو احمد وغیرہ نے نقل کر کے ان کا ذکر کیا ہے اور ان سے روایت کرنے والے راوی کے متعلق کہتے ہیں: مجھے ان کے حالات معلوم نہیں۔ اور نہ میں ابو ثعلبہ کے متعلق جانتا ہوں۔ بغوی لکھتے ہیں: وہ مدینہ کے رہائشی تھے۔ امام احمد بغوی اور ابن مندہ نے بطریق ابن جریج، بحوالہ ابن الزبیر، عمر بن نبہان سے انہوں نے ابو ثعلبہ اشجعی سے ان کی حدیث نقل کی ہے، فرماتے ہیں: میں نے عرض کیا: یا رسول اللہ! میرے بچوں کا حالت اسلام میں انتقال ہوا ہے، آپ نے فرمایا: “جس کے بچے اسلام میں فوت ہوئے ہوں تو اللہ تعالیٰ ان پر اپنے فضل و کرم(3) کی وجہ سے اسے جنت میں داخل کرے گا۔” بغوی نے یہ اضافہ نقل کیا ہے، فرماتے ہیں: مجھ سے ابو ہریرہ رضی اللہ عنہ ملے تو بولے: تمہی وہ شخص ہو جسے نبی صلی اللہ علیہ وسلم نے بچوں کے بارے میں ارشاد فرمایا ہے؟ میں نے کہا: جی۔ فرمایا: اگر انہوں نے مجھ سے کہا ہوتا تو یہ بات مجھے فلاں سے زیادہ محبوب ہے۔ ابن مندہ فرماتے ہیں: یہ روایت ابن جریج سے مشہور ہے۔ ابو حاتم فرماتے ہیں: نہ مجھے ان دونوں کا پتہ ہے اور نہ ان کی بات کا۔ دار قطنی نے ذکر کیا ہے۔ بعض نے اسے ابن جریج سے نقل کیا ہے تو خشنی کہا اور بعض نے سیدنا ابو ہریرہ رضی اللہ عنہ سے نقل کیا تو ابو ثعلبہ نہیں کہا جبکہ درست پہلی روایت ہے۔ میں کہتا ہوں: پہلی روایت خطیب کی کتاب “المتفق” میں بروایت انصاری، ابن جریج لکھی ہے اور دوسری امام احمد رحمہ اللہ کی مسند میں، حماد بن مسعدہ سے بحوالہ ابن جریج ہے، لیکن ابن مندہ نے اسے عبد الرحمن بن یحییٰ سے بحوالہ ابن مسعود رازی، حماد بن مسعدہ سے نقل کیا ہے، فرماتے ہیں: ابو ثعلبہ سے مروی ہے: بغوی نے اس میں سیدنا ابو ہریرہ رضی اللہ عنہ کے تذکرہ کی وجہ بتائی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۱) تجرید (۱۵۳/۲)\n(2) التاریخ الکبیر (۱۸/۸)\n(3) الاحاد والمثانی (۲۷/۳)"}],[9618,"§۹۶۵۵ ۔ ابو ثعلبہ ثقفی(1)\nکردم بن سفیان کے چچا زاد، کردم بن سفیان کا تذکرہ پہلے ہو چکا ہے۔ ان کی حدیث کا ایک اور طریق ہے جسے دار قطنی(2) محمد نے خالد بن معدان بحوالہ ابو ثعلبہ نقل کیا ہے، فرماتے ہیں: مجھے میرے چچا نے فرمایا: میرا ایک کام کر دو میں تمہیں اپنی بیٹی کا رشتہ دے دوں گا۔ میں نے کہا: میں نے اگر اس سے شادی کی تو اسے تین طلاق، اسی میں ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: طلاق نکاح کے بعد ہی واقع ہوتی ہے۔ فرماتے ہیں: پھر میری اس سے شادی ہو گئی جس سے سعد اور سعید پیدا ہوئے۔ اس کی سند میں علی بن قرین جو بے حد کمزور راوی ہے۔ نیز قصہ کے اسلوب بیان میں فرق ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۳) استیعاب (۲۹۲۶) تجرید (۱۵۳/۲)\n(2) سنن دارقطنی (۱۷/۴)"}],[9619,"§۹۶۵۶ ۔ ابو ثعلبہ حنفی\nقاسم بن ثابت نے “دلائل” میں ولید بن مسلم کے طریق سے بحوالہ سعید بن عبد العزیز ان کا ذکر کیا ہے کہ ابو ثعلبہ حنفی فرمایا کرتے تھے: مجھے امید ہے کہ میں اس طرح سے روح کے پھندے سے نہیں مروں گا جیسے تم لوگ غرغرے کی حالت میں مرتے ہو اسی دوران انہوں نے اپنے اس بھائی سے کہا جو نبی صلی اللہ علیہ وسلم کے زمانہ میں فوت ہو گئے تھے: عبد الرحمن! یہ رسول اللہ صلی اللہ علیہ وسلم ہیں، پھر اپنے گھر نماز کی جگہ میں آ کر سجدے میں گر گئے اور اسی حالت میں ان کی روح قبض ہو گئی۔ اس روایت کو ابو نعیم نے حلیہ میں نقل کیا ہے جو ابو ثعلبہ خشنی کے سوانح میں مذکور ہے شاید کسی ایک جگہ غلطی ہوئی ہے۔"],[9620,"§۹۶۵۷ ۔ ابو ثعلبہ خشنی(1)\nمشہور صحابی ہیں جو اپنی کنیت سے شہرت رکھتے ہیں۔ ان کے اصل میں بہت زیادہ اختلاف ہے اتفاق دیکھیں یہی اختلاف ان کے والد کے نام میں بھی ہے کسی نے جرہم کہا جسے امام احمد، مسلم، ابن زنجویہ، ہارون حمال اور ابن سعد نے اپنے ساتھیوں سے نقل کیا ہے اور کسی نے جرثم تو کسی نے جرہوم، تو کسی نے جرثوم، اور بعض نے جرثونہ کہا۔ کسی نے عمر کسی نے سق، کسی نے لاسق کسی نے لاسر، کسی نے لاس کسی نے لاشوم کسی نے الاشق کسی نے الاشر کسی نے اشبع بروزن امین، کسی نے ناشر کسی نے ناشب تو کسی نے غرنوق کہا ہے۔ یہ تو ان کے نام میں اختلاف تھا۔ ان کے والد کے نام کے متعلق یہ اقوال ہیں: عمرو، قیس، ناسم، لاشم، لاسر، ناشب، ناشر، جرہم، جرہوم، جمیر، جرثوم، جلہم، عبد الکریم ایسا ہی ابن اسعد کی کتاب میں ہے۔ واللہ اعلم ان کے دادا کا کیا نام تھا مجھے معلوم نہ ہو سکا۔ یہ بنی خشین کی طرف منسوب ہیں۔ نام وائل بن عمر بن وبرہ بن تغلب بن حلوان بن عمران بن حاف بن قضاعہ ہے۔ ابن کلبی فرماتے ہیں: ان کا تعلق لیوان بن مز بن خشین کی اولاد سے ہے۔ نبی صلی اللہ علیہ وسلم سے کئی احادیث روایت کی ہیں۔ ایک حدیث صحیحین میں ربیعہ بن یزید کے طریق سے مروی ہے۔ میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم ہم ایسی سرزمین میں رہتے ہیں جہاں اہل کتاب ہیں ہم ان کے برتنوں میں کھاتے پیتے ہیں اور شکار کی زمین سے اپنی کمان اور اپنے سدھائے اور بے سدھائے کتے سے شکار کرتا ہوں تو آپ مجھے بتائیں ان میں سے میرے لیے کیا حلال ہے؟۔۔۔۔ حدیث(2) ابو ثعلبہ شام میں رہائش پذیر رہے بقول بعض حمص رہے۔ ان سے روایت کرنے والے مندرجہ ذیل افراد ہیں: ابو ادریس خولانی، ابو امیہ شعبانی ابو اسماء رحبی، سعید بن المسیب، جبیر بن نفیر، ابو قلابہ، مکحول بعض دوسرے حضرات جنہوں نے ان کا دور نہیں پایا ہے۔ ابن برقی، ابن کلبی کے اتباع میں فرماتے ہیں: درخت تلے بیعت کرنے والوں میں شامل تھے اور خیبر میں ان کا حصہ مقرر ہوا۔ آپ صلی اللہ علیہ وسلم نے انہیں ان کی قوم کی طرف داعی بنا کر بھیجا وہ سب مسلمان ہو گئے۔(3) ابن سعد نے اپنی سند سے بحوالہ مجن بن وہب نقل کیا ہے فرماتے ہیں: ابو ثعلبہ اس وقت نبی صلی اللہ علیہ وسلم کے پاس آئے جب آپ خیبر کے لیے تیاری فرما رہے تھے وہیں اسلام لائے اور آپ کے ساتھ اس غزوہ میں شریک ہوئے۔ بعد میں ان کی قوم کے سات افراد آئے اور مسلمان ہو کر ان کے پاس ٹھہرے۔ ابو الحسن بن سمیع فرماتے ہیں: مجھے پتہ چلا ہے کہ وہ سیدنا ابو ہریرہ رضی اللہ عنہ سے پہلے اسلام لائے اور نبی صلی اللہ علیہ وسلم کے بعد بھی زندہ رہے۔ جنگ صفین میں کسی گروہ کے ساتھ نہیں لڑے۔ امیر معاویہ رضی اللہ عنہ کی خلافت کے ابتدائی دور میں فوت ہوئے۔ لیکن مشہور اس کے برخلاف ہے۔ ابو علی خولانی کہتے ہیں: وہ داریا میں فروکش ہوئے۔ ابن عساکر نے ان کے حالات میں لکھا ہے جو محفوظ بن علقمہ کے طریق سے بحوالہ ابن عائذ مروی ہے فرماتے ہیں: ناشرہ بن سمی نے کہا: ہم نے ابو ثعلبہ سے بڑھ کر سچا آدمی نہیں دیکھا۔ وادی کے صحنوں کے متعلق ہم نے ان کی بات کو سچا پایا، علی فرماتے ہیں: وہ ہر رات آسمان کی طرف آ کر دیکھتے کہ کیسا ہے پھر آ کر سجدہ کرتے۔ ابو زاہریہ سے مروی ہے کہ ابو ثعلبہ نے فرمایا: مجھے امید ہے کہ جیسے تم لوگوں کا گلا موت کے وقت گھٹ جاتا ہے میری موت اس طرح نہیں ہوگی۔ فرماتے ہیں: ایک دفعہ رات میں نماز پڑھ رہے تھے تو سجدہ کی حالت میں ان کی روح پرواز کر گئی۔ ان کی بیٹی نے خواب میں دیکھا کہ اس کا والد فوت ہو گیا ہے چونک کر اٹھی آواز دی کوئی جواب نہ ملا دوبارہ آواز دی کسی نے کہا جائے نماز پر نہیں وہاں آ کر انہیں کہا: ابا جان! انہوں نے کوئی جواب نہ دیا۔ حرکت دی تو وہ گر پڑے۔ ابو عبید، ابن سعد خلیفہ بن خیاط، ہارون حمال اور ابو حسان زیادی کا قول ہے کہ وہ پچھتر(۷۵) ھ میں فوت ہوئے تھے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۴) استیعاب (۲۹۲۷) تجرید (۱۵۳/۲)\n(2) سنن دارقطنی (۴۸۳) المعجم الکبیر (۵۸۹/۲۲) مجمع الزوائد (۱۷۱/۱) جامع المسانید والسنن (۴۵۴/۱۳)\n(3) جامع المسانید (۴۴۳/۱۳)"}],[9621,"§۹۶۵۸ ۔ ابو ثمامہ کنانی\nجاہلیت کی رسم نسئی کرنے والے آخری شخص ان کا نام جنادہ تھا بقول بعض امیہ، جیم میں ذکر ہو چکا ہے۔"],[9622,"§۹۶۵۹ ۔ ابو ثور فہمی(1)\nابو زرعہ رازی فرماتے ہیں: صحابی ہیں، لیکن مجھے ان کا نام معلوم نہیں۔ بغوی لکھتے ہیں: مصر میں رہے ہیں، ابو احمد حاکم فرماتے ہیں نہ مجھے ان کے نام کا علم ہے اور نہ سلسلہ نسب سے واقف ہوں۔ میں کہتا ہوں: امام احمد،(2) علم بغوی اور ابن السکن وغیرہ نے ان کی حدیث ابن لہیعہ کے طریق سے بحوالہ یزید بن عمرو وہ ان سے روایت کرتے ہیں فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے کہ معافر کا ایک کپڑا آپ کے پاس لایا گیا ابو سفیان کہنے لگے اللہ تعالیٰ اس کپڑے پر اور اس کے بنانے والے پر لعنت کرے آپ صلی اللہ علیہ وسلم نے فرمایا: ان پر لعنت نہ کرو کیونکہ وہ میرے اور میں ان کا ہوں ابو ثور کو سیدنا عثمان رضی اللہ عنہ سے روایت حاصل ہے جس کا انہوں نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۵) استیعاب، تجرید (۱۵۴/۲)\n(2) مسند احمد (۳۰۵/۴)"}],[9623,"§۹۶۶۰ ۔ ابو ثور محمد بن معدی کرب زبیدی\nناموں میں ذکر ہو چکا ہے۔"],[9624,"§۹۶۶۱ ۔ ابو ثعلبہ قرظی\nدور نبوی صلی اللہ علیہ وسلم پایا ہے اور سیدنا عمر رضی اللہ عنہ سے حدیث سنی ہے ان سے زہری روایت کرتے ہیں۔ ابو احمد کنیتوں میں عبد الرحمن بن یحییٰ عدوی کے طریق سے بحوالہ یونس دیلی وہ زہری سے وہ ابو ثعلبہ قرظی سے روایت نقل کرتے ہیں فرمایا: میں نے سیدنا عمر رضی اللہ عنہ کو فرماتے سنا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: لوگ گناہوں کا ارتکاب کرتے ہیں۔ جب فجر کی نماز پڑھ لیتے ہیں تو سابقہ (صغیرہ) گناہ دھل جاتے ہیں۔ حدیث۔ ابو احمد فرماتے ہیں: یہ منکر حدیث ہے اور ابو ثعلبہ کا اس میں تذکرہ محفوظ نہیں اور عبد الرحمن بن یحییٰ غیر معتمد راوی ہے۔ مشہور ثعلبہ بن ابی مالک قرظی ہے۔ میں کہتا ہوں: یہ احتمال بعید نہیں کہ وہ دوسرے صاحب ہوں۔"],[9625,"§۹۶۶۲ ۔ ابو ثعلبہ انصاری(1)\nابن مندہ نے ان کا ذکر کیا ہے اور حماد بن سلمہ کے طریق سے بحوالہ محمد بن اسحاق، مالک بن ثعلبہ سے انہوں نے اپنے والد سے ایک روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے وادی مہزور(2) میں یہ فیصلہ فرمایا کہ سیرابی کے لیے ٹخنوں تک پانی روکا جائے”۔ (حدیث)(3) یہ غلط نام ہے ناموں کو الٹ دیا گیا ہے۔ درست ثعلبہ بن ابی مالک ہے۔ جیسا کہ ناموں کی قسم رابع میں گزر چکا ہے۔ وہ قرظی ہیں اور انصار کے حلیف ہیں۔ انہوں نے نبی صلی اللہ علیہ وسلم سے نہیں سنا، ان کے درمیان جس صحابی کا واسطہ ہے ان کا نام نہیں لیا گیا ابو داؤد میں یہ روایت درست الفاظ میں لکھی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۲) تجرید (۱۵۳/۲)\n(2) مہزور ایک وادی ہے جس کے پانی پر باغوں والوں کا جھگڑا ہوا تھا۔\n(3) ابو داؤد کتاب الاقضیۃ باب من القضاء (۳۶۳۸)، ابن ماجہ کتاب الرہون باب الشرب من الاودیۃ (۲۴۸۱) السنن الکبریٰ (۱۵۴/۶)، جامع المسانید (۴۶۵/۳)"}],[9626,"§۹۶۶۳ ۔ ابو جابر انصاری\nعبد اللہ بن عمرو بن حرام، اسماء میں تذکرہ ہو چکا ہے۔"],[9627,"§۹۶۶۴ ۔ ابو جابر صدفی(1)\nطبرانی نے مبہم ناموں میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے کئی میں اپنے استدراک میں ذکر کیا ہے۔ انہی کے طریق سے، بحوالہ اعمش، قیس بن جابر صدفی سے وہ اپنے والد وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عنقریب میرے بعد خلفاء، خلفاء کے بعد امراء، امراء کے بعد بادشاہ اور بادشاہوں کے بعد ظالم حکمران ہوں گے۔ پھر میرے گھرانے کا ایک شخص نکلے گا جو زمین کو عدل و انصاف سے بھر دے گا۔ الحدیث۔(2) اعمش سے روایت کرنے والے شخص حسین بن علی کندی کو میں نہیں جانتا اور نہ مجھے قیس کے والد جابر کا حال معلوم ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۶) تجرید (۱۵۴/۲)\n(2) مجمع الزوائد (۱۹۰/۵) المعجم الکبیر (۹۳۷/۲۲) اسد الغابہ (۳۳۸/۴)"}],[9628,"§۹۶۶۵ ۔ ابو جابر یمامی\nسیار بن طارق ناموں میں تذکرہ ہو چکا ہے۔"],[9629,"§۹۶۶۶ ۔ ابو جاریہ انصاری(1)\nنبی صلی اللہ علیہ وسلم سے یہ ارشاد نقل کیا ہے “قرآن سارا درست ہے”۔(2) ان کی حدیث حرب بن ثابت نے بحوالہ اسحاق بن جاریہ وہ اپنے والد وہ اپنے دادا سے روایت کرتے ہیں۔ ابن مندہ نے ان کا اسی طرح ذکر کیا ہے۔ دار قطنی نے “موتلف” میں جاریہ بن اسحاق کی روایت بحوالہ اپنے والد اپنے دادا ابو الجاریہ نجاشی کی نماز جنازہ کے بارے میں نقل کی ہے۔ ابن ماکولا نے ان کی پیروی کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۷) تجرید (۱۵۴/۲)\n(2) التاریخ الکبیر (۲۸۲/۱) کنز العمال (۲۴۶۵) اسد الغابہ (۳۹۸/۴)"}],[9630,"§۹۶۶۷ ۔ ابو جبیر نفیر بن مالک کندی\nبقول بعض حضرمی، ناموں میں تذکرہ ہوا ہے۔"],[9631,"§۹۶۶۸ ۔ ابو جبیرہ(1) (شروع حرف پر زبر ہے)\nابن ضحاک بن خلیفہ انصاری اشہلی، ان کا نام مشہور نہیں۔ ابو احمد حاکم اور ابن مندہ فرماتے ہیں: یہ ثابت بن ضحاک کے بھائی ہیں۔ ابو احمد اور انہی کی پیروی میں ابن عبد البر کا قول ہے کہ یہ صحابی ہیں اور بعض کا قول ہے: کہ یہ صحابی نہیں، نبی صلی اللہ علیہ وسلم سے کئی ایک احادیث نقل کی ہیں ان سے ان کا بیٹا محمود، قیس بن ابی حازم، شبل بن عوف اور عامر شعبی روایت کرتے ہیں۔ ابن ابی حاتم فرماتے ہیں: میرے والد نے کہا: مجھے ان کے صحابی ہونے کا علم نہیں۔ میں کہتا ہوں: امام بخاری نے “الادب المفرد” میں ان کی حدیث نقل کی جسے اصحاب السنن نے بھی درج کیا ہے حاکم نے اسے صحیح اور ترمذی(2) نے حسن کہا ہے جس کے الفاظ یہ ہیں: “ہمارے بارے یہ آیت 'ایک دوسرے کو برے لقب مت دو'(3) نازل ہوئی۔","",{"fn":"(1) اسد الغابہ (۵۷۴۸) تجرید (۱۵۴/۲)\n(2) ترمذی کتاب التفسیر باب و من سورۃ الحجرات (۳۲۶۸)\n(3) سورۃ الحجرات: ۱۱"}],[9632,"§۹۶۶۹ ۔ ابو جبیرہ بن حصین(1)\nبن نعمان بن سنان بن عبد بن کعب بن عبد الافضل انصاری اشہلی، صحابہ میں ان کا ذکر آتا ہے یہ ابو عمر کا قول ہے۔ میں کہتا ہوں: اسلم میں ان کا ذکر ہوا ہے یہی نام ابو عبید قاسم بن سلام نے بتایا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۴۹)"}],[9633,"§۹۶۷۰ ۔ ابو جحش لیثی(1)(2)\nکتاب العظمۃ میں ابو الشیخ نے ان کی حدیث اور حاکم نے مستدرک میں عبد الملک بن قدامہ کے طریق سے بحوالہ عبد الرحمن بن عبد اللہ بن دینار وہ اپنے والد سے وہ ابن عمر رضی اللہ عنہ سے نقل کرتے ہیں، فرمایا: سیدنا عمر رضی اللہ عنہ مسجد میں داخل ہوئے، نماز ہو رہی تھی اور تین شخص بیٹھے ہوئے تھے، ان میں ایک ابو جحش لیثی تھے۔ آپ نے انہیں دیکھ کر فرمایا: اٹھو اور نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھو! ان میں سے دو شخص تو اٹھ گئے البتہ ابو جحش کہنے لگے: میں تو اس وقت تک نہیں اٹھوں گا جب تک کوئی مجھ سے قوی آ کر مجھے پچھاڑ نہیں لیتا اور مٹی میں گرا کر میرا چہرہ زخمی نہیں کر لیتا۔ تو سیدنا عمر رضی اللہ عنہ نے ان کا یہ شوق بھی پورا کر دیا۔ پھر فرشتوں کی عبادت کے متعلق حدیث ذکر کی۔ جس کے الفاظ یہ ہیں، نبی صلی اللہ علیہ وسلم نے فرمایا: “(ابو جحش!) تم بیٹھے رہو! اللہ تعالیٰ کو ابو جحش کی نماز کی ضرورت نہیں، آسمان دنیا پر اللہ تعالیٰ کے ایسے عاجز فرشتے ہیں جو قیامت تک سر نہیں اٹھائیں گے۔”(3) اسی حدیث میں ہے عمر رضی اللہ عنہ کی رضا مندی رحمت ہے۔ اسے ابو نعیم نے اپنے طریق سے روایت کیا ہے۔ حاکم فرماتے ہیں: شرط بخاری کے مطابق ہے۔ جبکہ ذہبی نے اسے رد کر دیا کہ غریب اور منکر ہے، شرط بخاری مفقود ہے۔ میں کہتا ہوں: اس کی سند میں صرف عبد الملک بن قدامہ تھی ہے جس کے متعلق اختلاف ہے، ابن معین اور عجلی نے اس کی توثیق کی ہے۔ ابو حاتم اور نسائی نے اسے ضعیف قرار دیا ہے۔ امام بخاری رحمہ اللہ فرماتے ہیں: معروف و منکر روایات نقل کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۵۱) تجرید (۱۵۴/۲)\n(2) المستدرک (۸۸/۳) تفسیر ابن کثیر (۲۹۶/۸)\n(3) جمع الجوامع (۵۷۰)"}],[9634,"§۹۶۷۱ ۔ ابو جحیفہ(1)\nوہب بن عبد اللہ اسوائی، ناموں میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۵۹) استیعاب (۲۹۳۲)"}],[9635,"§۹۶۷۲ ۔ ابو الجراح اشجعی\nانہیں الجراح بھی کہا جاتا ہے۔ ابو موسیٰ نے ذیل میں لکھا ہے کہ خلیفہ بن خیاط نے انہیں کنیت کے ساتھ ہی لکھا ہے۔ میں کہتا ہوں: ناموں میں گزر چکا ہے۔"],[9636,"§۹۶۷۳ ۔ ابو جرول(1)\nزہیر بن صرد جشمی، ناموں میں تذکرہ ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۲)"}],[9637,"§۹۶۷۴ ۔ ابو جرول (دوسرے)\nہند بن الصامت، پہلے ذکر ہو چکا ہے۔"],[9638,"§۹۶۷۵ ۔ ابو جری(1) (تصغیر)\nجابر بن سلیم / یا سلیم بن جابر جیمی، تذکرہ ہو چکا ہے۔ امام بخاری رحمہ اللہ(2) نے پہلے نام کو ترجیح دی ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۳) استیعاب (۲۹۳۳)\n(2) التاریخ الکبیر (۲۰۶/۲)"}],[9639,"§۹۶۷۶ ۔ ابو الجعال جذامی\nمغازی میں اموی نے بحوالہ ابن اسحاق ضمام کے ان لوگوں میں ان کا ذکر کیا ہے جو نبی صلی اللہ علیہ وسلم کے پاس اپنے ان قیدیوں کا مطالبہ کرنے آئے جنہیں سیدنا زید بن حارثہ رضی اللہ عنہ نے گرفتار کر لیا تھا اور اس کے متعلق اشعار بھی کہے۔"],[9640,"§۹۶۷۷ ۔ ابو الجعد افلح(1)\nابو العیس کے بھائی، سیدہ عائشہ رضی اللہ عنہا کے رضاعی والد۔ پہلے تذکرہ ہوا ہے۔ کنیت ابو الجعد، ابن جریج اپنی روایت میں بحوالہ عطاء، عروہ سے وہ سیدہ عائشہ رضی اللہ عنہا سے نقل کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۵۹) استیعاب (۲۹۳۴) تجرید (۱۵۵/۲)"}],[9641,"§۹۶۷۸ ۔ ابو الجعد ضمری(1)\nامام بخاری رحمہ اللہ فرماتے ہیں: مجھے ان کا نام معلوم نہیں۔ ان کی صرف ایک روایت میرے علم میں ہے یعنی وہ روایت جسے اصحاب السنن اور بغوی نے نقل کیا ہے اور ابن خزیمہ و ابن حبان وغیرہ نے اسے صحیح قرار دیا ہے۔ وہ از قبیل ترہیب ہے “جس نے جمعہ کی نماز چھوڑی۔۔۔۔”۔ (حدیث)(2) اس کے کسی طریق میں لکھا ہے کہ یہ صحابی ہیں۔ جبکہ ان کے علاوہ کسی نے ان کا نام اذرع لیا ہے، کسی نے جنادہ، کسی نے عمرو بن بکر نقل کیا ہے۔ سیدنا سلمان فارسی رضی اللہ عنہ سے بھی روایت کرتے ہیں۔ ان سے عبیدہ بن سفیان حضرمی روایت لیتے ہیں۔ فتح مکہ کے موقع پر بقول ابن سعد اپنی قوم کے امیر تھے۔ ابن البرقی فرماتے ہیں کہ جنگ جمل میں سیدہ عائشہ رضی اللہ عنہا کا ساتھ دیتے شہید ہوئے۔ بغوی فرماتے ہیں: مدینہ رہتے تھے، بنی ضمرہ میں ان کی ایک حویلی تھی۔ اس قول کو ابن سعد کی طرف منسوب کیا ہے، جس میں یہ اضافہ بھی کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ان کی قوم کی طرف بھیجا تا کہ وہ فتح مکہ کے لیے جمع ہو جائیں۔ اسے غزوہ تبوک کے موقع پر ان کی نفری جمع کرنے کے لیے انہیں ان کی قوم کی جانب بھیجا تھا۔ تو وہ ان کے ساتھ ساحل کی طرف نکلے اور ان کی معیت میں نبی صلی اللہ علیہ وسلم کے پاس آ گئے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۰) تجرید (۱۳۵/۲)\n(2) ترمذی کتاب الجمعۃ باب ما جاء فی ترک الجمعۃ من غیر عذر (۴۹۸)"}],[9642,"§۹۶۷۹ ۔ ابو الجعیجعہ(1)\nغلام والے۔ ابن مندہ نے ان کا ذکر کیا ہے اور ابو مقاتل حفص بن مسلم کے طریق سے بحوالہ عبد اللہ بن عوف، حسن سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم کے زمانہ میں ایک شخص غلام بیچتا تھا جس کا نام ابو الجعیجعہ تھا، فرماتے ہیں: پھر حدیث ذکر کی۔(2)","",{"fn":"(1) اسد الغابہ (۵۷۶۲) تجرید (۱۵۵/۲)\n(2) اسد الغابہ (۴۰۳/۴)"}],[9643,"§۹۶۸۰ ۔ ابو جمعہ انصاری(1)\nکنانی، قاری۔ کنیت سے شہرت رکھتے ہیں۔ نام میں اختلاف ہے۔ جندب بن سبع، ابن سباع، ابن وہب، جنید اور حبیب یہ آخری راجح ہے۔ محمد بن ربیع الجیزی نے ان صحابہ رضی اللہ عنہم میں ان کا تذکرہ کیا ہے جو فتح مصر میں شریک تھے۔ ابن سعد کا قول ہے: شام میں رہتے تھے پھر مصر منتقل ہو گئے۔ طبرانی کی روایت سے معلوم ہوتا ہے کہ وہ حدیبیہ کے دنوں میں مشرف باسلام ہوئے۔ چنانچہ حجر ابو خلف کے طریق سے عبد اللہ بن عوف سے بحوالہ ابو جمعہ جنید بن سبع انصاری سے مروی ایک روایت نقل کی ہے، فرمایا: “دن چڑھے تک تو میں کافروں کی طرف سے نبی صلی اللہ علیہ وسلم کے خلاف لڑتا رہا ہوں اور دن ڈھلے مسلمان ہو کر آپ صلی اللہ علیہ وسلم کی معیت میں کفار کے مقابلہ میں لڑتا رہا۔ ہم تین مرد اور نو عورتیں تھیں۔ ہمارے بارے ہی یہ آیت “اگر مومن مرد اور مومن عورتیں نہ ہوتیں”(2) نازل ہوئی۔ میں کہتا ہوں: انہیں انصاری لکھنا صحیح نہیں تھا، اس واسطے کہ اس وقت کوئی ایسا نہ بچا تھا جو ان میں سے قریش کے ساتھ مل کر مسلمانوں کے خلاف لڑتا۔ طبرانی ہی کی ایک روایت ہے “صاع بن جبیر بحوالہ ابو جمعہ کنانی” یہ زیادہ بہتر ہے۔ یہ بھی احتمال ہے کہ معاہدہ کی وجہ سے انصاری ہوں۔ اربعین نسفی میں ہم حدیث سلفی کا ایک حصہ جو متصل بالسماع ہے روایت کر چکے ہیں۔ معاویہ بن صالح کی روایت سے بحوالہ صالح بن جبیر مروی ہے، فرماتے ہیں کہ صحابی رسول اللہ صلی اللہ علیہ وسلم ابو جمعہ انصاری ہمارے پاس بیت المقدس میں نماز پڑھنے تشریف لائے وہاں رجاء بن حیوہ بھی ہمارے ساتھ موجود تھے۔ نماز وغیرہ سے فراغت کے بعد جب وہ نکلنے لگے تو ہم انہیں رخصت کرنے ان کے ساتھ چلے۔ ہم جب واپس چھوڑ کر مڑنے لگے تو انہوں نے فرمایا: تمہارے لیے ایک انعام اور حق ہے، وہ یہ کہ میں تمہیں نبی صلی اللہ علیہ وسلم کی ایک حدیث سناتا ہوں جو میں نے خود آپ صلی اللہ علیہ وسلم سے سنی ہے۔ ہم نے عرض کیا: ضرور سنائیے! فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے جن میں معاذ دسویں آدمی تھے۔ ہم نے عرض کیا: یا رسول اللہ! کوئی گروہ ہم سے بھی زیادہ اجر و ثواب والا ہے؟ ہم آپ پر ایمان لائے، آپ کا اتباع کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تمہیں اس فضیلت سے کون روک سکتا ہے، اللہ کا رسول تمہارے درمیان ہے، تم میں آسمان سے وحی آتی ہے؟ (حدیث) اس حدیث کا، بطریق اسید بن عبد الرحمن بحوالہ صالح بن جبیر اس کی اسناد کے بغیر، ایک شاہد بھی ہے۔ جسے امام احمد اور دارمی بیا نے نقل کیا ہے اور حاکم نے اسے صحیح قرار دیا ہے۔ ان کی حدیث امام بخاری رحمہ اللہ نے کتاب خلق افعال العباد میں درج کی ہے۔ اوزاعی سے اوپر اس کے متعلق اختلاف ہے۔ اکثر ان سے روایت کرتے ہیں جو اسید، خالد بن دریک، ابن محیریز کے سلسلہ سند سے ہے۔ فرماتے ہیں: میں نے ابو جمعہ سے کہا، انہوں نے فرمایا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ صبح کا کھانا کھایا ہمارے ساتھ ابو عبیدہ بن الجراح تھے۔ (حدیث)(3) ابن شماس، اوزاعی، اسید، صالح بن محمد کے سلسلہ سند میں ہے مجھ سے ابو جمعہ نے بیان کیا۔ ان سے ان کے مولیٰ روایت کرتے ہیں جن کا نام معلوم نہیں۔ صالح بن جبیر، عبد اللہ محیریز، عبد اللہ بن عوف ریلی بھی ان سے روایت کرتے ہیں۔ امام بخاری رحمہ اللہ نے ان کا ذکر ستر(۷۰) سے اسی(۸۰) تک کی درمیانی عمر میں فوت ہونے والوں کی فضیلت میں کیا ہے۔ ابن حبان نے بہت انوکھا کام کیا کہ ان کے متعلق ثقات التابعین میں لکھتے ہیں: ابو جمعہ حبیب بن سباع صحابہ رضی اللہ عنہم کی ایک جماعت سے روایت لیتے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۶۳) تجرید (۱۵۵/۲)\n(2) سورۃ الفتح (۲۵)\n(3) مسند ابی یعلی (۱۵۵۹/۳)"}],[9644,"§۹۶۸۱ ۔ ابو جمیلہ سلمی(1)\nنام سنین۔ امام بخاری رحمہ اللہ نے تعلیق میں ان کا ذکر کیا ہے کہ وہ فتح مکہ میں شریک تھے۔ پھر پھینکے ہوئے بچہ کے متعلق سیدنا عمر رضی اللہ عنہ کے ساتھ ان کا جو واقعہ پیش آیا اسے ذکر کیا اور یہ کہ اس کی پہچان کرنے والا سیدنا عمر رضی اللہ عنہ کے پاس آیا اور وہ نیک شخص تھا۔ امام مالک رحمہ اللہ نے اسے موصولاً ذکر کیا ہے۔ ناموں میں حرف سین کے دوران ان کا تذکرہ گزر چکا ہے۔ بقول بعض یہ ضمری ہیں۔ ابن حبان نے ان کے والد کا نام واقد بتایا ہے۔ بقول بعض: ان کے والد کا نام فرقد ہے ان کی ایک روایت حضرات شیخین میں امی سے بھی ہے۔ جبکہ ان سے زہری روایت کرتے ہیں کہ انہوں نے دور نبوی پایا ہے۔ آپ صلی اللہ علیہ وسلم کی معیت میں حج کیا ہے اور فتح مکہ کے سال آپ کے لشکر کے ساتھ نکلے تھے۔(2) ابن سعد فرماتے ہیں: ان کی کئی ایک احادیث ہیں، انہیں تابعین کے پہلے طبقہ میں ذکر کیا ہے، ایسا ہی قول عجلی کا ہے کہ وہ معتبر تابعی ہیں۔ ادھر بغوی نے ان میں اور سنین بن واقد میں فرق کیا جیسا کہ پہلے ناموں میں بھی اس کا ذکر ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۵) تجرید (۱۵۵/۲)\n(2) اسد الغابہ (۴۰۴/۴)"}],[9645,"§۹۶۸۲ ۔ ابو جندب عتقی(1)\nابو سعید بن یونس فرماتے ہیں: فتح مصر میں شرکت کی، انہیں شرف صحابیت حاصل ہے۔ جبکہ ان کی کوئی حدیث مروی نہیں۔","",{"fn":"(1) اسد الغابہ (۵۷۶۶) تجرید (۱۵۶/۲)"}],[9646,"§۹۶۸۳ ۔ ابو جندب فزاری(1)\nمطین اور باوردی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور دونوں نے نصر بن منصور، بحوالہ سہل الفزاری، جندب الفزاری سے انہوں نے اپنے والد سے روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنے صحابہ رضی اللہ عنہم سے ملتے تو (ہر وقت) ان سے مصافحہ نہ (ہاتھ ملاتے) کرتے تھے۔(2) باوردی نے اپنی بعض مغازی میں یہ اضافہ نقل کیا ہے ہمیں وہ لوگ ملے جن کی نماز رہ گئی تھی۔ ابن ابی حاتم بحوالہ والد فرماتے ہیں: اس کے راوی مجہول ہیں، ابو موسیٰ اور ابو نعیم نے مطین کے طریق سے ان کا ذکر کیا ہے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۷) تجرید (۱۵۶/۲)\n(2) المعجم الکبیر (۱۷۲۱/۲) مجمع الزوائد (۳۶/۸) جامع المسانید (۵۰۴/۱۳)"}],[9647,"§۹۶۸۴ ۔ ابو جندل بن سہیل(1)\nبن عمرو قرشی عامری، ان کے والد کے سوانح میں ان کے احوال گزر چکے ہیں۔ بقول بعض: ان کا نام عبد اللہ ہے، اسلام میں پہل کرنے والے خوش نصیبوں میں سے ایک ہیں۔ اور جن لوگوں کو اسلام لانے کے باعث اذیتیں(2) برداشت کرنا پڑیں، ان میں شامل ہیں۔ صحیح بخاری میں حدیبیہ کے قصہ میں ان کا ذکر ثابت ہے۔(3) معمر، زہری، عروہ، مسور بن مخرمہ اور مروان بن الحکم سے مروی ہے پھر وہ قصہ ذکر کیا۔ فرمایا: حدیبیہ کی شرائط لکھی جا رہی تھیں کہ اتنے میں بیڑیوں میں جکڑے ابو جندل آ کر مسلمانوں سے کہنے لگے: “میری حالت تم لوگ دیکھ رہے، اب بھی میں مشرکین کو دے دیا جاؤں حالانکہ میں مسلمان ہو کر آیا ہوں”۔ انہیں بہت اذیتیں دی گئیں، افسوس وہ عہد نامہ کی تکمیل سے پہلے پہنچے تھے مگر سرخروئی نہ ہو سکی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “مجھے اس کی اجازت دے دو”۔ سہیل بولے: یہ پہلی شرط ہے جس پر میں آپ سے مطالبہ کر رہا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہم نے ابھی تک تحریر مکمل نہیں کی۔ کہنے لگے: اللہ کی قسم! میں تحریر پر کسی قسم کا سمجھوتہ نہیں کروں گا۔ پھر انہیں ان کے والد سہیل بن عمرو لے کر واپس چلے گئے۔ پھر ان کے اسلام لانے کا قصہ ذکر کیا اور ابو بصیر کے ساتھ ساحلی علاقے میں جا ملے تھے، قریش کا جو دستہ وہاں سے گزرتا اسے پکڑ لیتے یہاں تک کہ خود ہی قریش نے آپ صلی اللہ علیہ وسلم کی طرف پیام بھیجا کہ انہیں اپنے ساتھ ملا لیں (یہ راہ کے کانٹے بنے پڑے ہیں)۔ بغوی نے یہ روایت بطریق عبد الرزاق طویل نقل کی ہے اور ابن اسحاق(4) نے بحوالہ زہری طوالت سے پیش کی ہے۔ صحیح میں سہل بن سعد رضی اللہ عنہ کی حدیث میں بھی ان کا تذکرہ ثابت ہے کہ صفین کے روز انہوں نے کہا: لوگو! اپنی رائے کو غلط سمجھو! ابو جندل کے روز مجھے یاد ہے اگر میرے بس میں ہوتا کہ میں رسول اللہ صلی اللہ علیہ وسلم کا فیصلہ ٹھکرا دوں تو اس کی تردید کر دیتا۔ یعنی ابو جندل کے بارے میں جو فیصلہ طے ہو گیا تھا۔ اہل مغازی نے شرکاء بدر میں ان کا ذکر کیا ہے۔ مشرکین کی طرف سے آئے تو تھے لیکن مسلمانوں سے جا ملے۔ بعد میں مشرکین نے گرفتار کر لیا اور طرح طرح کے مصائب و آلام سے دو چار ہوئے۔ جب فتح مکہ ہوئی تو انہوں نے ہی اپنے والد کے لیے امن مانگا تھا۔ اس بات کا تذکرہ واقدی نے حدیث سہیل سے کیا ہے۔ فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم مکہ میں داخل ہو گئے تو میں نے اپنا دروازہ بند کر لیا اور اپنے بیٹے عبد اللہ کو محمد (صلی اللہ علیہ وسلم) سے امان طلبی کے لیے روانہ کر دیا۔ پھر انہیں آپ صلی اللہ علیہ وسلم کے امان دینے والی حدیث ذکر کی۔ سیدنا ابو جندل رضی اللہ عنہ یمامہ میں، بعمر اڑتیس(۳۸) سال شہید ہوئے۔ اسی قول کو خلیفہ، ابن اسحاق اور ابو معشر وغیرہ نے اختیار کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۶۸) تجرید (۱۵۶/۲)\n(2) اسد الغابہ (۵۷۶۸)\n(3) کتاب المغازی (۴۱۸۰، ۴۱۸۱)\n(4) السیرۃ النبویۃ (۲۴۸/۳) (۲۵۰/۳)"}]])